-- Circuits (12)
insert into public.circuits (slug, featured, sort, content) values ('andasibe-rainforest-2d', true, 0, $MW${"slug": "andasibe-rainforest-2d", "tone": "forest", "title": {"en": "Andasibe Rainforest — Lemurs & Culture", "fr": "Forêt d'Andasibe — Lémuriens & Culture"}, "region": "Andasibe", "videos": [], "gallery": ["/images/andasibe-rainforest-2d-1.webp", "/images/andasibe-rainforest-2d-2.webp", "/images/andasibe-rainforest-2d-3.webp"], "summary": {"en": "A short, soulful escape into the eastern rainforest — meet the Indri, the world's largest lemur, and get up close on Lemur Island.", "fr": "Une échappée courte et intense dans la forêt tropicale de l'Est — rencontrez l'Indri, le plus grand lémurien du monde, et approchez les lémuriens sur l'Île aux Lémuriens."}, "category": "wildlife", "featured": true, "groupMax": 14, "included": {"en": ["Accommodation with breakfast", "Tourist taxes", "Park & reserve entrance fees", "Private vehicle with driver-guide", "Local guides for park visits"], "fr": ["Hébergement avec petit-déjeuner", "Taxes touristiques", "Droits d'entrée des parcs et réserves", "Véhicule privé avec chauffeur-guide", "Guides locaux pour les visites de parc"]}, "itinerary": [{"day": {"en": "Day 1", "fr": "Jour 1"}, "lat": -18.9068244, "lng": 47.5224114, "title": {"en": "Antananarivo → Andasibe (140 km, ~4h)", "fr": "Antananarivo → Andasibe (140 km, ~4h)"}, "waypoints": [{"lat": -18.799454, "lng": 47.4728224, "name": "Antananarivo"}], "description": {"en": "Morning pickup from your hotel in Tana and departure towards the eastern rainforest through beautiful landscapes. En route, visit Peyrieras Reserve — brilliantly coloured chameleons, geckos, snakes and crocodiles, a perfect introduction to the island's biodiversity. Reach Andasibe by afternoon and head to Vakona Private Reserve and its famous 'Lemur Island', where you meet Madagascar's most famous primates up close. As night falls, a guided night walk in the VOIMMA Reserve reveals mouse lemurs and tree frogs. Overnight at Relais de Mantadia or Mantadia Lodge.", "fr": "Prise en charge le matin à votre hôtel de Tana et départ vers la forêt tropicale de l'Est à travers de superbes paysages. En chemin, visite de la réserve de Peyrieras — caméléons aux couleurs éclatantes, geckos, serpents et crocodiles, une parfaite introduction à la biodiversité de l'île. Arrivée à Andasibe dans l'après-midi, puis découverte de la réserve privée de Vakona et sa fameuse « Île aux Lémuriens », où vous approchez de près les primates les plus célèbres de Madagascar. À la tombée de la nuit, une marche nocturne guidée dans la réserve de VOIMMA dévoile microcèbes et grenouilles arboricoles. Nuit au Relais de Mantadia ou au Mantadia Lodge."}}, {"day": {"en": "Day 2", "fr": "Jour 2"}, "lat": -18.9388336, "lng": 48.4311889, "title": {"en": "Analamazaotra Park → return to Antananarivo", "fr": "Parc d'Analamazaotra → retour à Antananarivo"}, "waypoints": [{"lat": -18.9388336, "lng": 48.4311835, "name": "Analamazaotra"}, {"lat": -18.799454, "lng": 47.4728224, "name": "Antananarivo"}], "description": {"en": "After breakfast, a guided trek in Analamazaotra Special Reserve, home to the Indri, the world's largest lemur — observe these extraordinary primates in their natural habitat, their echoing calls resonating through the misty forest. Then visit Andasibe Village to experience daily life and traditions, from craftsmanship to local markets. Enjoy lunch before the drive back to Antananarivo.", "fr": "Après le petit-déjeuner, randonnée guidée dans la réserve spéciale d'Analamazaotra, refuge de l'Indri, le plus grand lémurien du monde — observez ces primates extraordinaires dans leur habitat naturel, leurs cris puissants résonnant dans la forêt brumeuse. Puis visite du village d'Andasibe à la rencontre de la vie quotidienne et des traditions locales, de l'artisanat aux marchés. Déjeuner avant le retour vers Antananarivo."}}], "priceFrom": 335, "bestSeason": {"en": "All year round", "fr": "Toute l'année"}, "difficulty": 1, "highlights": {"en": ["Home of Madagascar's reptiles", "Hear the Indri's call", "Explore famous Lemur Island", "Immerse in local culture"], "fr": ["Le royaume des reptiles de Madagascar", "Entendre l'appel de l'Indri", "L'Île aux Lémuriens", "Immersion dans la culture locale"]}, "description": {"en": "Embark on an unforgettable two-day adventure to Andasibe National Park, one of Madagascar's most renowned natural treasures. Nestled in the lush eastern rainforest, this park is a haven for biodiversity, home to endemic flora and fauna. Immerse yourself in a preserved ecosystem where lemurs leap through the canopy, chameleons blend into their surroundings and rare birds call from the treetops. The highlight: the mesmerising call of the Indri, the largest living lemur, echoing through the forest.", "fr": "Vivez une aventure inoubliable de deux jours au parc national d'Andasibe, l'un des trésors naturels les plus réputés de Madagascar. Niché dans la luxuriante forêt tropicale de l'Est, ce parc est un havre de biodiversité, riche d'une flore et d'une faune endémiques. Immergez-vous dans un écosystème préservé où les lémuriens bondissent dans la canopée, les caméléons se fondent dans leur environnement et les oiseaux rares chantent depuis la cime des arbres. Point d'orgue : l'appel envoûtant de l'Indri, le plus grand lémurien vivant, résonnant à travers la forêt."}, "notIncluded": {"en": ["Accommodation in Antananarivo", "Tips and personal expenses", "Lunch and dinner during the tour"], "fr": ["Hébergement à Antananarivo", "Pourboires et dépenses personnelles", "Déjeuners et dîners pendant le circuit"]}, "durationDays": 2, "macroRegions": ["east"]}$MW$::jsonb) on conflict (slug) do update set featured=excluded.featured, sort=excluded.sort, content=excluded.content;
insert into public.circuits (slug, featured, sort, content) values ('baobabs-tsingy-rainforest-9d', true, 1, $MW${"slug": "baobabs-tsingy-rainforest-9d", "tone": "sunset", "title": {"en": "Baobabs, Tsingy & Rainforest", "fr": "Baobabs, Tsingy & Forêt tropicale"}, "region": "Morondava · Bemaraha · Andasibe", "gallery": ["/images/baobabs-tsingy-rainforest-9d-1.webp", "/images/baobabs-tsingy-rainforest-9d-2.webp", "/images/baobabs-tsingy-rainforest-9d-3.webp"], "summary": {"en": "Nine days across western and eastern Madagascar: the Avenue of the Baobabs at sunset, the UNESCO Tsingy de Bemaraha, and the Indri lemurs of Andasibe.", "fr": "Neuf jours entre l'ouest et l'est de Madagascar : l'Allée des Baobabs au coucher du soleil, les Tsingy de Bemaraha classés UNESCO et les indris d'Andasibe."}, "category": "adventure", "featured": true, "groupMax": 14, "included": {"en": ["Accommodation with breakfast", "Air-conditioned 4WD including fuel", "Guide", "Domestic flights", "Entry fees to all mentioned parks", "Local guides", "Ferry crossings"], "fr": ["Hébergement avec petit-déjeuner", "4×4 climatisé, carburant inclus", "Guide", "Vols intérieurs", "Droits d'entrée de tous les parcs cités", "Guides locaux", "Traversées en bac"]}, "itinerary": [{"day": {"en": "Day 1", "fr": "Jour 1"}, "title": {"en": "Arrival at Antananarivo (TNR)", "fr": "Arrivée à Antananarivo (TNR)"}, "description": {"en": "Our agent greets you at the airport and helps with anything you need — SIM card, currency exchange — before transferring you to your hotel. Overnight at Sakamanga Hotel.", "fr": "Notre agent vous accueille à l'aéroport et vous aide pour tout besoin — carte SIM, change — avant de vous transférer à votre hôtel. Nuit à l'hôtel Sakamanga."}}, {"day": {"en": "Day 2", "fr": "Jour 2"}, "title": {"en": "Antananarivo → Morondava → Kirindy", "fr": "Antananarivo → Morondava → Kirindy"}, "description": {"en": "Fly to Morondava, meet your driver and head into town for lunch, then on to Kirindy Reserve with a photo stop at the iconic Avenue of the Baobabs. After check-in, a night walk to spot fat-tailed dwarf lemurs and grey mouse lemurs. Overnight at Relais du Kirindy.", "fr": "Vol vers Morondava, accueil par votre chauffeur et déjeuner en ville, puis route vers la réserve de Kirindy avec un arrêt photo à la célèbre Allée des Baobabs. Après l'installation, marche nocturne à la recherche du microcèbe roux et du microcèbe gris. Nuit au Relais du Kirindy."}}, {"day": {"en": "Day 3", "fr": "Jour 3"}, "title": {"en": "Kirindy → Belo → Bekopaka (180 km, 7h)", "fr": "Kirindy → Belo → Bekopaka (180 km, 7h)"}, "description": {"en": "Morning visit of Kirindy Reserve, famous for the fossa, Madagascar's largest predator; by day, watch Verreaux's sifakas and red-fronted lemurs leap between the trees. Drive on through baobab forests and red earth, cross the Tsiribihina river by ferry to Belo for lunch, then four more hours on the mud road to Bekopaka. Overnight at Soleil des Tsingy.", "fr": "Visite matinale de la réserve de Kirindy, réputée pour le fossa, le plus grand prédateur de Madagascar ; en journée, observez les propithèques de Verreaux et les lémuriens à front roux bondir entre les arbres. Route à travers les forêts de baobabs et la terre rouge, traversée du fleuve Tsiribihina en bac jusqu'à Belo pour le déjeuner, puis quatre heures de piste jusqu'à Bekopaka. Nuit au Soleil des Tsingy."}}, {"day": {"en": "Day 4", "fr": "Jour 4"}, "title": {"en": "Grand Tsingy", "fr": "Grand Tsingy"}, "description": {"en": "Drive to the start of the Grands Tsingy (17 km of bumpy track, 1–2h). The roughly 4-hour 'Andamozavakay' circuit is a slow-paced observational walk — no particular fitness required, but not ideal for those prone to vertigo. Explore secondary forest, caves (bring a headlamp), panoramic viewpoints and a suspension bridge, safely harnessed. Overnight at Soleil des Tsingy.", "fr": "Route jusqu'au départ des Grands Tsingy (17 km de piste cahoteuse, 1 à 2h). Le circuit « Andamozavakay », d'environ 4h, est une marche d'observation au rythme tranquille — sans condition physique particulière, mais déconseillée en cas de vertige. Forêts secondaires, grottes (prévoir une lampe frontale), points de vue panoramiques et pont suspendu, harnaché en toute sécurité. Nuit au Soleil des Tsingy."}}, {"day": {"en": "Day 5", "fr": "Jour 5"}, "title": {"en": "Bekopaka → Morondava (200 km, 9h)", "fr": "Bekopaka → Morondava (200 km, 9h)"}, "description": {"en": "Head back south by 4WD and ferry (about 9 hours). Pass the Sakalava tombs, known for their unusual paintings and carvings, and stop again at the Avenue of the Baobabs for a spectacular sunset — the perfect photo moment. Overnight in Morondava at Baobab Café Hotel.", "fr": "Retour vers le sud en 4×4 et bac (environ 9h). Passage devant les tombeaux Sakalava, réputés pour leurs peintures et sculptures singulières, et nouvel arrêt à l'Allée des Baobabs pour un coucher de soleil spectaculaire — le moment photo parfait. Nuit à Morondava, au Baobab Café Hotel."}}, {"day": {"en": "Day 6", "fr": "Jour 6"}, "title": {"en": "Morondava → Antananarivo (flight) → Andasibe", "fr": "Morondava → Antananarivo (vol) → Andasibe"}, "description": {"en": "Fly back to Antananarivo, then drive to Andasibe through scenic villages, golden grasslands and lush rice paddies, discovering colourful clay houses, local markets and authentic Malagasy culture. Overnight at Relais de Mantadia.", "fr": "Vol retour vers Antananarivo, puis route vers Andasibe à travers villages pittoresques, prairies dorées et rizières verdoyantes, à la découverte des maisons de brique colorées, des marchés locaux et de la culture malgache authentique. Nuit au Relais de Mantadia."}}, {"day": {"en": "Day 7", "fr": "Jour 7"}, "title": {"en": "Andasibe National Park", "fr": "Parc national d'Andasibe"}, "description": {"en": "Guided morning trek in Analamazaotra Reserve to find the Indri, the world's largest lemur, its calls echoing through the misty forest. In the afternoon, meet friendly lemurs on Lemur Island at Vakona and watch crocodiles from safe platforms. After dark, a guided night walk in VOIMMA reveals mouse lemurs and tree frogs. Overnight at Relais de Mantadia.", "fr": "Randonnée guidée le matin dans la réserve d'Analamazaotra à la rencontre de l'Indri, le plus grand lémurien du monde, dont les cris résonnent dans la forêt brumeuse. L'après-midi, approche des lémuriens sur l'Île aux Lémuriens de Vakona et observation des crocodiles depuis des plateformes sécurisées. À la nuit tombée, marche nocturne guidée à VOIMMA (microcèbes, grenouilles arboricoles). Nuit au Relais de Mantadia."}}, {"day": {"en": "Day 8", "fr": "Jour 8"}, "title": {"en": "Andasibe → Antananarivo (140 km, 4h)", "fr": "Andasibe → Antananarivo (140 km, 4h)"}, "description": {"en": "Drive back to Antananarivo past the Angavo mountains and lively market villages — great photo stops. On arrival, a guided city walk through vibrant streets and markets, ending at the hilltop Manjakamiadana, the former royal palace with panoramic views over the capital. Overnight at Sakamanga Hotel.", "fr": "Retour vers Antananarivo en longeant les massifs de l'Angavo et des villages animés de marchés colorés — parfaits pour la photo. À l'arrivée, visite guidée à pied de la ville, de ses rues vivantes et de ses marchés, jusqu'au palais royal de Manjakamiadana, perché, offrant une vue panoramique sur la capitale. Nuit à l'hôtel Sakamanga."}}, {"day": {"en": "Day 9", "fr": "Jour 9"}, "title": {"en": "International departure", "fr": "Départ international"}, "description": {"en": "Your tour comes to an end. We arrange your transfer back to Ivato Airport. Safe travels, with cherished memories of Madagascar.", "fr": "Votre circuit touche à sa fin. Nous organisons votre transfert vers l'aéroport d'Ivato. Bon retour, avec de précieux souvenirs de Madagascar."}}], "priceFrom": 2170, "bestSeason": {"en": "May to November", "fr": "De mai à novembre"}, "difficulty": 3, "highlights": {"en": ["Encounter the elusive fossa", "Trek the Tsingy de Bemaraha", "A magical baobab sunset", "Into the Andasibe rainforest"], "fr": ["Rencontrer l'insaisissable fossa", "Explorer les Tsingy de Bemaraha", "Coucher de soleil magique sur les baobabs", "Au cœur de la forêt d'Andasibe"]}, "description": {"en": "A thrilling 9-day journey through western and eastern Madagascar, exploring iconic landscapes, unique wildlife and vibrant culture. Fly to Morondava and visit Kirindy Reserve, home to the elusive fossa. Cross rugged terrain to Bekopaka to marvel at the UNESCO-listed Tsingy de Bemaraha, with its limestone pinnacles, caves and suspension bridges. Witness the legendary sunset at the Avenue of the Baobabs before returning to Antananarivo and continuing to the Andasibe rainforest to trek among Indri lemurs and explore nocturnal wildlife on guided night walks.", "fr": "Un voyage palpitant de 9 jours à travers l'ouest et l'est de Madagascar, à la découverte de paysages iconiques, d'une faune unique et d'une culture vibrante. Vol vers Morondava et visite de la réserve de Kirindy, refuge de l'insaisissable fossa. Franchissez des pistes accidentées jusqu'à Bekopaka pour admirer les Tsingy de Bemaraha, classés UNESCO, avec leurs aiguilles calcaires, leurs grottes et leurs ponts suspendus. Assistez au coucher de soleil légendaire sur l'Allée des Baobabs avant de revenir à Antananarivo, puis de rejoindre la forêt d'Andasibe pour marcher parmi les indris et partir à la rencontre de la faune nocturne."}, "notIncluded": {"en": ["Drinks", "Tips and personal purchases", "All meals (lunches and dinners)", "Travel insurance and visa", "International flights"], "fr": ["Boissons", "Pourboires et achats personnels", "Tous les repas (déjeuners et dîners)", "Assurance voyage et visa", "Vols internationaux"]}, "durationDays": 9, "macroRegions": ["west", "east"]}$MW$::jsonb) on conflict (slug) do update set featured=excluded.featured, sort=excluded.sort, content=excluded.content;
insert into public.circuits (slug, featured, sort, content) values ('madagascar-road-trip-10d', false, 2, $MW${"slug": "madagascar-road-trip-10d", "tone": "highland", "title": {"en": "Road Trip — Lemurs, Landscapes & Adventure", "fr": "Road trip — Lémuriens, paysages & aventure"}, "region": "Tana → Ifaty (RN7)", "gallery": ["/images/madagascar-road-trip-10d-1.webp", "/images/madagascar-road-trip-10d-2.webp", "/images/madagascar-road-trip-10d-3.webp"], "summary": {"en": "Ten days down the legendary RN7: highland crafts, the rainforest of Ranomafana, ring-tailed lemurs at Anja, the canyons of Isalo and the lagoon of Ifaty.", "fr": "Dix jours sur la légendaire RN7 : artisanat des hautes terres, forêt de Ranomafana, makis catta d'Anja, canyons de l'Isalo et lagon d'Ifaty."}, "category": "nature", "featured": false, "groupMax": 14, "included": {"en": ["Air-conditioned 4WD transport", "Experienced driver-guide", "Accommodation in double/twin with breakfast", "Domestic flight", "Entry fees to all mentioned parks", "Compulsory local park guides", "Driver & guide's board and lodging", "Taxes"], "fr": ["Transport en 4×4 climatisé", "Chauffeur-guide expérimenté", "Hébergement en chambre double/twin avec petit-déjeuner", "Vol intérieur", "Droits d'entrée de tous les parcs cités", "Guides locaux obligatoires dans les parcs", "Hébergement et repas du chauffeur et du guide", "Taxes"]}, "itinerary": [{"day": {"en": "Day 1", "fr": "Jour 1"}, "title": {"en": "Arrival at Antananarivo", "fr": "Arrivée à Antananarivo"}, "description": {"en": "Our agent greets you at the airport, helps with a SIM card and currency exchange, and transfers you to your hotel. Overnight at Sakamanga Hotel.", "fr": "Notre agent vous accueille à l'aéroport, vous aide pour la carte SIM et le change, et vous transfère à votre hôtel. Nuit à l'hôtel Sakamanga."}}, {"day": {"en": "Day 2", "fr": "Jour 2"}, "title": {"en": "Antananarivo → Antsirabe (170 km, 4h)", "fr": "Antananarivo → Antsirabe (170 km, 4h)"}, "description": {"en": "Drive south to Antsirabe along a scenic route of villages and rice fields. Stop at Ambatolampy, known for its aluminium craftsmanship, then after lunch explore Lakes Andraikiba and Tritriva — the latter perfect for a refreshing swim. Overnight at Ecolodge Chambre du Voyageur.", "fr": "Route vers le sud jusqu'à Antsirabe, à travers villages et rizières. Arrêt à Ambatolampy, réputée pour son artisanat de l'aluminium, puis après le déjeuner, découverte des lacs Andraikiba et Tritriva — ce dernier parfait pour une baignade rafraîchissante. Nuit à l'Ecolodge Chambre du Voyageur."}}, {"day": {"en": "Day 3", "fr": "Jour 3"}, "title": {"en": "Antsirabe → Ranomafana (250 km, 7h)", "fr": "Antsirabe → Ranomafana (250 km, 7h)"}, "description": {"en": "Tour Antsirabe by rickshaw — the railway station, Hôtel des Thermes and craft workshops — then continue to Ambositra, capital of Malagasy woodcraft, for lunch. In the afternoon, descend from the highlands to the lush east and Ranomafana, with a night walk at the forest edge to spot nocturnal species. Overnight at Hotel Thermal.", "fr": "Découverte d'Antsirabe en pousse-pousse — la gare, l'Hôtel des Thermes et les ateliers d'artisans — puis route vers Ambositra, capitale du travail du bois malgache, pour le déjeuner. L'après-midi, descente des hautes terres vers l'est luxuriant et Ranomafana, avec une marche nocturne en lisière de forêt à la recherche des espèces nocturnes. Nuit à l'Hotel Thermal."}}, {"day": {"en": "Day 4", "fr": "Jour 4"}, "title": {"en": "Ranomafana National Park", "fr": "Parc national de Ranomafana"}, "description": {"en": "Explore Ranomafana — 'hot water' in Malagasy, for its springs. Protected since 1986, it shelters the rare golden bamboo lemur, 12 lemur species in all, and 30 endemic birds. Follow forest trails such as Varibolomena in search of bamboo lemurs and Milne-Edwards' sifakas. Overnight at Hotel Thermal.", "fr": "Exploration de Ranomafana — « eau chaude » en malgache, pour ses sources. Protégé depuis 1986, il abrite le rare lémurien à bambou doré, 12 espèces de lémuriens au total et 30 oiseaux endémiques. Suivez des sentiers comme le Varibolomena à la recherche des lémuriens à bambou et des propithèques de Milne-Edwards. Nuit à l'Hotel Thermal."}}, {"day": {"en": "Day 5", "fr": "Jour 5"}, "title": {"en": "Ranomafana → Anja → Ranohira (360 km, 7h)", "fr": "Ranomafana → Anja → Ranohira (360 km, 7h)"}, "description": {"en": "Drive the famed RN7. Stop in Fianarantsoa, Betsileo capital of colonial architecture and lively markets, then Ambalavao for its Antemoro paper factory and zebu market. At Anja Reserve, meet ring-tailed lemurs in the wild before crossing the scenic Ihorombe plateau to Ranohira. Overnight at Le Jardin du Roy.", "fr": "Route sur la célèbre RN7. Arrêt à Fianarantsoa, capitale betsileo à l'architecture coloniale et aux marchés animés, puis à Ambalavao pour sa fabrique de papier Antemoro et son marché aux zébus. À la réserve d'Anja, rencontre avec les makis catta en liberté avant de traverser le plateau de l'Ihorombe jusqu'à Ranohira. Nuit au Jardin du Roy."}}, {"day": {"en": "Day 6", "fr": "Jour 6"}, "title": {"en": "Isalo National Park", "fr": "Parc national de l'Isalo"}, "description": {"en": "A full day among the canyons and oases of Isalo. Hike through dramatic landscapes to natural pools and waterfalls, follow the 'Piscine Bleue et Noire' trails and their unique wildlife, and end with the mesmerising sunset over the famous Window of Isalo. Overnight at Le Jardin du Roy.", "fr": "Une journée entière dans les canyons et oasis de l'Isalo. Randonnée à travers des paysages spectaculaires vers des piscines naturelles et des cascades, sentiers de la « Piscine Bleue et Noire » et leur faune unique, puis coucher de soleil envoûtant sur la célèbre Fenêtre de l'Isalo. Nuit au Jardin du Roy."}}, {"day": {"en": "Day 7", "fr": "Jour 7"}, "title": {"en": "Ranohira → Zombitse → Ifaty (280 km, 5h)", "fr": "Ranohira → Zombitse → Ifaty (280 km, 5h)"}, "description": {"en": "Journey to the coast, passing the sapphire town of Ilakaka and the baobabs of the south-west. Explore Zombitse National Park and see traditional Mahafaly and Antandroy tombs before reaching the tranquil fishing village of Ifaty. Overnight at La Bella Donna.", "fr": "Route vers la côte, en passant par Ilakaka la ville du saphir et les baobabs du sud-ouest. Découverte du parc national de Zombitse et des tombeaux traditionnels mahafaly et antandroy avant d'atteindre le paisible village de pêcheurs d'Ifaty. Nuit à La Bella Donna."}}, {"day": {"en": "Day 8", "fr": "Jour 8"}, "title": {"en": "Ifaty — lagoon day", "fr": "Ifaty — journée lagon"}, "description": {"en": "A relaxing beach day: stroll golden sands as fishing pirogues drift by, swim in the reef-protected lagoon, savour fresh seafood, and end with a sunset pirogue ride. Overnight at La Bella Donna.", "fr": "Journée détente à la plage : promenade sur le sable doré au passage des pirogues de pêche, baignade dans le lagon protégé par le récif, déjeuner de fruits de mer et balade en pirogue au coucher du soleil. Nuit à La Bella Donna."}}, {"day": {"en": "Day 9", "fr": "Jour 9"}, "title": {"en": "Ifaty → Toliara → Antananarivo (flight)", "fr": "Ifaty → Toliara → Antananarivo (vol)"}, "description": {"en": "Transfer to Toliara airport and fly to Antananarivo; transfer to your hotel. Overnight at Sakamanga Hotel.", "fr": "Transfert à l'aéroport de Toliara et vol vers Antananarivo ; transfert à votre hôtel. Nuit à l'hôtel Sakamanga."}}, {"day": {"en": "Day 10", "fr": "Jour 10"}, "title": {"en": "International departure", "fr": "Départ international"}, "description": {"en": "Your tour comes to an end. We arrange your transfer to Ivato Airport. Safe travels!", "fr": "Votre circuit s'achève. Nous organisons votre transfert vers l'aéroport d'Ivato. Bon retour !"}}], "priceFrom": 1850, "bestSeason": {"en": "All year round", "fr": "Toute l'année"}, "difficulty": 1, "highlights": {"en": ["Discover Isalo Park", "Explore Ranomafana rainforest", "Home of the dancing sifakas", "Ring-tailed lemurs at Anja"], "fr": ["Découvrir le parc de l'Isalo", "La forêt de Ranomafana", "Le pays des sifakas danseurs", "Makis catta à Anja"]}, "description": {"en": "An extraordinary 10-day expedition through the landscapes and biodiversity of Madagascar. From Antananarivo, drive to Antsirabe through villages and rice fields, stopping in Ambositra to discover Malagasy woodcraft. Explore Ranomafana National Park, sanctuary of the endangered golden bamboo lemur, then travel via Fianarantsoa and Ambalavao to the Anja Reserve for a close encounter with ring-tailed lemurs. Hike the canyons and natural pools of Isalo, and reach the coast at Ifaty via Zombitse National Park, home to dancing sifakas and ancient baobabs.", "fr": "Une expédition extraordinaire de 10 jours à travers les paysages et la biodiversité de Madagascar. D'Antananarivo, route vers Antsirabe entre villages et rizières, avec un arrêt à Ambositra pour découvrir l'art du bois malgache. Explorez le parc national de Ranomafana, sanctuaire du lémurien à bambou doré menacé, puis rejoignez, via Fianarantsoa et Ambalavao, la réserve d'Anja pour une rencontre rapprochée avec les makis catta. Randonnez dans les canyons et vasques naturelles de l'Isalo, et gagnez la côte à Ifaty en passant par le parc national de Zombitse, royaume des sifakas danseurs et des baobabs centenaires."}, "notIncluded": {"en": ["Drinks", "Tips and personal purchases", "All meals (lunches and dinners)", "Travel insurance and visa", "International flights"], "fr": ["Boissons", "Pourboires et achats personnels", "Tous les repas (déjeuners et dîners)", "Assurance voyage et visa", "Vols internationaux"]}, "durationDays": 10, "macroRegions": ["highlands", "south"]}$MW$::jsonb) on conflict (slug) do update set featured=excluded.featured, sort=excluded.sort, content=excluded.content;
insert into public.circuits (slug, featured, sort, content) values ('birding-photography-24d', false, 3, $MW${"slug": "birding-photography-24d", "tone": "forest", "title": {"en": "Immersive Birding & Photography Journey", "fr": "Voyage photo & ornithologie immersif"}, "region": "Ifaty · Ranomafana · Ankarafantsika · Andasibe", "gallery": ["/images/birding-photography-24d-1.webp", "/images/birding-photography-24d-2.webp", "/images/birding-photography-24d-3.webp"], "summary": {"en": "A 24-day birding and photography expedition for serious enthusiasts — from the spiny forests of Ifaty to the hidden wetlands of Bemanevika, tracking Madagascar's rarest endemics.", "fr": "Une expédition photo et ornithologie de 24 jours pour passionnés — des forêts épineuses d'Ifaty aux marais secrets de Bemanevika, à la recherche des endémiques les plus rares de Madagascar."}, "category": "wildlife", "featured": false, "groupMax": 8, "included": {"en": ["Air-conditioned 4WD including fuel", "English-speaking guide", "Accommodation in double/twin with breakfast", "Domestic flights", "Entry fees to all mentioned parks", "Local park guides", "Driver & guide's board and lodging", "Taxes"], "fr": ["4×4 climatisé, carburant inclus", "Guide anglophone", "Hébergement en chambre double/twin avec petit-déjeuner", "Vols intérieurs", "Droits d'entrée de tous les parcs cités", "Guides locaux dans les parcs", "Hébergement et repas du chauffeur et du guide", "Taxes"]}, "itinerary": [{"day": {"en": "Day 1", "fr": "Jour 1"}, "title": {"en": "Arrival at Antananarivo", "fr": "Arrivée à Antananarivo"}, "description": {"en": "Our agent greets you at the airport, assists with a SIM card and currency exchange, and transfers you to your hotel. Overnight at Le Grand Mellis or similar.", "fr": "Notre agent vous accueille à l'aéroport, vous aide pour la carte SIM et le change, et vous transfère à votre hôtel. Nuit au Grand Mellis ou similaire."}}, {"day": {"en": "Day 2", "fr": "Jour 2"}, "title": {"en": "Antananarivo → Toliara → Ifaty (flight + 1h)", "fr": "Antananarivo → Toliara → Ifaty (vol + 1h)"}, "description": {"en": "Fly to Toliara and transfer to Ifaty. Begin birding in the spiny forests of baobabs and octopus trees — a unique habitat for sought-after endemics such as the Long-tailed Ground Roller, Subdesert Mesite, Sickle-billed Vanga and Red-capped Coua. Overnight at La Bella Donna or similar.", "fr": "Vol vers Toliara et transfert à Ifaty. Premières observations dans les forêts épineuses de baobabs et d'« arbres pieuvres » — un habitat unique pour des endémiques recherchés : rollier à longue queue, mésite monias, vanga à bec en faucille et coua à tête rousse. Nuit à La Bella Donna ou similaire."}}, {"day": {"en": "Day 3", "fr": "Jour 3"}, "title": {"en": "Andatabo & Ifaty", "fr": "Andatabo & Ifaty"}, "description": {"en": "Morning at Andatabo Forest ('La Table'), rich in aloes and euphorbias, seeking Verreaux's Coua and Red-shouldered Vanga. Back near Ifaty, explore the Mangily spiny forest and its baobabs, then a guided night walk for the Rainforest Scops Owl and grey mouse-lemur. Overnight at La Bella Donna.", "fr": "Matinée dans la forêt d'Andatabo (« La Table »), riche en aloès et euphorbes, à la recherche du coua de Verreaux et du vanga à épaulettes rousses. De retour vers Ifaty, exploration de la forêt épineuse de Mangily et de ses baobabs, puis marche nocturne guidée (petit-duc de forêt, microcèbe gris). Nuit à La Bella Donna."}}, {"day": {"en": "Day 4", "fr": "Jour 4"}, "title": {"en": "Ifaty → Zombitse → Ranohira (300 km, 6h)", "fr": "Ifaty → Zombitse → Ranohira (300 km, 6h)"}, "description": {"en": "Head to Zombitse-Vohibasia National Park, a dry deciduous forest and Important Bird Area with nearly 100 species — targets include Appert's Tetraka, Cuckoo Roller, Rufous Vanga and several couas. After a picnic lunch, continue to Isalo, watching for Madagascan Partridge and Malagasy Harrier. Overnight at Hotel H1 Isalo.", "fr": "Route vers le parc national de Zombitse-Vohibasia, forêt sèche décidue et zone importante pour les oiseaux (près de 100 espèces) — cibles : tétraka d'Appert, courol vouroudriou, vanga roux et plusieurs couas. Après un pique-nique, route vers l'Isalo en guettant la perdrix et le busard de Madagascar. Nuit à l'Hotel H1 Isalo."}}, {"day": {"en": "Day 5", "fr": "Jour 5"}, "title": {"en": "Isalo National Park", "fr": "Parc national de l'Isalo"}, "description": {"en": "Though not a top birding site, Isalo holds over 80 species, 70% endemic — Madagascar Bee-eater, Benson's Rock Thrush, Crested Drongo — alongside stunning canyon panoramas and ring-tailed lemurs. Overnight at Hotel H1 Isalo.", "fr": "Bien que secondaire pour l'ornithologie, l'Isalo compte plus de 80 espèces, 70 % endémiques — guêpier de Madagascar, monticole de Benson, drongo huppé — avec de superbes panoramas de canyons et des makis catta. Nuit à l'Hotel H1 Isalo."}}, {"day": {"en": "Day 6", "fr": "Jour 6"}, "title": {"en": "Ranohira → Ranomafana (420 km, 8h)", "fr": "Ranohira → Ranomafana (420 km, 8h)"}, "description": {"en": "Cross the Ihorombe plateau (Malagasy Harrier, Madagascan Buzzard) and stop at Anja Community Reserve, home to the island's densest population of ring-tailed lemurs. Continue via Fianarantsoa down to Ranomafana for a guided night walk (golden-brown mouse-lemur, chameleons). Overnight in Ranomafana.", "fr": "Traversée du plateau de l'Ihorombe (busard, buse de Madagascar) et arrêt à la réserve communautaire d'Anja, plus forte concentration de makis catta de l'île. Descente via Fianarantsoa jusqu'à Ranomafana pour une marche nocturne guidée (microcèbe roux, caméléons). Nuit à Ranomafana."}}, {"day": {"en": "Day 7", "fr": "Jour 7"}, "title": {"en": "Ranomafana National Park", "fr": "Parc national de Ranomafana"}, "description": {"en": "One of Madagascar's finest birding parks (over 115 species, 77% endemic). Targets include Yellow-bellied and Common Sunbird-Asity, Brown Mesite, Pollen's Vanga, Scaly Ground Roller and Velvet Asity, with lunch back at the lodge between morning and afternoon outings. Overnight at Centrest Séjour.", "fr": "L'un des meilleurs parcs ornithologiques de Madagascar (plus de 115 espèces, 77 % endémiques). Cibles : philépitte veloutée, mésite unicolore, vanga de Pollen, brachyptérolle écaillé, entre autres. Déjeuner au lodge entre les sorties du matin et de l'après-midi. Nuit au Centrest Séjour."}}, {"day": {"en": "Day 8", "fr": "Jour 8"}, "title": {"en": "Ranomafana National Park", "fr": "Parc national de Ranomafana"}, "description": {"en": "A second full day on the park trails, seeking raptors (Henst's Goshawk, Frances's Sparrowhawk), ground rollers, vangas, Blue Coua, Madagascan Pygmy Kingfisher and many endemic warblers and sunbirds. Overnight at Centrest Séjour.", "fr": "Deuxième journée complète sur les sentiers du parc, à la recherche des rapaces (autour de Henst, épervier de Frances), brachyptérolles, vangas, coua bleu, martin-pêcheur pygmée et de nombreux endémiques. Nuit au Centrest Séjour."}}, {"day": {"en": "Day 9", "fr": "Jour 9"}, "title": {"en": "Ranomafana → Antsirabe (280 km, 7h)", "fr": "Ranomafana → Antsirabe (280 km, 7h)"}, "description": {"en": "A final forest trail at dawn, then north to Ambositra — the woodcarving capital — for lunch, and on to Antsirabe in the highlands, scanning rivers for herons and Madagascan Wagtail. Overnight at Ecolodge Chambre du Voyageur.", "fr": "Un dernier sentier forestier à l'aube, puis route vers Ambositra — capitale de la sculpture sur bois — pour le déjeuner, et continuation vers Antsirabe, dans les hautes terres, en guettant hérons et bergeronnette de Madagascar. Nuit à l'Ecolodge Chambre du Voyageur."}}, {"day": {"en": "Day 10", "fr": "Jour 10"}, "title": {"en": "Antsirabe → Antananarivo → Mahajanga (flight)", "fr": "Antsirabe → Antananarivo → Mahajanga (vol)"}, "description": {"en": "Cross the highland plateau back to Antananarivo with birding stops, then a flight to Mahajanga on the north-west coast. Overnight at Coco Lodge.", "fr": "Traversée du plateau des hautes terres jusqu'à Antananarivo, avec arrêts d'observation, puis vol vers Mahajanga, sur la côte nord-ouest. Nuit au Coco Lodge."}}, {"day": {"en": "Day 11", "fr": "Jour 11"}, "title": {"en": "Mahajanga → Ankarafantsika (125 km, 3h)", "fr": "Mahajanga → Ankarafantsika (125 km, 3h)"}, "description": {"en": "Drive to Ankarafantsika, stopping at Lake Amboromalandy and rice fields for Madagascar Jacana, Malagasy Pond Heron and Humblot's Heron. Around the lodge and Lake Ravelobe, watch for the Madagascar Fish-Eagle; a night walk follows for nightjars, owls and nocturnal lemurs. Overnight at Tia Asity Lodge.", "fr": "Route vers Ankarafantsika, avec arrêts au lac Amboromalandy et dans les rizières (jacana, crabier blanc, héron de Humblot). Autour du lodge et du lac Ravelobe, guet du pygargue de Madagascar ; marche nocturne (engoulevents, chouettes, lémuriens nocturnes). Nuit au Tia Asity Lodge."}}, {"day": {"en": "Day 12", "fr": "Jour 12"}, "title": {"en": "Ankarafantsika National Park", "fr": "Parc national d'Ankarafantsika"}, "description": {"en": "A full day across the park's sections, a stronghold for endangered endemics — White-breasted Mesite, Schlegel's Asity, Van Dam's and Sickle-billed Vanga, Coquerel's Coua — plus Madagascar Ibis and Fish-Eagle, and Humblot's Heron and Madagascar Jacana at the dam. Overnight at Tia Asity Lodge.", "fr": "Journée complète dans les différentes sections du parc, bastion d'endémiques menacés — mésite à poitrine blanche, philépitte de Schlegel, vangas de Van Dam et à bec en faucille, coua de Coquerel — ainsi qu'ibis et pygargue de Madagascar, et héron de Humblot et jacana au barrage. Nuit au Tia Asity Lodge."}}, {"day": {"en": "Day 13", "fr": "Jour 13"}, "title": {"en": "Ankarafantsika → Antsohihy (340 km, 10h)", "fr": "Ankarafantsika → Antsohihy (340 km, 10h)"}, "description": {"en": "A long drive north via Ambondromamy across open, palm-dotted grasslands (satrana fan palms) to the town of Antsohihy. Overnight at Hotel Sofia Bellevue.", "fr": "Longue route vers le nord via Ambondromamy, à travers des savanes ouvertes ponctuées de palmiers satrana, jusqu'à la ville d'Antsohihy. Nuit à l'Hotel Sofia Bellevue."}}, {"day": {"en": "Day 14", "fr": "Jour 14"}, "title": {"en": "Antsohihy → Bealanana → Bemanevika (200 km, 9h)", "fr": "Antsohihy → Bealanana → Bemanevika (200 km, 9h)"}, "description": {"en": "A 4WD journey to the remote Bemanevika Special Reserve, last refuge of the critically endangered Madagascar Pochard and the elusive Red Owl. Lunch in Bealanana before reaching camp by evening. Overnight camping.", "fr": "Expédition en 4×4 vers la réserve spéciale isolée de Bemanevika, dernier refuge du fuligule de Madagascar (au bord de l'extinction) et de l'insaisissable phodile rousse. Déjeuner à Bealanana avant d'atteindre le camp en soirée. Nuit sous tente."}}, {"day": {"en": "Day 15", "fr": "Jour 15"}, "title": {"en": "Bemanevika", "fr": "Bemanevika"}, "description": {"en": "Hike through varied habitats for White-throated Rail, Meller's Duck and Malagasy Kingfisher, with the forest quest for the rare Red Owl. At 'Pochard Lake', watch for Madagascar Grebe and Rail; night excursions for nightjars and scops owls. Overnight camping.", "fr": "Randonnée à travers des habitats variés (râle à gorge blanche, canard de Meller, martin-pêcheur malgache), avec la quête en forêt de la rare phodile rousse. Au « lac du Fuligule », guet du grèbe et du râle de Madagascar ; sorties nocturnes (engoulevents, petits-ducs). Nuit sous tente."}}, {"day": {"en": "Day 16", "fr": "Jour 16"}, "title": {"en": "Bemanevika", "fr": "Bemanevika"}, "description": {"en": "A second full day for the area's specialities — Madagascar Pochard, Madagascar Serpent Eagle, Red Owl and Slender-billed Flufftail — across wetlands and marshes, with further night outings. Overnight camping.", "fr": "Deuxième journée complète pour les spécialités du secteur — fuligule, serpentaire, phodile rousse et râle à bec fin — entre zones humides et marais, avec de nouvelles sorties nocturnes. Nuit sous tente."}}, {"day": {"en": "Day 17", "fr": "Jour 17"}, "title": {"en": "Bemanevika → Antsohihy (200 km, 9h)", "fr": "Bemanevika → Antsohihy (200 km, 9h)"}, "description": {"en": "Return to Antsohihy; time to explore the town and its craft workshops. Overnight at Hotel Sofia Bellevue.", "fr": "Retour à Antsohihy ; temps libre pour découvrir la ville et ses ateliers d'artisanat. Nuit à l'Hotel Sofia Bellevue."}}, {"day": {"en": "Day 18", "fr": "Jour 18"}, "title": {"en": "Antsohihy → Ankarafantsika (340 km, 10h)", "fr": "Antsohihy → Ankarafantsika (340 km, 10h)"}, "description": {"en": "Drive back south across the satrana grasslands via Ambondromamy to Ankarafantsika. Overnight at Tia Asity Lodge.", "fr": "Retour vers le sud à travers les savanes de satrana via Ambondromamy jusqu'à Ankarafantsika. Nuit au Tia Asity Lodge."}}, {"day": {"en": "Day 19", "fr": "Jour 19"}, "title": {"en": "Ankarafantsika → Mahajanga → Antananarivo (flight)", "fr": "Ankarafantsika → Mahajanga → Antananarivo (vol)"}, "description": {"en": "Final 'cleanup' birding in the dry forest, then drive to lively Mahajanga and fly to Antananarivo. Overnight at La Résidence Lapasoa.", "fr": "Dernières observations dans la forêt sèche, puis route vers la ville animée de Mahajanga et vol vers Antananarivo. Nuit à La Résidence Lapasoa."}}, {"day": {"en": "Day 20", "fr": "Jour 20"}, "title": {"en": "Antananarivo → Andasibe (170 km, 4h)", "fr": "Antananarivo → Andasibe (170 km, 4h)"}, "description": {"en": "Morning at Lake Tsarasaotra, a refuge for endangered waterbirds — Madagascar Little Grebe, Meller's Duck, Madagascar Pond Heron and Humblot's Heron — then drive east to Andasibe. Overnight at Andasibe Lemurs Lodge.", "fr": "Matinée au lac Tsarasaotra, refuge d'oiseaux d'eau menacés — grèbe malgache, canard de Meller, crabier blanc, héron de Humblot — puis route vers l'est jusqu'à Andasibe. Nuit à l'Andasibe Lemurs Lodge."}}, {"day": {"en": "Day 21", "fr": "Jour 21"}, "title": {"en": "Mantadia National Park", "fr": "Parc national de Mantadia"}, "description": {"en": "A full day in Andasibe-Mantadia (over 100 species): Red-breasted Coua, Scaly and Short-legged Ground Roller, Madagascan Ibis, Crossley's Vanga and more, plus a night walk for the streaked tenrec, owls and geckos. Overnight at Andasibe Lemurs Lodge.", "fr": "Journée complète à Andasibe-Mantadia (plus de 100 espèces) : coua à poitrine rouge, brachyptérolles écaillé et à pieds courts, ibis, vanga de Crossley et bien d'autres, plus une marche nocturne (tenrec, chouettes, geckos). Nuit à l'Andasibe Lemurs Lodge."}}, {"day": {"en": "Day 22", "fr": "Jour 22"}, "title": {"en": "Iaroka Forest", "fr": "Forêt d'Iaroka"}, "description": {"en": "Bird the community reserve of Iaroka, famous since the discovery of the Helmet Vanga in its deep forest. A challenging walk may reward you with Helmet and Bernier's Vanga, Brown Emutail and Rufous-headed Ground Roller. Overnight at Andasibe Lemurs Lodge.", "fr": "Observation dans la réserve communautaire d'Iaroka, célèbre depuis la découverte du vanga casqué au cœur de sa forêt. Une marche exigeante peut être récompensée par le vanga casqué, le vanga de Bernier et le brachyptérolle à tête rousse. Nuit à l'Andasibe Lemurs Lodge."}}, {"day": {"en": "Day 23", "fr": "Jour 23"}, "title": {"en": "Analamazaotra → Antananarivo (170 km, 4h)", "fr": "Analamazaotra → Antananarivo (170 km, 4h)"}, "description": {"en": "A final morning in Analamazaotra, best known for the Indri — Madagascar's largest lemur, whose haunting call echoes at dawn — and 13 other lemur species. Lunch, then transfer back to Antananarivo. Overnight at La Résidence Lapasoa.", "fr": "Dernière matinée à Analamazaotra, réputée pour l'Indri — le plus grand lémurien de Madagascar, dont l'appel résonne à l'aube — et 13 autres espèces de lémuriens. Déjeuner, puis transfert vers Antananarivo. Nuit à La Résidence Lapasoa."}}, {"day": {"en": "Day 24", "fr": "Jour 24"}, "title": {"en": "International departure", "fr": "Départ international"}, "description": {"en": "Your tour comes to an end. We arrange your transfer to Ivato Airport. Safe travels!", "fr": "Votre circuit s'achève. Nous organisons votre transfert vers l'aéroport d'Ivato. Bon retour !"}}], "priceFrom": 5540, "bestSeason": {"en": "September to November", "fr": "De septembre à novembre"}, "difficulty": 3, "highlights": {"en": ["Andasibe & Ranomafana birds", "Isalo's unique landscapes", "Ifaty's endemic spiny-forest birds", "Bemanevika hidden gem"], "fr": ["Oiseaux d'Andasibe & Ranomafana", "Les paysages uniques de l'Isalo", "Les endémiques d'Ifaty", "Bemanevika, joyau caché"]}, "description": {"en": "A 24-day adventure through Madagascar's landscapes and rich birdlife. From the spiny forests of Ifaty (Long-tailed Ground Roller, Red-capped Coua) to Zombitse-Vohibasia, Ranomafana, Ankarafantsika (White-breasted Mesite, Madagascar Fish-Eagle) and the remote Bemanevika Special Reserve — last refuge of the Madagascar Pochard and Red Owl — this expedition tracks the island's rarest endemics, ending amid the calls of the Indri lemurs in Andasibe-Mantadia.", "fr": "Une aventure de 24 jours à travers les paysages et l'avifaune de Madagascar. Des forêts épineuses d'Ifaty (rollier à longue queue, coua à tête rousse) à Zombitse-Vohibasia, Ranomafana, Ankarafantsika (mésite à poitrine blanche, pygargue de Madagascar) jusqu'à la réserve spéciale isolée de Bemanevika — dernier refuge du fuligule de Madagascar et de la phodile rousse — cette expédition traque les endémiques les plus rares de l'île, avant de s'achever au son des indris à Andasibe-Mantadia."}, "notIncluded": {"en": ["Drinks", "Tips and personal purchases", "All meals (lunches and dinners)", "Travel insurance and visa", "International flights"], "fr": ["Boissons", "Pourboires et achats personnels", "Tous les repas (déjeuners et dîners)", "Assurance voyage et visa", "Vols internationaux"]}, "durationDays": 24, "macroRegions": ["north", "west", "highlands", "east", "south"]}$MW$::jsonb) on conflict (slug) do update set featured=excluded.featured, sort=excluded.sort, content=excluded.content;
insert into public.circuits (slug, featured, sort, content) values ('discovery-wildlife-coast-15d', true, 4, $MW${"slug": "discovery-wildlife-coast-15d", "tone": "ocean", "title": {"en": "Discovery — Wildlife, Landscapes & Coast", "fr": "Découverte — Faune, paysages & côte"}, "region": "Antsirabe · Ranomafana · Isalo · Ambatomilo · Andasibe", "gallery": ["/images/discovery-wildlife-coast-15d-1.webp", "/images/discovery-wildlife-coast-15d-2.webp", "/images/discovery-wildlife-coast-15d-3.webp"], "summary": {"en": "Fifteen days from the highlands to the reef: RN7 crafts and lemurs, the canyons of Isalo, and pure relaxation on a world-class beach at Ambatomilo — ideal for families.", "fr": "Quinze jours des hautes terres au récif : artisanat et lémuriens de la RN7, canyons de l'Isalo et détente pure sur une plage d'exception à Ambatomilo — idéal en famille."}, "category": "nature", "featured": true, "groupMax": 14, "included": {"en": ["Air-conditioned 4WD including fuel", "English-speaking driver", "Accommodation in double/twin with breakfast", "Half board at Ambatomilo", "Domestic flight", "Entry fees to all mentioned parks", "Local park guides", "Driver & guide's board and lodging", "Taxes"], "fr": ["4×4 climatisé, carburant inclus", "Chauffeur anglophone", "Hébergement en chambre double/twin avec petit-déjeuner", "Demi-pension à Ambatomilo", "Vol intérieur", "Droits d'entrée de tous les parcs cités", "Guides locaux dans les parcs", "Hébergement et repas du chauffeur et du guide", "Taxes"]}, "itinerary": [{"day": {"en": "Day 1", "fr": "Jour 1"}, "title": {"en": "Arrival at Antananarivo", "fr": "Arrivée à Antananarivo"}, "description": {"en": "Our agent greets you at the airport, helps with a SIM card and currency exchange, and transfers you to your hotel. Overnight at Le Grand Mellis or similar.", "fr": "Notre agent vous accueille à l'aéroport, vous aide pour la carte SIM et le change, et vous transfère à votre hôtel. Nuit au Grand Mellis ou similaire."}}, {"day": {"en": "Day 2", "fr": "Jour 2"}, "title": {"en": "Antananarivo → Antsirabe (170 km, 4h)", "fr": "Antananarivo → Antsirabe (170 km, 4h)"}, "description": {"en": "Drive south through villages and rice fields, stopping at Ambatolampy's aluminium workshops. After lunch in Antsirabe, visit Lakes Andraikiba and Tritriva — the latter ideal for a swim. Overnight at Ecolodge Chambre du Voyageur.", "fr": "Route vers le sud à travers villages et rizières, avec un arrêt aux ateliers d'aluminium d'Ambatolampy. Après le déjeuner à Antsirabe, découverte des lacs Andraikiba et Tritriva — ce dernier parfait pour une baignade. Nuit à l'Ecolodge Chambre du Voyageur."}}, {"day": {"en": "Day 3", "fr": "Jour 3"}, "title": {"en": "Antsirabe → Ranomafana (250 km, 7h)", "fr": "Antsirabe → Ranomafana (250 km, 7h)"}, "description": {"en": "Tour Antsirabe by rickshaw (railway station, Hôtel des Thermes, zebu-horn crafts), lunch in Ambositra, capital of woodcraft, then descend to the eastern rainforest and Ranomafana with a night walk at the forest edge. Overnight at Setam Lodge.", "fr": "Découverte d'Antsirabe en pousse-pousse (gare, Hôtel des Thermes, objets en corne de zébu), déjeuner à Ambositra, capitale du bois, puis descente vers la forêt de l'Est et Ranomafana avec une marche nocturne en lisière. Nuit au Setam Lodge."}}, {"day": {"en": "Day 4", "fr": "Jour 4"}, "title": {"en": "Ranomafana National Park", "fr": "Parc national de Ranomafana"}, "description": {"en": "Explore this 415 km² rainforest park, home to the golden bamboo lemur, 12 lemur species and 30 endemic birds. Choose a trail such as Varibolomena for bamboo lemurs and waterfalls. Overnight at Setam Lodge.", "fr": "Exploration de ce parc de forêt tropicale de 415 km², refuge du lémurien à bambou doré, de 12 espèces de lémuriens et de 30 oiseaux endémiques. Sentier au choix, comme le Varibolomena (lémuriens à bambou, cascades). Nuit au Setam Lodge."}}, {"day": {"en": "Day 5", "fr": "Jour 5"}, "title": {"en": "Ranomafana → Anja → Ranohira (360 km, 7h)", "fr": "Ranomafana → Anja → Ranohira (360 km, 7h)"}, "description": {"en": "Along the RN7, stop in Fianarantsoa and Ambalavao (Antemoro paper, zebu market), then Anja Reserve for ring-tailed lemurs, crossing the Ihorombe plateau to Ranohira. Overnight at Hotel H1 Isalo.", "fr": "Sur la RN7, arrêts à Fianarantsoa et Ambalavao (papier Antemoro, marché aux zébus), puis réserve d'Anja pour les makis catta, avant de traverser le plateau de l'Ihorombe jusqu'à Ranohira. Nuit à l'Hotel H1 Isalo."}}, {"day": {"en": "Day 6", "fr": "Jour 6"}, "title": {"en": "Isalo National Park", "fr": "Parc national de l'Isalo"}, "description": {"en": "A full day in the canyons and oases of Isalo — natural pools, waterfalls, the 'Piscine Bleue et Noire' trails and a mesmerising sunset at the Window of Isalo. Overnight at Hotel H1 Isalo.", "fr": "Une journée entière dans les canyons et oasis de l'Isalo — piscines naturelles, cascades, sentiers de la « Piscine Bleue et Noire » et coucher de soleil envoûtant sur la Fenêtre de l'Isalo. Nuit à l'Hotel H1 Isalo."}}, {"day": {"en": "Day 7", "fr": "Jour 7"}, "title": {"en": "Ranohira → Zombitse → Toliara (280 km, 5h)", "fr": "Ranohira → Zombitse → Toliara (280 km, 5h)"}, "description": {"en": "Drive south past baobabs and thorny forest, through the sapphire town of Ilakaka. Visit Zombitse National Park and see the decorated Mahafaly and Antandroy tombs along the way.", "fr": "Route vers le sud entre baobabs et forêt épineuse, en passant par Ilakaka la ville du saphir. Visite du parc national de Zombitse et découverte des tombeaux décorés mahafaly et antandroy en chemin."}}, {"day": {"en": "Day 8", "fr": "Jour 8"}, "title": {"en": "Toliara → Ifaty → Ambatomilo (125 km, 2h)", "fr": "Toliara → Ifaty → Ambatomilo (125 km, 2h)"}, "description": {"en": "Coastal road to Ambatomilo, stopping at Reniala Reserve near Ifaty — 60 ha of baobabs and thorny bush, a birders' paradise home to a 1,500-year-old baobab. Free afternoon on arrival. Overnight at Shangri-La Lodge.", "fr": "Route côtière vers Ambatomilo, avec un arrêt à la réserve de Reniala près d'Ifaty — 60 ha de baobabs et de bush épineux, paradis des ornithologues, abritant un baobab de plus de 1 500 ans. Après-midi libre à l'arrivée. Nuit au Shangri-La Lodge."}}, {"day": {"en": "Days 9–10", "fr": "Jours 9–10"}, "title": {"en": "Ambatomilo — lagoon & beach", "fr": "Ambatomilo — lagon & plage"}, "description": {"en": "Two free days on a magnificent lagoon: snorkelling on the reef a kilometre offshore, humpback whale watching in season (Jul–Sep), a visit to the Vezo village of Tsiandamba, or scuba diving along one of the world's richest reefs. Overnight at Shangri-La Lodge.", "fr": "Deux journées libres sur un lagon magnifique : snorkeling sur le récif à un kilomètre du rivage, observation des baleines à bosse en saison (juil.–sept.), visite du village vezo de Tsiandamba ou plongée le long de l'un des récifs les plus riches du monde. Nuit au Shangri-La Lodge."}}, {"day": {"en": "Day 11", "fr": "Jour 11"}, "title": {"en": "Ambatomilo → Toliara → Antananarivo (flight)", "fr": "Ambatomilo → Toliara → Antananarivo (vol)"}, "description": {"en": "Transfer to Toliara and fly to Antananarivo; transfer to your hotel.", "fr": "Transfert à Toliara et vol vers Antananarivo ; transfert à votre hôtel."}}, {"day": {"en": "Day 12", "fr": "Jour 12"}, "title": {"en": "Antananarivo → Andasibe (150 km, 4h)", "fr": "Antananarivo → Andasibe (150 km, 4h)"}, "description": {"en": "Scenic drive to Andasibe through villages, rice paddies and forest, with a stop at Mr Peyrieras' reptile and butterfly farm in Marozevo. Evening stroll through Andasibe village. Overnight at Andasibe Lemurs Lodge.", "fr": "Route pittoresque vers Andasibe à travers villages, rizières et forêts, avec un arrêt à la ferme aux reptiles et papillons de M. Peyrieras à Marozevo. Balade en soirée dans le village d'Andasibe. Nuit à l'Andasibe Lemurs Lodge."}}, {"day": {"en": "Day 13", "fr": "Jour 13"}, "title": {"en": "Analamazaotra National Park", "fr": "Parc national d'Analamazaotra"}, "description": {"en": "Trek in Analamazaotra to meet the Indri, woolly and brown lemurs, chameleons and frogs, then Lemur Island at Vakona and an evening night walk at VOIMMA (mouse lemur, leaf-tailed gecko). Overnight at Andasibe Lemurs Lodge.", "fr": "Randonnée à Analamazaotra à la rencontre de l'Indri, des lémuriens laineux et bruns, des caméléons et grenouilles, puis Île aux Lémuriens de Vakona et marche nocturne à VOIMMA (microcèbe, gecko à queue plate). Nuit à l'Andasibe Lemurs Lodge."}}, {"day": {"en": "Day 14", "fr": "Jour 14"}, "title": {"en": "Andasibe → Antananarivo (150 km, 4h)", "fr": "Andasibe → Antananarivo (150 km, 4h)"}, "description": {"en": "A final visit to the community-run Mitsinjo Reserve, then the scenic drive back to Antananarivo, ending with a walk along Independence Avenue and the Queen's Palace. Overnight at Sakamanga Hotel.", "fr": "Ultime visite de la réserve communautaire de Mitsinjo, puis route panoramique vers Antananarivo, avec une promenade sur l'avenue de l'Indépendance et le Palais de la Reine. Nuit à l'hôtel Sakamanga."}}, {"day": {"en": "Day 15", "fr": "Jour 15"}, "title": {"en": "International departure", "fr": "Départ international"}, "description": {"en": "Your tour comes to an end. We arrange your transfer to Ivato Airport. Safe travels!", "fr": "Votre circuit s'achève. Nous organisons votre transfert vers l'aéroport d'Ivato. Bon retour !"}}], "priceFrom": 2530, "bestSeason": {"en": "All year round", "fr": "Toute l'année"}, "difficulty": 1, "highlights": {"en": ["Malagasy daily life", "The landscapes of Isalo", "Ranomafana & Andasibe", "A world-class beach escape"], "fr": ["La vie quotidienne malgache", "Les paysages de l'Isalo", "Ranomafana & Andasibe", "Une plage d'exception"]}, "description": {"en": "An extraordinary 15-day expedition through Madagascar's landscapes and biodiversity. From Antananarivo, drive to Antsirabe, then Ranomafana (golden bamboo lemur) via the woodcraft town of Ambositra. Meet ring-tailed lemurs at Anja, hike the canyons of Isalo, and pass Zombitse and its dancing sifakas on the way to the coast. Snorkel or dive at Ambatomilo — one of the world's most beautiful beaches — before flying back to end in the rainforest of Andasibe among Indri and diademed sifakas.", "fr": "Une expédition extraordinaire de 15 jours à travers les paysages et la biodiversité de Madagascar. D'Antananarivo, route vers Antsirabe, puis Ranomafana (lémurien à bambou doré) via la ville du bois d'Ambositra. Rencontre des makis catta à Anja, randonnée dans les canyons de l'Isalo, puis Zombitse et ses sifakas danseurs en route vers la côte. Snorkeling ou plongée à Ambatomilo — l'une des plus belles plages du monde — avant un vol retour pour terminer dans la forêt d'Andasibe, parmi indris et propithèques à diadème."}, "notIncluded": {"en": ["Drinks", "Tips and personal purchases", "All meals (lunches and dinners)", "Travel insurance and visa", "International flights"], "fr": ["Boissons", "Pourboires et achats personnels", "Tous les repas (déjeuners et dîners)", "Assurance voyage et visa", "Vols internationaux"]}, "durationDays": 15, "macroRegions": ["highlands", "south", "east"]}$MW$::jsonb) on conflict (slug) do update set featured=excluded.featured, sort=excluded.sort, content=excluded.content;
insert into public.circuits (slug, featured, sort, content) values ('explorer-baobab-tsingy-17d', false, 5, $MW${"slug": "explorer-baobab-tsingy-17d", "tone": "sunset", "title": {"en": "Explorer — Baobab & Tsingy to Lemur Legends", "fr": "Explorer — Des baobabs aux légendes de lémuriens"}, "region": "Morondava · Bekopaka · Ranomafana · Isalo · Andasibe", "gallery": ["/images/explorer-baobab-tsingy-17d-1.webp"], "summary": {"en": "Seventeen days linking the wild west and the RN7: Kirindy's fossa, the UNESCO Tsingy de Bemaraha, the Avenue of the Baobabs at sunset, Isalo's canyons and the Indri of Andasibe.", "fr": "Dix-sept jours reliant l'ouest sauvage à la RN7 : le fossa de Kirindy, les Tsingy de Bemaraha classés UNESCO, l'Allée des Baobabs au coucher du soleil, les canyons de l'Isalo et l'Indri d'Andasibe."}, "category": "adventure", "featured": false, "groupMax": 14, "included": {"en": ["Air-conditioned 4WD including fuel", "English-speaking driver", "Domestic flight", "Accommodation in double/twin with breakfast", "Entry fees to all mentioned parks", "Compulsory local park guides", "Ferry crossings", "Driver & guide's board and lodging", "Taxes"], "fr": ["4×4 climatisé, carburant inclus", "Chauffeur anglophone", "Vol intérieur", "Hébergement en chambre double/twin avec petit-déjeuner", "Droits d'entrée de tous les parcs cités", "Guides locaux obligatoires dans les parcs", "Traversées en bac", "Hébergement et repas du chauffeur et du guide", "Taxes"]}, "itinerary": [{"day": {"en": "Day 1", "fr": "Jour 1"}, "title": {"en": "Arrival at Antananarivo", "fr": "Arrivée à Antananarivo"}, "description": {"en": "Our agent greets you at the airport, helps with a SIM card and currency exchange, and transfers you to your hotel. Overnight at Le Grand Mellis or similar.", "fr": "Notre agent vous accueille à l'aéroport, vous aide pour la carte SIM et le change, et vous transfère à votre hôtel. Nuit au Grand Mellis ou similaire."}}, {"day": {"en": "Day 2", "fr": "Jour 2"}, "title": {"en": "Antananarivo → Morondava → Kirindy (flight + 2h)", "fr": "Antananarivo → Morondava → Kirindy (vol + 2h)"}, "description": {"en": "Fly to Morondava, lunch, then to Kirindy Reserve with a photo stop at the Avenue of the Baobabs. Night walk for dwarf and mouse lemurs, including Madame Berthe's mouse lemur — the world's smallest — and the endangered giant jumping rat. Overnight at Relais du Kirindy.", "fr": "Vol vers Morondava, déjeuner, puis route vers la réserve de Kirindy avec un arrêt photo à l'Allée des Baobabs. Marche nocturne (microcèbes), dont le microcèbe de Mme Berthe — le plus petit lémurien du monde — et le rat sauteur géant, menacé. Nuit au Relais du Kirindy."}}, {"day": {"en": "Day 3", "fr": "Jour 3"}, "title": {"en": "Kirindy → Belo → Bekopaka (180 km, 7h)", "fr": "Kirindy → Belo → Bekopaka (180 km, 7h)"}, "description": {"en": "Morning at Kirindy (fossa, Verreaux's sifakas, red-fronted lemurs), then drive through baobab forests and red earth, ferry across the Tsiribihina at Belo for lunch, and four more hours to Bekopaka near the Tsingy de Bemaraha. Overnight at Grand Hôtel du Tsingy.", "fr": "Matinée à Kirindy (fossa, propithèques de Verreaux, lémuriens à front roux), puis route à travers forêts de baobabs et terre rouge, bac sur la Tsiribihina à Belo pour le déjeuner, et quatre heures de plus jusqu'à Bekopaka, près des Tsingy de Bemaraha. Nuit au Grand Hôtel du Tsingy."}}, {"day": {"en": "Day 4", "fr": "Jour 4"}, "title": {"en": "Grand Tsingy", "fr": "Grand Tsingy"}, "description": {"en": "Drive to the start of the Grands Tsingy (17 km of track, 1–2h). The 4-hour 'Andamozavakay' circuit is a slow observational walk — no particular fitness required, but not ideal for those prone to vertigo. Caves, panoramic viewpoints and a suspension bridge, safely harnessed. Overnight at Grand Hôtel du Tsingy.", "fr": "Route jusqu'au départ des Grands Tsingy (17 km de piste, 1 à 2h). Le circuit « Andamozavakay », d'environ 4h, est une marche d'observation tranquille — sans condition physique particulière, mais déconseillée en cas de vertige. Grottes, points de vue panoramiques et pont suspendu, harnaché en sécurité. Nuit au Grand Hôtel du Tsingy."}}, {"day": {"en": "Day 5", "fr": "Jour 5"}, "title": {"en": "Bekopaka → Morondava (200 km, 9h)", "fr": "Bekopaka → Morondava (200 km, 9h)"}, "description": {"en": "Head back south by 4WD and ferry (about 9 hours), passing the Sakalava tombs and their unusual carvings, and stopping again at the Avenue of the Baobabs for a spectacular sunset. Overnight in Morondava at Chez Maggie.", "fr": "Retour vers le sud en 4×4 et bac (environ 9h), en passant devant les tombeaux Sakalava et leurs sculptures singulières, avec un nouvel arrêt à l'Allée des Baobabs pour un coucher de soleil spectaculaire. Nuit à Morondava, Chez Maggie."}}, {"day": {"en": "Day 6", "fr": "Jour 6"}, "title": {"en": "Morondava → Antsirabe (520 km, 10h)", "fr": "Morondava → Antsirabe (520 km, 10h)"}, "description": {"en": "A long travel day across the Betsiriry plateau and savannah, lunch in Miandrivazo, past the gold-panning village of Dabolava, reaching thermal Antsirabe (1,500 m) by evening. Overnight at Flower Palace.", "fr": "Longue journée de route à travers le plateau du Betsiriry et la savane, déjeuner à Miandrivazo, passage par le village aurifère de Dabolava, pour atteindre Antsirabe la thermale (1 500 m) en soirée. Nuit au Flower Palace."}}, {"day": {"en": "Day 7", "fr": "Jour 7"}, "title": {"en": "Antsirabe → Ranomafana (250 km, 7h)", "fr": "Antsirabe → Ranomafana (250 km, 7h)"}, "description": {"en": "Tour Antsirabe by rickshaw (railway station, Hôtel des Thermes, zebu-horn crafts), lunch in Ambositra, then descend to the eastern rainforest and Ranomafana with a night walk at the forest edge. Overnight at Setam Lodge.", "fr": "Découverte d'Antsirabe en pousse-pousse (gare, Hôtel des Thermes, objets en corne de zébu), déjeuner à Ambositra, puis descente vers la forêt de l'Est et Ranomafana avec une marche nocturne en lisière. Nuit au Setam Lodge."}}, {"day": {"en": "Day 8", "fr": "Jour 8"}, "title": {"en": "Ranomafana National Park", "fr": "Parc national de Ranomafana"}, "description": {"en": "Explore the 415 km² rainforest park — golden bamboo lemur, 12 lemur species and 30 endemic birds — along trails such as Varibolomena. Overnight at Setam Lodge.", "fr": "Exploration du parc de forêt tropicale de 415 km² — lémurien à bambou doré, 12 espèces de lémuriens et 30 oiseaux endémiques — sur des sentiers comme le Varibolomena. Nuit au Setam Lodge."}}, {"day": {"en": "Day 9", "fr": "Jour 9"}, "title": {"en": "Ranomafana → Anja → Ranohira (360 km, 7h)", "fr": "Ranomafana → Anja → Ranohira (360 km, 7h)"}, "description": {"en": "Along the RN7, stop in Fianarantsoa and Ambalavao (Antemoro paper, zebu market), then Anja Reserve for ring-tailed lemurs, crossing the Ihorombe plateau to Ranohira. Overnight at Hotel H1 Isalo.", "fr": "Sur la RN7, arrêts à Fianarantsoa et Ambalavao (papier Antemoro, marché aux zébus), puis réserve d'Anja pour les makis catta, avant de traverser le plateau de l'Ihorombe jusqu'à Ranohira. Nuit à l'Hotel H1 Isalo."}}, {"day": {"en": "Day 10", "fr": "Jour 10"}, "title": {"en": "Isalo National Park", "fr": "Parc national de l'Isalo"}, "description": {"en": "A full day in the canyons and oases of Isalo — natural pools, waterfalls, the 'Piscine Bleue et Noire' trails and a sunset at the Window of Isalo. Overnight at Hotel H1 Isalo.", "fr": "Une journée entière dans les canyons et oasis de l'Isalo — piscines naturelles, cascades, sentiers de la « Piscine Bleue et Noire » et coucher de soleil sur la Fenêtre de l'Isalo. Nuit à l'Hotel H1 Isalo."}}, {"day": {"en": "Day 11", "fr": "Jour 11"}, "title": {"en": "Ranohira → Zombitse → Ifaty (300 km, 6h)", "fr": "Ranohira → Zombitse → Ifaty (300 km, 6h)"}, "description": {"en": "Drive south past baobabs and thorny forest, through the sapphire town of Ilakaka. Visit Zombitse National Park and see the decorated Mahafaly and Antandroy tombs before reaching the coast at Ifaty. Overnight at La Bella Donna.", "fr": "Route vers le sud entre baobabs et forêt épineuse, en passant par Ilakaka la ville du saphir. Visite du parc national de Zombitse et des tombeaux décorés mahafaly et antandroy avant d'atteindre la côte à Ifaty. Nuit à La Bella Donna."}}, {"day": {"en": "Day 12", "fr": "Jour 12"}, "title": {"en": "Free day in Ifaty", "fr": "Journée libre à Ifaty"}, "description": {"en": "Choose from hotel excursions: Reniala Reserve, the tortoise village, a zebu-cart ride through the baobab forest, a quad-bike adventure, or sailing, snorkelling and scuba diving in the crystal-clear lagoon. Overnight at La Bella Donna.", "fr": "Excursions au choix proposées par l'hôtel : réserve de Reniala, village des tortues, balade en charrette à zébu dans la forêt de baobabs, sortie en quad, ou voile, snorkeling et plongée dans le lagon cristallin. Nuit à La Bella Donna."}}, {"day": {"en": "Day 13", "fr": "Jour 13"}, "title": {"en": "Ifaty → Toliara → Antananarivo (flight)", "fr": "Ifaty → Toliara → Antananarivo (vol)"}, "description": {"en": "Transfer to Toliara airport and fly to Antananarivo; transfer to your hotel. Overnight at Sakamanga Hotel.", "fr": "Transfert à l'aéroport de Toliara et vol vers Antananarivo ; transfert à votre hôtel. Nuit à l'hôtel Sakamanga."}}, {"day": {"en": "Day 14", "fr": "Jour 14"}, "title": {"en": "Antananarivo → Andasibe (150 km, 4h)", "fr": "Antananarivo → Andasibe (150 km, 4h)"}, "description": {"en": "Scenic drive to Andasibe with a stop at Mr Peyrieras' reptile and butterfly farm in Marozevo, then an evening stroll through Andasibe village. Overnight at Andasibe Lemurs Lodge.", "fr": "Route pittoresque vers Andasibe avec un arrêt à la ferme aux reptiles et papillons de M. Peyrieras à Marozevo, puis balade en soirée dans le village d'Andasibe. Nuit à l'Andasibe Lemurs Lodge."}}, {"day": {"en": "Day 15", "fr": "Jour 15"}, "title": {"en": "Analamazaotra National Park", "fr": "Parc national d'Analamazaotra"}, "description": {"en": "Trek in Analamazaotra to meet the Indri, woolly and brown lemurs, then Lemur Island at Vakona and an evening night walk at VOIMMA (mouse lemur, leaf-tailed gecko). Overnight at Andasibe Lemurs Lodge.", "fr": "Randonnée à Analamazaotra à la rencontre de l'Indri et des lémuriens laineux et bruns, puis Île aux Lémuriens de Vakona et marche nocturne à VOIMMA (microcèbe, gecko à queue plate). Nuit à l'Andasibe Lemurs Lodge."}}, {"day": {"en": "Day 16", "fr": "Jour 16"}, "title": {"en": "Andasibe → Antananarivo (150 km, 4h)", "fr": "Andasibe → Antananarivo (150 km, 4h)"}, "description": {"en": "A final visit to the community-run Mitsinjo Reserve, then the scenic drive back to Antananarivo, ending with Independence Avenue and the Queen's Palace. Overnight at Sakamanga Hotel.", "fr": "Ultime visite de la réserve communautaire de Mitsinjo, puis route panoramique vers Antananarivo, avec l'avenue de l'Indépendance et le Palais de la Reine. Nuit à l'hôtel Sakamanga."}}, {"day": {"en": "Day 17", "fr": "Jour 17"}, "title": {"en": "International departure", "fr": "Départ international"}, "description": {"en": "Your tour comes to an end. We arrange your transfer to Ivato Airport. Safe travels!", "fr": "Votre circuit s'achève. Nous organisons votre transfert vers l'aéroport d'Ivato. Bon retour !"}}], "priceFrom": 3200, "bestSeason": {"en": "May to November", "fr": "De mai à novembre"}, "difficulty": 2, "highlights": {"en": ["Explore the Tsingy de Bemaraha", "Sunset at Baobab Avenue", "Kirindy's wildlife", "Trek Isalo National Park"], "fr": ["Explorer les Tsingy de Bemaraha", "Coucher de soleil sur l'Allée des Baobabs", "La faune de Kirindy", "Randonner dans l'Isalo"]}, "description": {"en": "An exhilarating odyssey through western Madagascar and down the famed RN7. Fly to Morondava and visit Kirindy Reserve, home to the fossa. Reach Bekopaka, gateway to the UNESCO Tsingy de Bemaraha, and enjoy the iconic Baobab Avenue sunset. Head south via Antsirabe and Ranomafana's rainforest, meet ring-tailed lemurs at Anja, hike Isalo, relax at Ifaty, and end in Andasibe with the magical call of the Indri.", "fr": "Une odyssée grisante à travers l'ouest de Madagascar puis le long de la célèbre RN7. Vol vers Morondava et visite de la réserve de Kirindy, refuge du fossa. Rejoignez Bekopaka, porte des Tsingy de Bemaraha classés UNESCO, et savourez le coucher de soleil sur l'Allée des Baobabs. Descente vers le sud via Antsirabe et la forêt de Ranomafana, makis catta à Anja, randonnée dans l'Isalo, détente à Ifaty, et final à Andasibe au son magique de l'Indri."}, "notIncluded": {"en": ["Drinks", "Activities in Ifaty", "Tips and personal purchases", "All meals (lunches and dinners)", "Travel insurance and visa", "International flights"], "fr": ["Boissons", "Activités à Ifaty", "Pourboires et achats personnels", "Tous les repas (déjeuners et dîners)", "Assurance voyage et visa", "Vols internationaux"]}, "durationDays": 17, "macroRegions": ["west", "highlands", "south", "east"]}$MW$::jsonb) on conflict (slug) do update set featured=excluded.featured, sort=excluded.sort, content=excluded.content;
insert into public.circuits (slug, featured, sort, content) values ('northern-wonders-12d', true, 6, $MW${"slug": "northern-wonders-12d", "tone": "ocean", "title": {"en": "Northern Wonders — Lemurs, Tsingy & Islands", "fr": "Merveilles du Nord — Lémuriens, Tsingy & îles"}, "region": "Diego Suarez · Montagne d'Ambre · Ankarana · Nosy Be", "gallery": ["/images/northern-wonders-12d-1.webp", "/images/northern-wonders-12d-2.webp", "/images/northern-wonders-12d-3.webp"], "summary": {"en": "Twelve days across the north: the Emerald Sea and bays of Diego Suarez, the crowned lemurs of Amber Mountain, the Red Tsingy and Ankarana caves, and island paradise around Nosy Be.", "fr": "Douze jours dans le Nord : la Mer d'Émeraude et les baies de Diego Suarez, les lémuriens couronnés de la Montagne d'Ambre, les Tsingy Rouges et les grottes d'Ankarana, et le paradis insulaire autour de Nosy Be."}, "category": "nature", "featured": true, "groupMax": 14, "included": {"en": ["Air-conditioned 4WD transport", "English-speaking guide", "Accommodation in double/twin with breakfast", "Half board at Akiba Lodge Anjahakely", "Domestic flight", "Entry fees to all mentioned parks", "Compulsory local park guides", "Day trips to Nosy Komba, Nosy Tanikely & Nosy Iranja", "Driver & guide's board and lodging", "Taxes"], "fr": ["Transport en 4×4 climatisé", "Guide anglophone", "Hébergement en chambre double/twin avec petit-déjeuner", "Demi-pension à l'Akiba Lodge Anjahakely", "Vol intérieur", "Droits d'entrée de tous les parcs cités", "Guides locaux obligatoires dans les parcs", "Excursions à Nosy Komba, Nosy Tanikely & Nosy Iranja", "Hébergement et repas du chauffeur et du guide", "Taxes"]}, "itinerary": [{"day": {"en": "Day 1", "fr": "Jour 1"}, "title": {"en": "Arrival at Antananarivo", "fr": "Arrivée à Antananarivo"}, "description": {"en": "Our agent greets you at the airport, helps with a SIM card and currency exchange, and transfers you to your hotel. Overnight at Le Grand Mellis or similar.", "fr": "Notre agent vous accueille à l'aéroport, vous aide pour la carte SIM et le change, et vous transfère à votre hôtel. Nuit au Grand Mellis ou similaire."}}, {"day": {"en": "Day 2", "fr": "Jour 2"}, "title": {"en": "Antananarivo → Antsiranana (flight)", "fr": "Antananarivo → Antsiranana (vol)"}, "description": {"en": "Fly to Diego Suarez and explore the Three Bays — French Bay, Sugar Loaf, Sakalava Bay — a spectrum of white, pink and golden sands. Lunch at Dunes Bay, then the colonial Cap Miné, its lighthouse and Orangea beach. Overnight at Allamanda Hotel.", "fr": "Vol vers Diego Suarez et découverte des Trois Baies — baie des Français, Pain de Sucre, baie des Sakalava — un éventail de sables blancs, roses et dorés. Déjeuner à la baie des Dunes, puis le Cap Miné colonial, son phare et la plage d'Orangea. Nuit à l'Allamanda Hotel."}}, {"day": {"en": "Day 3", "fr": "Jour 3"}, "title": {"en": "Emerald Sea day trip", "fr": "Excursion à la Mer d'Émeraude"}, "description": {"en": "A traditional boat across the transparent Emerald Sea to a pristine sandbar — snorkelling, swimming and kitesurfing amid coral reefs, sea turtles and manta rays, returning to Ramena by evening. Overnight at Allamanda Hotel.", "fr": "Traversée en boutre de la Mer d'Émeraude cristalline jusqu'à un banc de sable immaculé — snorkeling, baignade et kitesurf parmi récifs coralliens, tortues marines et raies manta, retour à Ramena en soirée. Nuit à l'Allamanda Hotel."}}, {"day": {"en": "Day 4", "fr": "Jour 4"}, "title": {"en": "Diego → Joffreville → Amber Mountain NP", "fr": "Diego → Joffreville → Montagne d'Ambre"}, "description": {"en": "A day among the forest trails and waterfalls of Amber Mountain (1,475 m), a lush sanctuary of orchids and endemic wildlife — crowned lemurs, 77 bird species and the tiny Brookesia chameleon. Overnight at Nature Lodge.", "fr": "Une journée entre sentiers forestiers et cascades de la Montagne d'Ambre (1 475 m), sanctuaire luxuriant d'orchidées et d'espèces endémiques — lémuriens couronnés, 77 espèces d'oiseaux et le minuscule caméléon Brookesia. Nuit au Nature Lodge."}}, {"day": {"en": "Day 5", "fr": "Jour 5"}, "title": {"en": "Joffreville → Red Tsingy → Ankarana (150 km, 5h)", "fr": "Joffreville → Tsingy Rouges → Ankarana (150 km, 5h)"}, "description": {"en": "Drive to the surreal crimson sandstone pinnacles of the Red Tsingy, sculpted by wind and rain, then continue to Ankarana National Park and its grey tsingy. Overnight at Relais de l'Ankarana.", "fr": "Route vers les surréalistes aiguilles de grès cramoisi des Tsingy Rouges, sculptées par le vent et la pluie, puis continuation vers le parc national de l'Ankarana et ses tsingy gris. Nuit au Relais de l'Ankarana."}}, {"day": {"en": "Day 6", "fr": "Jour 6"}, "title": {"en": "Ankarana National Park", "fr": "Parc national de l'Ankarana"}, "description": {"en": "Explore Ankarana's tsingy, canyons, sinkholes, caves and suspension bridges — trails adaptable to your level of fitness. Overnight at Relais de l'Ankarana.", "fr": "Exploration des tsingy, canyons, avens, grottes et ponts suspendus de l'Ankarana — sentiers adaptables à votre condition physique. Nuit au Relais de l'Ankarana."}}, {"day": {"en": "Day 7", "fr": "Jour 7"}, "title": {"en": "Ankarana → Ankify → Nosy Be (150 km, 4h)", "fr": "Ankarana → Ankify → Nosy Be (150 km, 4h)"}, "description": {"en": "Drive through coffee, cocoa and ylang-ylang plantations and the fertile Tsaratanana foothills, visiting the Millot cocoa plantation, then board a boat at Ankify for Nosy Be. Overnight at L'Heure Bleue.", "fr": "Route à travers plantations de café, cacao et ylang-ylang et les contreforts fertiles du Tsaratanana, avec la visite de la plantation de cacao Millot, puis embarquement à Ankify pour Nosy Be. Nuit à L'Heure Bleue."}}, {"day": {"en": "Day 8", "fr": "Jour 8"}, "title": {"en": "Nosy Komba & Nosy Tanikely", "fr": "Nosy Komba & Nosy Tanikely"}, "description": {"en": "A full-day boat excursion: snorkelling and diving in the Nosy Tanikely marine reserve with a beach picnic, then Nosy Komba, famous for its tame lemurs and island craft markets. Overnight at L'Heure Bleue.", "fr": "Excursion bateau à la journée : snorkeling et plongée dans la réserve marine de Nosy Tanikely avec pique-nique sur la plage, puis Nosy Komba, réputée pour ses lémuriens familiers et ses marchés artisanaux. Nuit à L'Heure Bleue."}}, {"day": {"en": "Day 9", "fr": "Jour 9"}, "title": {"en": "Nosy Iranja", "fr": "Nosy Iranja"}, "description": {"en": "By fast boat to Nosy Iranja, two islands joined by a white sandbar revealed at low tide — turquoise waters, a turtle-nesting beach, a lighthouse viewpoint and a traditional fishing village. Overnight at L'Heure Bleue.", "fr": "En hors-bord vers Nosy Iranja, deux îles reliées par un banc de sable blanc découvert à marée basse — eaux turquoise, plage de ponte des tortues, phare panoramique et village de pêcheurs traditionnel. Nuit à L'Heure Bleue."}}, {"day": {"en": "Day 10", "fr": "Jour 10"}, "title": {"en": "Relax day in Nosy Be", "fr": "Journée détente à Nosy Be"}, "description": {"en": "A free day on the 'Perfume Island' — beaches, snorkelling, diving, vibrant markets and fresh seafood, or simply relaxing. Overnight at L'Heure Bleue.", "fr": "Journée libre sur « l'île aux parfums » — plages, snorkeling, plongée, marchés animés et fruits de mer, ou simple détente. Nuit à L'Heure Bleue."}}, {"day": {"en": "Day 11", "fr": "Jour 11"}, "title": {"en": "Nosy Be → Antananarivo (flight)", "fr": "Nosy Be → Antananarivo (vol)"}, "description": {"en": "Transfer to the airport and fly to Antananarivo; transfer to your hotel. Overnight at Sakamanga Hotel.", "fr": "Transfert à l'aéroport et vol vers Antananarivo ; transfert à votre hôtel. Nuit à l'hôtel Sakamanga."}}, {"day": {"en": "Day 12", "fr": "Jour 12"}, "title": {"en": "Departure", "fr": "Départ"}, "description": {"en": "Your tour comes to an end and we arrange your transfer to Ivato Airport. Note: international flights also depart from Nosy Be (Ethiopian Airlines, Airlink), so you may prefer to fly home from there. Safe travels!", "fr": "Votre circuit s'achève et nous organisons votre transfert vers l'aéroport d'Ivato. À noter : des vols internationaux partent aussi de Nosy Be (Ethiopian Airlines, Airlink), vous pouvez donc envisager un départ depuis l'île. Bon retour !"}}], "priceFrom": 2770, "bestSeason": {"en": "All year round", "fr": "Toute l'année"}, "difficulty": 1, "highlights": {"en": ["Antsiranana & the Emerald Sea", "Amber Mountain National Park", "The Red Tsingy", "Island paradise at Nosy Be"], "fr": ["Antsiranana & la Mer d'Émeraude", "Le parc de la Montagne d'Ambre", "Les Tsingy Rouges", "Paradis insulaire à Nosy Be"]}, "description": {"en": "A 12-day journey through northern Madagascar. Fly to Antsiranana (Diego Suarez) to discover its three bays and the Emerald Sea, hike Amber Mountain National Park — home to the world's smallest chameleon — and marvel at the crimson Red Tsingy. Explore the caves and canyons of Ankarana, visit the Millot cocoa plantation, and finish with island-hopping around Nosy Be — Nosy Komba, Nosy Tanikely and the sandbar of Nosy Iranja.", "fr": "Un voyage de 12 jours dans le nord de Madagascar. Vol vers Antsiranana (Diego Suarez) pour découvrir ses trois baies et la Mer d'Émeraude, randonnée dans le parc national de la Montagne d'Ambre — refuge du plus petit caméléon du monde — et émerveillement devant les Tsingy Rouges. Exploration des grottes et canyons de l'Ankarana, visite de la plantation de cacao Millot, et final en sauts d'îles autour de Nosy Be — Nosy Komba, Nosy Tanikely et le banc de sable de Nosy Iranja."}, "notIncluded": {"en": ["Tips and personal purchases", "All meals (lunches and dinners)", "Travel insurance and visa", "International flights"], "fr": ["Pourboires et achats personnels", "Tous les repas (déjeuners et dîners)", "Assurance voyage et visa", "Vols internationaux"]}, "durationDays": 12, "macroRegions": ["north"]}$MW$::jsonb) on conflict (slug) do update set featured=excluded.featured, sort=excluded.sort, content=excluded.content;
insert into public.circuits (slug, featured, sort, content) values ('luxury-escape-8d', false, 7, $MW${"slug": "luxury-escape-8d", "tone": "sunset", "title": {"en": "Luxury Escape — Private Charter & Exclusive Experiences", "fr": "Escapade de luxe — Charter privé & expériences exclusives"}, "region": "Bemaraha · Morondava · Isalo · Andasibe", "gallery": ["/images/luxury-escape-8d-1.webp", "/images/luxury-escape-8d-2.webp", "/images/luxury-escape-8d-3.webp"], "summary": {"en": "Eight days of untamed nature and refined comfort — private charter flights over the Tsingy and baobabs, handpicked lodges, and the calls of the Indri, all in effortless style.", "fr": "Huit jours de nature sauvage et de confort raffiné — vols privés au-dessus des Tsingy et des baobabs, lodges d'exception et chant de l'Indri, dans un style sans effort."}, "category": "nature", "featured": false, "groupMax": 12, "included": {"en": ["Private air charters per itinerary", "Air-conditioned 4WD with experienced driver-guide", "Accommodation in double/twin with daily breakfast", "All park entry fees and compulsory local guides", "All taxes and service charges"], "fr": ["Charters aériens privés selon l'itinéraire", "4×4 climatisé avec chauffeur-guide expérimenté", "Hébergement en chambre double/twin avec petit-déjeuner quotidien", "Tous les droits d'entrée des parcs et guides locaux obligatoires", "Toutes les taxes et frais de service"]}, "itinerary": [{"day": {"en": "Day 1", "fr": "Jour 1"}, "title": {"en": "Arrival in Antananarivo", "fr": "Arrivée à Antananarivo"}, "description": {"en": "Personalised Meet & Assist at Ivato: guided through customs, currency exchange and a local SIM, then transfer to an elegant boutique hotel. B&B at Nosy Manga Hotel.", "fr": "Accueil personnalisé « Meet & Assist » à Ivato : accompagnement aux formalités, change et carte SIM locale, puis transfert vers un élégant hôtel de charme. Nuit et petit-déjeuner au Nosy Manga Hotel."}}, {"day": {"en": "Day 2", "fr": "Jour 2"}, "title": {"en": "Antananarivo → Tsingy de Bemaraha → Morondava (private charter)", "fr": "Antananarivo → Tsingy de Bemaraha → Morondava (charter privé)"}, "description": {"en": "A private charter flight over the High Plateau and Manambolo River, landing near the Grand Tsingy — a UNESCO labyrinth of razor-sharp limestone pinnacles over 200 million years old. In the evening, a magical sunset at the Avenue of the Baobabs. Dinner & B&B at Palissandre Côte Ouest Resort & Spa.", "fr": "Vol en charter privé au-dessus des Hauts Plateaux et du fleuve Manambolo, atterrissage près du Grand Tsingy — labyrinthe UNESCO d'aiguilles calcaires acérées, vieux de plus de 200 millions d'années. En soirée, coucher de soleil magique sur l'Allée des Baobabs. Dîner, nuit et petit-déjeuner au Palissandre Côte Ouest Resort & Spa."}}, {"day": {"en": "Day 3", "fr": "Jour 3"}, "title": {"en": "Morondava → Isalo (private charter)", "fr": "Morondava → Isalo (charter privé)"}, "description": {"en": "Sunrise at Baobab Avenue, then a private flight to the Isalo Massif; arrive in Ranohira and settle into a luxury lodge among the sandstone formations. Dinner & B&B at Relais de la Reine.", "fr": "Lever de soleil sur l'Allée des Baobabs, puis vol privé vers le massif de l'Isalo ; arrivée à Ranohira et installation dans un lodge de luxe au cœur des formations de grès. Dîner, nuit et petit-déjeuner au Relais de la Reine."}}, {"day": {"en": "Day 4", "fr": "Jour 4"}, "title": {"en": "Isalo National Park", "fr": "Parc national de l'Isalo"}, "description": {"en": "A full day in the Jurassic landscapes of Isalo — the palm-fringed Natural Pool, the waterfalls of Namaza Canyon, ring-tailed lemurs and chameleons, and sweeping plateau views. Dinner & B&B at Relais de la Reine.", "fr": "Une journée entière dans les paysages jurassiques de l'Isalo — la Piscine Naturelle bordée de palmiers, les cascades du canyon de Namaza, makis catta et caméléons, et de vastes panoramas sur les plateaux. Dîner, nuit et petit-déjeuner au Relais de la Reine."}}, {"day": {"en": "Day 5", "fr": "Jour 5"}, "title": {"en": "Isalo → Antananarivo → Andasibe (charter + drive)", "fr": "Isalo → Antananarivo → Andasibe (charter + route)"}, "description": {"en": "A private flight back to Antananarivo, lunch in the capital, then a scenic 4-hour drive to Andasibe through villages, rice paddies and rolling hills to a luxury rainforest lodge. B&B at Mantadia Lodge.", "fr": "Vol privé retour vers Antananarivo, déjeuner dans la capitale, puis route panoramique de 4h vers Andasibe à travers villages, rizières et collines jusqu'à un lodge de luxe en lisière de forêt. Nuit et petit-déjeuner au Mantadia Lodge."}}, {"day": {"en": "Day 6", "fr": "Jour 6"}, "title": {"en": "Analamazaotra & night walk", "fr": "Analamazaotra & marche nocturne"}, "description": {"en": "Into the Analamazaotra Reserve for the Indri and its haunting song, the diademed sifaka and endemic birds; an intimate Lemur Island encounter, then a guided night walk in the VOIMMA community forest. B&B at Mantadia Lodge.", "fr": "Dans la réserve d'Analamazaotra à la rencontre de l'Indri et de son chant envoûtant, du propithèque à diadème et des oiseaux endémiques ; rencontre intime sur l'Île aux Lémuriens, puis marche nocturne guidée dans la forêt communautaire de VOIMMA. Nuit et petit-déjeuner au Mantadia Lodge."}}, {"day": {"en": "Day 7", "fr": "Jour 7"}, "title": {"en": "Andasibe → Antananarivo (city tour)", "fr": "Andasibe → Antananarivo (visite de ville)"}, "description": {"en": "Return to Antananarivo past the Angavo range, then a guided city tour — the Analakely market, colonial architecture and the hilltop Rova (Royal Palace). B&B at Radisson Blu Waterfront.", "fr": "Retour vers Antananarivo en longeant le massif de l'Angavo, puis visite guidée de la ville — le marché d'Analakely, l'architecture coloniale et le Rova (Palais royal) sur les hauteurs. Nuit et petit-déjeuner au Radisson Blu Waterfront."}}, {"day": {"en": "Day 8", "fr": "Jour 8"}, "title": {"en": "Departure", "fr": "Départ"}, "description": {"en": "A relaxed morning before your transfer to Ivato Airport for your international departure. Leave with unforgettable memories of Madagascar's wild beauty and luxurious hospitality.", "fr": "Une matinée tranquille avant votre transfert vers l'aéroport d'Ivato pour votre départ international. Repartez avec des souvenirs inoubliables de la beauté sauvage de Madagascar et d'une hospitalité de luxe."}}], "priceFrom": 5460, "bestSeason": {"en": "May to November", "fr": "De mai à novembre"}, "difficulty": 1, "highlights": {"en": ["Dramatic landscapes from above", "The ancient pinnacles of Bemaraha", "Baobab sunsets & sunrises", "Where nature meets luxury"], "fr": ["Paysages spectaculaires vus du ciel", "Les aiguilles antiques du Bemaraha", "Baobabs au lever et au coucher du soleil", "Quand la nature rencontre le luxe"]}, "description": {"en": "A luxury journey crafted for travellers who seek the extraordinary. Fly privately over dramatic landscapes, explore the ancient stone forest of the Grand Tsingy, walk among giant baobabs at sunset and sunrise, hike the Jurassic canyons of Isalo, and hear the haunting calls of the Indri deep in the rainforest — every moment curated for exclusivity, from private air charters and handpicked lodges to intimate wildlife encounters.", "fr": "Un voyage de luxe conçu pour les voyageurs en quête d'extraordinaire. Survolez en privé des paysages spectaculaires, explorez l'antique forêt de pierre du Grand Tsingy, marchez parmi les baobabs géants au coucher et au lever du soleil, randonnez dans les canyons jurassiques de l'Isalo, et écoutez le chant envoûtant de l'Indri au cœur de la forêt — chaque instant pensé pour l'exclusivité, des charters privés aux lodges d'exception et aux rencontres intimes avec la faune."}, "notIncluded": {"en": ["International flights, visa and insurance", "Meals (lunches and dinners), drinks and personal expenses", "Tips and gratuities"], "fr": ["Vols internationaux, visa et assurance", "Repas (déjeuners et dîners), boissons et dépenses personnelles", "Pourboires et gratifications"]}, "durationDays": 8, "macroRegions": ["west", "south", "east"]}$MW$::jsonb) on conflict (slug) do update set featured=excluded.featured, sort=excluded.sort, content=excluded.content;
insert into public.circuits (slug, featured, sort, content) values ('birding-photography-20d', false, 8, $MW${"slug": "birding-photography-20d", "tone": "forest", "title": {"en": "Ultimate Birding & Photography — Masoala & Beyond", "fr": "Ornithologie & photo ultime — Masoala & au-delà"}, "region": "Ankarafantsika · Masoala · Andasibe", "gallery": ["/images/birding-photography-20d-1.webp", "/images/birding-photography-20d-2.webp", "/images/birding-photography-20d-3.webp"], "summary": {"en": "Twenty days across three iconic birding regions — the dry forests of Ankarafantsika, the lowland rainforest of Masoala and montane Andasibe-Mantadia — in search of 150+ endemics.", "fr": "Vingt jours à travers trois régions ornithologiques emblématiques — les forêts sèches d'Ankarafantsika, la forêt de plaine de Masoala et Andasibe-Mantadia — à la recherche de plus de 150 espèces endémiques."}, "category": "wildlife", "featured": false, "groupMax": 8, "included": {"en": ["Air-conditioned 4WD including fuel", "English-speaking guide", "Domestic flights", "Accommodation in double/twin with breakfast", "Entry fees to all mentioned parks", "Local park guides", "Driver & guide's board and lodging", "Taxes"], "fr": ["4×4 climatisé, carburant inclus", "Guide anglophone", "Vols intérieurs", "Hébergement en chambre double/twin avec petit-déjeuner", "Droits d'entrée de tous les parcs cités", "Guides locaux dans les parcs", "Hébergement et repas du chauffeur et du guide", "Taxes"]}, "itinerary": [{"day": {"en": "Day 1", "fr": "Jour 1"}, "title": {"en": "Arrival in Antananarivo", "fr": "Arrivée à Antananarivo"}, "description": {"en": "Warm welcome at Ivato and transfer to your city hotel; relax after your long flight. Overnight at Le Chalet des Roses.", "fr": "Accueil chaleureux à Ivato et transfert vers votre hôtel en ville ; détente après votre long vol. Nuit au Chalet des Roses."}}, {"day": {"en": "Day 2", "fr": "Jour 2"}, "title": {"en": "Tsarasaotra & fly to Mahajanga", "fr": "Tsarasaotra & vol vers Mahajanga"}, "description": {"en": "Early birding at the urban Tsarasaotra Lake reserve (whistling-ducks, herons, Dimorphic Egret), then a flight to the coastal town of Mahajanga. Overnight at Coco Lodge.", "fr": "Observation matinale à la réserve urbaine du lac Tsarasaotra (dendrocygnes, hérons, aigrette dimorphe), puis vol vers la ville côtière de Mahajanga. Nuit au Coco Lodge."}}, {"day": {"en": "Day 3", "fr": "Jour 3"}, "title": {"en": "Betsiboka Delta → Ankarafantsika", "fr": "Delta de la Betsiboka → Ankarafantsika"}, "description": {"en": "A motorised boat ride on the Betsiboka Delta in search of the endangered Bernier's Teal and Malagasy Sacred Ibis, then a scenic 4-hour drive to Ankarafantsika. Overnight at Tia Asity Lodge.", "fr": "Sortie en bateau à moteur sur le delta de la Betsiboka à la recherche de la sarcelle de Bernier et de l'ibis sacré malgache, menacés, puis route panoramique de 4h vers Ankarafantsika. Nuit au Tia Asity Lodge."}}, {"day": {"en": "Days 4–6", "fr": "Jours 4–6"}, "title": {"en": "Ankarafantsika National Park", "fr": "Parc national d'Ankarafantsika"}, "description": {"en": "Three full days on the park's trails — White-breasted Mesite, Van Dam's and Hook-billed Vanga, Schlegel's Asity — plus Coquerel's sifaka and other lemurs, with an afternoon boat trip across the lake. Overnight at Tia Asity Lodge.", "fr": "Trois journées complètes sur les sentiers du parc — mésite à poitrine blanche, vangas de Van Dam et à bec crochu, philépitte de Schlegel — ainsi que le propithèque de Coquerel et d'autres lémuriens, avec une sortie en bateau sur le lac. Nuit au Tia Asity Lodge."}}, {"day": {"en": "Day 7", "fr": "Jour 7"}, "title": {"en": "Ankarafantsika → Mahajanga → Antananarivo (flight)", "fr": "Ankarafantsika → Mahajanga → Antananarivo (vol)"}, "description": {"en": "Birding stops at Lake Amboromalandy and rice fields (Madagascar Jacana, Humblot's Heron), then an evening flight to Antananarivo. Overnight at Avamada Lodge.", "fr": "Arrêts d'observation au lac Amboromalandy et dans les rizières (jacana, héron de Humblot), puis vol en soirée vers Antananarivo. Nuit à l'Avamada Lodge."}}, {"day": {"en": "Day 8", "fr": "Jour 8"}, "title": {"en": "Fly to Maroantsetra", "fr": "Vol vers Maroantsetra"}, "description": {"en": "Flight to Maroantsetra, gateway to the wild north-east; relaxed evening at your hotel. Overnight at Manga Beach Hotel.", "fr": "Vol vers Maroantsetra, porte du nord-est sauvage ; soirée tranquille à votre hôtel. Nuit au Manga Beach Hotel."}}, {"day": {"en": "Day 9", "fr": "Jour 9"}, "title": {"en": "Boat transfer to Masoala", "fr": "Transfert bateau vers Masoala"}, "description": {"en": "A scenic 2.5-hour boat crossing of Antongil Bay to the Masoala Peninsula and its vast rainforest; first trails for Brown Mesite, Blue Coua and vangas, with an optional night walk. Overnight at Hippocampe Lodge.", "fr": "Traversée en bateau de 2h30 de la baie d'Antongil jusqu'à la presqu'île de Masoala et sa vaste forêt ; premiers sentiers (mésite unicolore, coua bleu, vangas), avec une marche nocturne en option. Nuit à l'Hippocampe Lodge."}}, {"day": {"en": "Days 10–13", "fr": "Jours 10–13"}, "title": {"en": "Masoala National Park", "fr": "Parc national de Masoala"}, "description": {"en": "Four days birding Madagascar's largest rainforest — Helmet and White-headed Vanga, Short-legged Ground Roller, coastal Madagascar Pratincole — with chances of Red Ruffed and White-fronted Lemur. Overnight at Hippocampe Lodge.", "fr": "Quatre jours d'observation dans la plus grande forêt de Madagascar — vangas casqué et à tête blanche, brachyptérolle à pieds courts, glaréole malgache du littoral — avec des chances de voir le vari roux et le lémur à front blanc. Nuit à l'Hippocampe Lodge."}}, {"day": {"en": "Day 14", "fr": "Jour 14"}, "title": {"en": "Boat to Nosy Mangabe", "fr": "Bateau vers Nosy Mangabe"}, "description": {"en": "By boat toward Maroantsetra with a stop at the rainforest island reserve of Nosy Mangabe; overnight camping on this remote island. Overnight camping.", "fr": "En bateau vers Maroantsetra avec un arrêt à la réserve insulaire boisée de Nosy Mangabe ; nuit sous tente sur cette île isolée. Nuit sous tente."}}, {"day": {"en": "Day 15", "fr": "Jour 15"}, "title": {"en": "Fly to Antananarivo → Andasibe", "fr": "Vol vers Antananarivo → Andasibe"}, "description": {"en": "Return by boat to Maroantsetra, fly to Antananarivo, then the 4-hour drive east to Andasibe. Overnight at Feon'ny Ala.", "fr": "Retour en bateau à Maroantsetra, vol vers Antananarivo, puis route de 4h vers l'est jusqu'à Andasibe. Nuit au Feon'ny Ala."}}, {"day": {"en": "Day 16", "fr": "Jour 16"}, "title": {"en": "Birding at Analamazaotra", "fr": "Observation à Analamazaotra"}, "description": {"en": "A full day in Analamazaotra — the Indri and its haunting call, colourful ground rollers and the elusive Collared Nightjar — with a VOIMMA night walk. Overnight at Feon'ny Ala.", "fr": "Journée complète à Analamazaotra — l'Indri et son appel envoûtant, les brachyptérolles colorés et l'engoulevent à collier — avec une marche nocturne à VOIMMA. Nuit au Feon'ny Ala."}}, {"day": {"en": "Day 17", "fr": "Jour 17"}, "title": {"en": "Birding at Mantadia", "fr": "Observation à Mantadia"}, "description": {"en": "Venture deeper into the primary rainforest of Mantadia for the Red-breasted Coua and Short-legged Ground Roller. Overnight at Feon'ny Ala.", "fr": "Plongée plus profonde dans la forêt primaire de Mantadia pour le coua à poitrine rouge et le brachyptérolle à pieds courts. Nuit au Feon'ny Ala."}}, {"day": {"en": "Day 18", "fr": "Jour 18"}, "title": {"en": "Iaroka Forest", "fr": "Forêt d'Iaroka"}, "description": {"en": "A challenging six-hour trek into the community-run primary forest of Iaroka for the Helmet Vanga and other high-value specialities. Overnight at Feon'ny Ala.", "fr": "Un trek exigeant de six heures dans la forêt primaire communautaire d'Iaroka pour le vanga casqué et d'autres spécialités recherchées. Nuit au Feon'ny Ala."}}, {"day": {"en": "Day 19", "fr": "Jour 19"}, "title": {"en": "Maromizaha Reserve", "fr": "Réserve de Maromizaha"}, "description": {"en": "Birding Maromizaha (Frances's Sparrowhawk, Madagascar Kestrel) and an evening night walk at Mitsinjo. Overnight at Feon'ny Ala.", "fr": "Observation à Maromizaha (épervier de Frances, crécerelle malgache) et marche nocturne en soirée à Mitsinjo. Nuit au Feon'ny Ala."}}, {"day": {"en": "Day 20", "fr": "Jour 20"}, "title": {"en": "VOIMMA / Mitsinjo → Antananarivo", "fr": "VOIMMA / Mitsinjo → Antananarivo"}, "description": {"en": "A last morning session at VOIMMA or Mitsinjo, then the drive back to Antananarivo with a stop at the Mangoro River Bridge for the Madagascar Jacana; transfer to your hotel.", "fr": "Une dernière matinée à VOIMMA ou Mitsinjo, puis route retour vers Antananarivo avec un arrêt au pont de la Mangoro pour le jacana ; transfert à votre hôtel."}}], "priceFrom": 4900, "bestSeason": {"en": "May to November", "fr": "De mai à novembre"}, "difficulty": 2, "highlights": {"en": ["Exclusive rare-bird access", "Diverse forests, unique birds", "Lemurs in the wild", "Nighttime rainforest adventures"], "fr": ["Accès exclusif aux oiseaux rares", "Des forêts variées, des oiseaux uniques", "Lémuriens en liberté", "Aventures nocturnes en forêt"]}, "description": {"en": "An exclusive 20-day birding adventure across three of Madagascar's finest regions: the dry deciduous forests of Ankarafantsika, the vast lowland rainforest of Masoala and the montane paradise of Andasibe-Mantadia. From river deltas and mangroves to dense rainforest, this itinerary offers a chance to see over 150 endemic species — some of the rarest birds on Earth — alongside lemurs and chameleons, with immersive hikes and scenic boat trips throughout.", "fr": "Une aventure ornithologique exclusive de 20 jours à travers trois des plus belles régions de Madagascar : les forêts sèches d'Ankarafantsika, la vaste forêt de plaine de Masoala et le paradis d'altitude d'Andasibe-Mantadia. Des deltas et mangroves à la forêt dense, cet itinéraire offre la chance d'observer plus de 150 espèces endémiques — parmi les oiseaux les plus rares du monde — aux côtés de lémuriens et de caméléons, ponctué de randonnées immersives et de sorties en bateau."}, "notIncluded": {"en": ["Drinks", "Tips and personal purchases", "All meals (lunches and dinners)", "Travel insurance and visa", "International flights"], "fr": ["Boissons", "Pourboires et achats personnels", "Tous les repas (déjeuners et dîners)", "Assurance voyage et visa", "Vols internationaux"]}, "durationDays": 20, "macroRegions": ["west", "north", "east"]}$MW$::jsonb) on conflict (slug) do update set featured=excluded.featured, sort=excluded.sort, content=excluded.content;
insert into public.circuits (slug, featured, sort, content) values ('wild-west-sainte-marie-15d', true, 9, $MW${"slug": "wild-west-sainte-marie-15d", "tone": "ocean", "title": {"en": "Wild West & Sainte-Marie — Tsiribihina, Baobabs & Whales", "fr": "Ouest sauvage & Sainte-Marie — Tsiribihina, baobabs & baleines"}, "region": "Tsiribihina · Bemaraha · Morondava · Sainte-Marie", "gallery": ["/images/wild-west-sainte-marie-15d-1.webp", "/images/wild-west-sainte-marie-15d-2.webp", "/images/wild-west-sainte-marie-15d-3.webp"], "summary": {"en": "Fifteen days from a Tsiribihina river descent by boat to the Tsingy, the Avenue of the Baobabs and Kirindy's fossa — ending with humpback whales off the island of Sainte-Marie.", "fr": "Quinze jours d'une descente de la Tsiribihina en bateau aux Tsingy, à l'Allée des Baobabs et au fossa de Kirindy — final avec les baleines à bosse au large de l'île Sainte-Marie."}, "category": "wildlife", "featured": true, "groupMax": 14, "included": {"en": ["Air-conditioned 4WD including fuel", "English-speaking driver", "English-speaking guide for Tsiribihina & Tsingy", "Domestic flights", "Accommodation in double/twin with breakfast", "Full Tsiribihina river package (camping gear, full board)", "Entry fees to all mentioned parks", "Whale watching in Sainte-Marie (Jul–Sep) or an off-season alternative", "Day trip to Île aux Nattes & Îlot Sable", "Compulsory local park guides", "Ferry crossings", "Driver & guide's board and lodging", "Taxes"], "fr": ["4×4 climatisé, carburant inclus", "Chauffeur anglophone", "Guide anglophone pour la Tsiribihina & les Tsingy", "Vols intérieurs", "Hébergement en chambre double/twin avec petit-déjeuner", "Forfait complet sur la Tsiribihina (matériel de camping, pension complète)", "Droits d'entrée de tous les parcs cités", "Observation des baleines à Sainte-Marie (juil.–sept.) ou une activité alternative hors saison", "Excursion à l'Île aux Nattes & Îlot Sable", "Guides locaux obligatoires dans les parcs", "Traversées en bac", "Hébergement et repas du chauffeur et du guide", "Taxes"]}, "itinerary": [{"day": {"en": "Day 1", "fr": "Jour 1"}, "title": {"en": "Arrival at Antananarivo", "fr": "Arrivée à Antananarivo"}, "description": {"en": "Our agent greets you at the airport, helps with a SIM card and currency exchange, and transfers you to your hotel. Overnight at Le Grand Mellis or similar.", "fr": "Notre agent vous accueille à l'aéroport, vous aide pour la carte SIM et le change, et vous transfère à votre hôtel. Nuit au Grand Mellis ou similaire."}}, {"day": {"en": "Day 2", "fr": "Jour 2"}, "title": {"en": "Antananarivo → Miandrivazo (390 km, 9h)", "fr": "Antananarivo → Miandrivazo (390 km, 9h)"}, "description": {"en": "Drive to thermal Antsirabe, stopping at Behenjy (foie gras) and Ambatolampy (aluminium crafts), then west to the hot lowland town of Miandrivazo by evening. Overnight at Princesse Tsiribihina.", "fr": "Route vers Antsirabe la thermale, avec des arrêts à Behenjy (foie gras) et Ambatolampy (artisanat de l'aluminium), puis vers l'ouest jusqu'à la ville chaude de Miandrivazo en soirée. Nuit à la Princesse Tsiribihina."}}, {"day": {"en": "Day 3", "fr": "Jour 3"}, "title": {"en": "Miandrivazo → Tsiribihina River (motorboat)", "fr": "Miandrivazo → fleuve Tsiribihina (bateau)"}, "description": {"en": "Board an adapted river barge at Masiakampy and begin the cruise through vast plains and Sakalava reed-hut villages, with a swim at the Nosy Ampela waterfall (lemurs) before camping on a sandbar. Camping.", "fr": "Embarquement sur une barge fluviale aménagée à Masiakampy et début de la descente à travers de vastes plaines et des villages sakalava aux cases de roseaux, avec une baignade à la cascade de Nosy Ampela (lémuriens) avant le bivouac sur un banc de sable. Nuit sous tente."}}, {"day": {"en": "Day 4", "fr": "Jour 4"}, "title": {"en": "Tsiribihina River", "fr": "Fleuve Tsiribihina"}, "description": {"en": "Continue down the river's bends past pirogues and cargo barges, stop at Begidro to see traditional tobacco farming, glimpse the first baobabs at Ambatomisay, and camp on a beach with a traditional dance around the campfire. Camping.", "fr": "Poursuite de la descente au fil des méandres, au milieu des pirogues et barges de marchandises, arrêt à Begidro pour la culture traditionnelle du tabac, premiers baobabs à Ambatomisay, et bivouac sur une plage avec une danse traditionnelle autour du feu. Nuit sous tente."}}, {"day": {"en": "Day 5", "fr": "Jour 5"}, "title": {"en": "Belo sur Tsiribihina → Bekopaka (120 km, 4h)", "fr": "Belo sur Tsiribihina → Bekopaka (120 km, 4h)"}, "description": {"en": "A final morning afloat among herons, bee-eaters and teals, arriving at Belo sur Tsiribihina for lunch aboard, then transfer to 4WD for a rugged 4-hour drive to Bekopaka, gateway to the Tsingy. Overnight at Grand Hôtel du Tsingy.", "fr": "Une dernière matinée sur l'eau parmi hérons, guêpiers et sarcelles, arrivée à Belo sur Tsiribihina pour le déjeuner à bord, puis transfert en 4×4 pour 4h de piste accidentée jusqu'à Bekopaka, porte des Tsingy. Nuit au Grand Hôtel du Tsingy."}}, {"day": {"en": "Day 6", "fr": "Jour 6"}, "title": {"en": "Tsingy de Bemaraha", "fr": "Tsingy de Bemaraha"}, "description": {"en": "Drive to the start of the Grands Tsingy (17 km of track, 1–2h). The 4-hour 'Andamozavakay' circuit is a slow observational walk — caves, panoramic viewpoints and a suspension bridge, safely harnessed. Overnight at Grand Hôtel du Tsingy.", "fr": "Route jusqu'au départ des Grands Tsingy (17 km de piste, 1 à 2h). Le circuit « Andamozavakay », d'environ 4h, est une marche d'observation tranquille — grottes, points de vue panoramiques et pont suspendu, harnaché en sécurité. Nuit au Grand Hôtel du Tsingy."}}, {"day": {"en": "Day 7", "fr": "Jour 7"}, "title": {"en": "Bekopaka → Kirindy (200 km, 6h + ferry)", "fr": "Bekopaka → Kirindy (200 km, 6h + bac)"}, "description": {"en": "Drive south by 4WD, road and ferry, passing decorated Sakalava tombs, to Kirindy Reserve; prepare for the night walk. Overnight at Relais du Kirindy.", "fr": "Route vers le sud en 4×4, piste et bac, en passant devant les tombeaux sakalava décorés, jusqu'à la réserve de Kirindy ; préparation de la marche nocturne. Nuit au Relais du Kirindy."}}, {"day": {"en": "Day 8", "fr": "Jour 8"}, "title": {"en": "Kirindy → Morondava (70 km, 2h)", "fr": "Kirindy → Morondava (70 km, 2h)"}, "description": {"en": "A morning guided walk in Kirindy — dancing sifakas, tenrecs, reptiles and the chance of the elusive fossa — then the Avenue of the Baobabs at sunset before Morondava. Overnight at Chez Maggie.", "fr": "Une marche guidée le matin à Kirindy — sifakas danseurs, tenrecs, reptiles et la chance d'apercevoir le fossa — puis l'Allée des Baobabs au coucher du soleil avant Morondava. Nuit Chez Maggie."}}, {"day": {"en": "Day 9", "fr": "Jour 9"}, "title": {"en": "Morondava → Antsirabe (520 km, 10h)", "fr": "Morondava → Antsirabe (520 km, 10h)"}, "description": {"en": "A long travel day across the Betsiriry plateau and savannah, lunch in Miandrivazo, past gold-panning Dabolava, to reach thermal Antsirabe (1,500 m). Overnight at Souimanga Hotel.", "fr": "Longue journée de route à travers le plateau du Betsiriry et la savane, déjeuner à Miandrivazo, passage par le village aurifère de Dabolava, pour atteindre Antsirabe la thermale (1 500 m). Nuit au Souimanga Hotel."}}, {"day": {"en": "Day 10", "fr": "Jour 10"}, "title": {"en": "Antsirabe → Antananarivo (170 km, 4h)", "fr": "Antsirabe → Antananarivo (170 km, 4h)"}, "description": {"en": "Swim at Tritriva Lake, then tour Antsirabe (cathedral, miniature and zebu-horn workshops, gem cutting, local market), before driving north through the rural highlands to Tana. Overnight at Sakamanga Hotel.", "fr": "Baignade au lac Tritriva, puis visite d'Antsirabe (cathédrale, ateliers de miniatures et de corne de zébu, taille de pierres, marché local), avant de remonter vers le nord à travers les hautes terres rurales jusqu'à Tana. Nuit à l'hôtel Sakamanga."}}, {"day": {"en": "Day 11", "fr": "Jour 11"}, "title": {"en": "Antananarivo → Sainte-Marie (flight)", "fr": "Antananarivo → Sainte-Marie (vol)"}, "description": {"en": "Fly to the island of Sainte-Marie and transfer to your beach lodge. Overnight at Sambatra Beach Lodge.", "fr": "Vol vers l'île Sainte-Marie et transfert vers votre lodge de plage. Nuit au Sambatra Beach Lodge."}}, {"day": {"en": "Day 12", "fr": "Jour 12"}, "title": {"en": "Half-day whale watching", "fr": "Demi-journée d'observation des baleines"}, "description": {"en": "In season (Jul–Sep), a three-hour humpback whale-watching outing with a CétaMada eco-guide; the rest of the day free to relax. Overnight at Sambatra Beach Lodge.", "fr": "En saison (juil.–sept.), une sortie de trois heures d'observation des baleines à bosse avec un éco-guide de CétaMada ; le reste de la journée libre. Nuit au Sambatra Beach Lodge."}}, {"day": {"en": "Day 13", "fr": "Jour 13"}, "title": {"en": "Île aux Nattes & Îlot Sable", "fr": "Île aux Nattes & Îlot Sable"}, "description": {"en": "By boat to the sandbank islet of Îlot Sable for snorkelling and swimming in pristine lagoons, then Île aux Nattes — turquoise waters, palm beaches, a lighthouse and a canoe ride among lemurs and orchids. Overnight at Sambatra Beach Lodge.", "fr": "En bateau vers l'îlot de sable d'Îlot Sable pour le snorkeling et la baignade dans des lagons immaculés, puis l'Île aux Nattes — eaux turquoise, plages de palmiers, un phare et une balade en pirogue parmi lémuriens et orchidées. Nuit au Sambatra Beach Lodge."}}, {"day": {"en": "Day 14", "fr": "Jour 14"}, "title": {"en": "Sainte-Marie → Antananarivo (flight)", "fr": "Sainte-Marie → Antananarivo (vol)"}, "description": {"en": "Fly back to Antananarivo and transfer to your hotel. Overnight at Sakamanga Hotel.", "fr": "Vol retour vers Antananarivo et transfert à votre hôtel. Nuit à l'hôtel Sakamanga."}}, {"day": {"en": "Day 15", "fr": "Jour 15"}, "title": {"en": "International departure", "fr": "Départ international"}, "description": {"en": "Your tour comes to an end. We arrange your transfer to Ivato Airport. Safe travels!", "fr": "Votre circuit s'achève. Nous organisons votre transfert vers l'aéroport d'Ivato. Bon retour !"}}], "priceFrom": 2790, "bestSeason": {"en": "May to November", "fr": "De mai à novembre"}, "difficulty": 2, "highlights": {"en": ["Descend the Tsiribihina by boat", "Tsingy de Bemaraha adventure", "Sunset at Baobab Avenue", "Whale watching off Sainte-Marie"], "fr": ["Descendre la Tsiribihina en bateau", "L'aventure des Tsingy de Bemaraha", "Coucher de soleil sur l'Allée des Baobabs", "Baleines au large de Sainte-Marie"]}, "description": {"en": "An exhilarating expedition through western Madagascar and the island of Sainte-Marie. Cross the highlands to the Tsiribihina River and drift down it by motorboat, camping under the stars among Sakalava villages. Explore the UNESCO Tsingy de Bemaraha, meet the fossa at Kirindy and watch the sun set over the Avenue of the Baobabs, before flying to Sainte-Marie for humpback whale watching (July–September) and the turquoise lagoons of Île aux Nattes.", "fr": "Une expédition grisante à travers l'ouest de Madagascar et l'île Sainte-Marie. Traversée des hautes terres jusqu'au fleuve Tsiribihina et descente en bateau, bivouac sous les étoiles parmi les villages sakalava. Exploration des Tsingy de Bemaraha classés UNESCO, rencontre du fossa à Kirindy et coucher de soleil sur l'Allée des Baobabs, avant de s'envoler vers Sainte-Marie pour l'observation des baleines à bosse (juillet–septembre) et les lagons turquoise de l'Île aux Nattes."}, "notIncluded": {"en": ["Drinks", "Tips and personal purchases", "All meals (lunches and dinners)", "Travel insurance and visa", "International flights"], "fr": ["Boissons", "Pourboires et achats personnels", "Tous les repas (déjeuners et dîners)", "Assurance voyage et visa", "Vols internationaux"]}, "durationDays": 15, "macroRegions": ["west", "highlands", "east"], "priceEstimated": true}$MW$::jsonb) on conflict (slug) do update set featured=excluded.featured, sort=excluded.sort, content=excluded.content;
insert into public.circuits (slug, featured, sort, content) values ('ultimate-trekking-22d', false, 10, $MW${"slug": "ultimate-trekking-22d", "tone": "canyon", "title": {"en": "Ultimate Trekking — Peaks, Canyons & Hidden Wilderness", "fr": "Trekking ultime — Sommets, canyons & nature secrète"}, "region": "Ranomafana · Andringitra · Isalo · Makay", "gallery": ["/images/ultimate-trekking-22d-1.webp", "/images/ultimate-trekking-22d-2.webp", "/images/ultimate-trekking-22d-3.webp"], "summary": {"en": "A 22-day trekking expedition for the fit and adventurous — summit Pic Boby, hike the Tsaranoro valley and Isalo's canyons, and cross the remote, rarely-visited Makay Massif.", "fr": "Une expédition de trekking de 22 jours pour randonneurs aguerris — ascension du Pic Boby, vallée du Tsaranoro et canyons de l'Isalo, et traversée du massif isolé et méconnu du Makay."}, "category": "adventure", "featured": false, "groupMax": 14, "included": {"en": ["Air-conditioned 4WD including fuel", "English-speaking driver", "Accommodation in double/twin with breakfast", "Domestic flight", "Entry fees to all mentioned parks", "Local park guides", "Porters", "Full board while trekking", "Camping gear", "Driver & guide's board and lodging", "Taxes"], "fr": ["4×4 climatisé, carburant inclus", "Chauffeur anglophone", "Hébergement en chambre double/twin avec petit-déjeuner", "Vol intérieur", "Droits d'entrée de tous les parcs cités", "Guides locaux dans les parcs", "Porteurs", "Pension complète pendant le trek", "Matériel de camping", "Hébergement et repas du chauffeur et du guide", "Taxes"]}, "itinerary": [{"day": {"en": "Day 1", "fr": "Jour 1"}, "title": {"en": "Arrival at Antananarivo", "fr": "Arrivée à Antananarivo"}, "description": {"en": "Our agent greets you at the airport, helps with a SIM card and currency exchange, and transfers you to your hotel. Overnight at Le Grand Mellis or similar.", "fr": "Notre agent vous accueille à l'aéroport, vous aide pour la carte SIM et le change, et vous transfère à votre hôtel. Nuit au Grand Mellis ou similaire."}}, {"day": {"en": "Day 2", "fr": "Jour 2"}, "title": {"en": "Antananarivo → Antsirabe (170 km, 4h)", "fr": "Antananarivo → Antsirabe (170 km, 4h)"}, "description": {"en": "Drive south through villages and rice fields, stopping at Ambatolampy's aluminium workshops, then Lakes Andraikiba and Tritriva — the latter ideal for a swim. Overnight at Ecolodge Chambre du Voyageur.", "fr": "Route vers le sud à travers villages et rizières, avec un arrêt aux ateliers d'aluminium d'Ambatolampy, puis les lacs Andraikiba et Tritriva — ce dernier parfait pour une baignade. Nuit à l'Ecolodge Chambre du Voyageur."}}, {"day": {"en": "Day 3", "fr": "Jour 3"}, "title": {"en": "Antsirabe → Ranomafana (250 km, 7h)", "fr": "Antsirabe → Ranomafana (250 km, 7h)"}, "description": {"en": "Tour Antsirabe by rickshaw, lunch in the woodcraft town of Ambositra, then descend to the eastern rainforest and Ranomafana with a night walk at the forest edge. Overnight at Setam Lodge.", "fr": "Découverte d'Antsirabe en pousse-pousse, déjeuner à Ambositra, ville du bois, puis descente vers la forêt de l'Est et Ranomafana avec une marche nocturne en lisière. Nuit au Setam Lodge."}}, {"day": {"en": "Day 4", "fr": "Jour 4"}, "title": {"en": "Ranomafana National Park", "fr": "Parc national de Ranomafana"}, "description": {"en": "Explore the 415 km² rainforest park — golden bamboo lemur, 12 lemur species and 30 endemic birds — along trails such as Varibolomena. Overnight at Setam Lodge.", "fr": "Exploration du parc de forêt tropicale de 415 km² — lémurien à bambou doré, 12 espèces de lémuriens et 30 oiseaux endémiques — sur des sentiers comme le Varibolomena. Nuit au Setam Lodge."}}, {"day": {"en": "Day 5", "fr": "Jour 5"}, "title": {"en": "Ranomafana → Ambalavao → Namoly (200 km, 6h)", "fr": "Ranomafana → Ambalavao → Namoly (200 km, 6h)"}, "description": {"en": "Drive via Fianarantsoa and Ambalavao (Antemoro paper and silk factory) and the Anja Community Reserve, then take the rough 45 km track to Namoly, northern gateway to Andringitra. Overnight at Tranogasy Guesthouse.", "fr": "Route via Fianarantsoa et Ambalavao (fabrique de papier Antemoro et de soie) et la réserve communautaire d'Anja, puis 45 km de piste difficile jusqu'à Namoly, porte nord de l'Andringitra. Nuit à la Tranogasy Guesthouse."}}, {"day": {"en": "Day 6", "fr": "Jour 6"}, "title": {"en": "Trek Andringitra → Andriamposty (2,100 m)", "fr": "Trek Andringitra → Andriamposty (2 100 m)"}, "description": {"en": "From Namoly through Betsileo villages and rice terraces, past the Riandahy and Raimbavy waterfalls, ascend to the Andohariana plateau among granite peaks, with a natural pool for a bracing swim. ~9 km, 6h, medium. Camp at Andriamposty (2,100 m).", "fr": "De Namoly à travers villages betsileo et rizières en terrasses, au-delà des cascades Riandahy et Raimbavy, montée vers le plateau d'Andohariana parmi les pics de granite, avec une piscine naturelle pour une baignade vivifiante. ~9 km, 6h, moyen. Bivouac à Andriamposty (2 100 m)."}}, {"day": {"en": "Day 7", "fr": "Jour 7"}, "title": {"en": "Trek Andringitra — summit Pic Boby (2,658 m)", "fr": "Trek Andringitra — sommet du Pic Boby (2 658 m)"}, "description": {"en": "An early ascent of Pic Boby ('close to the sky') — technically straightforward carved steps, 3–4h to the top and breathtaking high-altitude views — then descend past granite cliffs and the Gloka palm forest to camp at Iantaranomby (1,650 m). ~20 km, 8–11h, difficult.", "fr": "Ascension matinale du Pic Boby (« proche du ciel ») — marches taillées, techniquement accessible, 3 à 4h jusqu'au sommet et vues d'altitude à couper le souffle — puis descente au milieu des falaises de granite et de la palmeraie de Gloka jusqu'au bivouac d'Iantaranomby (1 650 m). ~20 km, 8–11h, difficile."}}, {"day": {"en": "Day 8", "fr": "Jour 8"}, "title": {"en": "Andringitra → Tsaranoro valley", "fr": "Andringitra → vallée du Tsaranoro"}, "description": {"en": "Descend through succulent landscapes of Pachypodium and Euphorbia and picturesque savannah to the Tsaranoro valley. ~13 km, 5–6h. Overnight at Tsarasoa Lodge.", "fr": "Descente à travers des paysages de plantes succulentes (Pachypodium, Euphorbia) et une savane pittoresque jusqu'à la vallée du Tsaranoro. ~13 km, 5–6h. Nuit au Tsarasoa Lodge."}}, {"day": {"en": "Day 9", "fr": "Jour 9"}, "title": {"en": "Tsaranoro valley — Chameleon hike", "fr": "Vallée du Tsaranoro — randonnée du Caméléon"}, "description": {"en": "A day hike (~4h up) to the summit of 'the Chameleon' for an outstanding view over the Tsaranoro valley, with a picnic lunch and endemic plants (Euphorbia, Pachypodium, aloes) along the way. Overnight at Tsarasoa Lodge.", "fr": "Randonnée à la journée (~4h de montée) jusqu'au sommet du « Caméléon » pour une vue remarquable sur la vallée du Tsaranoro, avec pique-nique et plantes endémiques (Euphorbia, Pachypodium, aloès) en chemin. Nuit au Tsarasoa Lodge."}}, {"day": {"en": "Day 10", "fr": "Jour 10"}, "title": {"en": "Tsaranoro → Ranohira (250 km, 5h)", "fr": "Tsaranoro → Ranohira (250 km, 5h)"}, "description": {"en": "Drive south into 'American West' scenery — grey mountains, red laterite, standing stones and zebu steppes — through Ihosy and the Horombe plateau to Ranohira, near Isalo. Overnight at Hotel H1 Isalo.", "fr": "Route vers le sud dans des décors de « Far West » — montagnes grises, latérite rouge, pierres levées et steppes à zébus — via Ihosy et le plateau de l'Horombe jusqu'à Ranohira, près de l'Isalo. Nuit à l'Hotel H1 Isalo."}}, {"day": {"en": "Day 11", "fr": "Jour 11"}, "title": {"en": "Trek Isalo — Canyon des Makis & Natural Pool", "fr": "Trek Isalo — Canyon des Makis & Piscine Naturelle"}, "description": {"en": "Early 4WD to Ranohira Bas, then on foot to the Canyon des Makis (lemurs), deep into gorges with 100 m cliffs, the Douche du Roi Bara, and up to a panoramic summit before camping at the Natural Pool. Camping.", "fr": "4×4 tôt le matin vers Ranohira Bas, puis à pied jusqu'au Canyon des Makis (lémuriens), au fond de gorges aux falaises de 100 m, la Douche du Roi Bara, et montée vers un sommet panoramique avant le bivouac à la Piscine Naturelle. Nuit sous tente."}}, {"day": {"en": "Day 12", "fr": "Jour 12"}, "title": {"en": "Trek Isalo — Namaza canyon", "fr": "Trek Isalo — canyon de Namaza"}, "description": {"en": "From the Panoramic Viewpoint past the Bara burial grounds and tapia forest, over the ridge above Mikaiky village, down into Namaza canyon (Isalo's three diurnal lemurs) and the Blue Pool, Black Pool and Nymphs' Waterfall. Overnight at Hotel H1 Isalo.", "fr": "Du point de vue panoramique aux sépultures bara et à la forêt de tapia, par-dessus la crête au-dessus de Mikaiky, descente dans le canyon de Namaza (les trois lémuriens diurnes de l'Isalo) et les Piscines Bleue et Noire et la Cascade des Nymphes. Nuit à l'Hotel H1 Isalo."}}, {"day": {"en": "Day 13", "fr": "Jour 13"}, "title": {"en": "Ranohira → Beroroha (155 km, 8h)", "fr": "Ranohira → Beroroha (155 km, 8h)"}, "description": {"en": "A long track north along the Isalo massif to the Mangoky River through baobab-dotted savannah; cross by ferry and camp on the riverbank, with an afternoon walk in Beroroha — the last town before the wild. Camping.", "fr": "Longue piste vers le nord le long du massif de l'Isalo jusqu'au fleuve Mangoky à travers une savane parsemée de baobabs ; traversée en bac et bivouac sur la berge, avec une marche l'après-midi à Beroroha — dernière ville avant le grand vide. Nuit sous tente."}}, {"day": {"en": "Day 14", "fr": "Jour 14"}, "title": {"en": "Beroroha → Beronono → Sariaka", "fr": "Beroroha → Beronono → Sariaka"}, "description": {"en": "65 km of track to Beronono to meet the porter team, then the start of the 5-day Makay trek — 2–3h hiking to Sariaka camp and Lake Sariaka. Camping.", "fr": "65 km de piste jusqu'à Beronono pour retrouver l'équipe de porteurs, puis début du trek de 5 jours dans le Makay — 2 à 3h de marche jusqu'au camp de Sariaka et au lac Sariaka. Nuit sous tente."}}, {"day": {"en": "Day 15", "fr": "Jour 15"}, "title": {"en": "Makay — canyon day (6–7h)", "fr": "Makay — journée canyon (6–7h)"}, "description": {"en": "Cross the Sakamantse gorges with their crystal-clear water and lush vegetation, the Behetaheta forest (wild zebu), and on to the Anosilahy canyon. Camping.", "fr": "Traversée des gorges de Sakamantse à l'eau cristalline et à la végétation luxuriante, la forêt de Behetaheta (zébus sauvages), puis le canyon d'Anosilahy. Nuit sous tente."}}, {"day": {"en": "Day 16", "fr": "Jour 16"}, "title": {"en": "Makay — Anosilahy → Andranovinily (6h)", "fr": "Makay — Anosilahy → Andranovinily (6h)"}, "description": {"en": "Over plateaus and ridges with views of the Anosilahy and Sariaka lakes, through a canyon and past a waterfall (a chance to swim) to Andranovinily camp. Camping.", "fr": "Par plateaux et crêtes avec vue sur les lacs d'Anosilahy et de Sariaka, à travers un canyon et près d'une cascade (baignade possible) jusqu'au camp d'Andranovinily. Nuit sous tente."}}, {"day": {"en": "Day 17", "fr": "Jour 17"}, "title": {"en": "Makay — Andranovinily → Beravitrahazo (6–7h)", "fr": "Makay — Andranovinily → Beravitrahazo (6–7h)"}, "description": {"en": "Deeper into the Makay's spectacular landscapes and palm forest (lemurs possible), through the Mazedrano canyon where the water can reach hip level, camping by the Makay River. Camping.", "fr": "Plus profond dans les paysages spectaculaires du Makay et sa palmeraie (lémuriens possibles), à travers le canyon de Mazedrano où l'eau peut monter jusqu'à la taille, bivouac au bord de la rivière Makay. Nuit sous tente."}}, {"day": {"en": "Day 18", "fr": "Jour 18"}, "title": {"en": "Makay — Beravitrahazo → Beronono (6–8h)", "fr": "Makay — Beravitrahazo → Beronono (6–8h)"}, "description": {"en": "Trek the eroded ruiniform sandstone plateau and visit the Mahatiny cave and its rock paintings; camp at Beronono. Camping.", "fr": "Trek sur le plateau de grès ruiniforme érodé et visite de la grotte de Mahatiny et de ses peintures rupestres ; bivouac à Beronono. Nuit sous tente."}}, {"day": {"en": "Day 19", "fr": "Jour 19"}, "title": {"en": "Beronono → Beroroha → Ranohira (9h)", "fr": "Beronono → Beroroha → Ranohira (9h)"}, "description": {"en": "Part ways with the porter team and take the 4WD back (9h of track, crossing the Mangoky) to Ranohira. Overnight at Hotel H1 Isalo.", "fr": "Séparation d'avec l'équipe de porteurs et retour en 4×4 (9h de piste, traversée du Mangoky) jusqu'à Ranohira. Nuit à l'Hotel H1 Isalo."}}, {"day": {"en": "Day 20", "fr": "Jour 20"}, "title": {"en": "Ranohira → Zombitse → Toliara (280 km, 5h)", "fr": "Ranohira → Zombitse → Toliara (280 km, 5h)"}, "description": {"en": "Drive through baobabs and thorny forest, Zombitse National Park and Mahafaly/Antandroy tombs, to Toliara. Overnight at Auberge de la Table.", "fr": "Route entre baobabs et forêt épineuse, parc national de Zombitse et tombeaux mahafaly/antandroy, jusqu'à Toliara. Nuit à l'Auberge de la Table."}}, {"day": {"en": "Day 21", "fr": "Jour 21"}, "title": {"en": "Toliara → Antananarivo (flight)", "fr": "Toliara → Antananarivo (vol)"}, "description": {"en": "Transfer to Toliara airport and fly to Antananarivo; transfer to your hotel. Overnight at Sakamanga Hotel.", "fr": "Transfert à l'aéroport de Toliara et vol vers Antananarivo ; transfert à votre hôtel. Nuit à l'hôtel Sakamanga."}}, {"day": {"en": "Day 22", "fr": "Jour 22"}, "title": {"en": "International departure", "fr": "Départ international"}, "description": {"en": "Your tour comes to an end. We arrange your transfer to Ivato Airport. Safe travels!", "fr": "Votre circuit s'achève. Nous organisons votre transfert vers l'aéroport d'Ivato. Bon retour !"}}], "priceFrom": 3990, "bestSeason": {"en": "All year round", "fr": "Toute l'année"}, "difficulty": 3, "highlights": {"en": ["Summit Pic Boby (2,658 m)", "Trek the Tsaranoro valley", "Isalo's canyons & natural pools", "Cross the remote Makay Massif"], "fr": ["Gravir le Pic Boby (2 658 m)", "Randonner la vallée du Tsaranoro", "Canyons & piscines naturelles de l'Isalo", "Traverser le massif isolé du Makay"]}, "description": {"en": "An unforgettable trekking expedition through the heart of southern Madagascar. From Antananarivo, journey via Ranomafana's rainforest to Andringitra National Park to summit Pic Boby (2,658 m), Madagascar's highest accessible peak, then trek the Tsaranoro valley and the canyons of Isalo. The expedition culminates in a five-day crossing of the remote Makay Massif — a labyrinth of sandstone canyons, waterfalls and rock paintings that remains one of the island's last true wildernesses. Experienced guides and porters accompany you throughout.", "fr": "Une expédition de trekking inoubliable au cœur du sud de Madagascar. D'Antananarivo, en passant par la forêt de Ranomafana, jusqu'au parc national d'Andringitra pour gravir le Pic Boby (2 658 m), le plus haut sommet accessible de Madagascar, puis la vallée du Tsaranoro et les canyons de l'Isalo. L'expédition culmine avec une traversée de cinq jours du massif isolé du Makay — un labyrinthe de canyons de grès, de cascades et de peintures rupestres qui demeure l'une des dernières véritables terres sauvages de l'île. Guides et porteurs expérimentés vous accompagnent tout du long."}, "notIncluded": {"en": ["Drinks", "Tips and personal purchases", "All meals (lunches and dinners)", "Travel insurance and visa", "International flights"], "fr": ["Boissons", "Pourboires et achats personnels", "Tous les repas (déjeuners et dîners)", "Assurance voyage et visa", "Vols internationaux"]}, "durationDays": 22, "macroRegions": ["highlands", "south"], "priceEstimated": true}$MW$::jsonb) on conflict (slug) do update set featured=excluded.featured, sort=excluded.sort, content=excluded.content;
insert into public.circuits (slug, featured, sort, content) values ('rivers-baobabs-wild-22d', false, 11, $MW${"slug": "rivers-baobabs-wild-22d", "tone": "ocean", "title": {"en": "Madagascar Unveiled — Rivers, Baobabs & Wild Wonders", "fr": "Madagascar dévoilé — Fleuves, baobabs & merveilles sauvages"}, "region": "Tsiribihina · Bemaraha · Belo sur Mer · Salary · Isalo · Ranomafana", "gallery": ["/images/rivers-baobabs-wild-22d-1.webp", "/images/rivers-baobabs-wild-22d-2.webp", "/images/rivers-baobabs-wild-22d-3.webp"], "summary": {"en": "A flight-free 22-day overland odyssey: the Tsiribihina river descent, the Tsingy de Bemaraha, the Avenue of the Baobabs, the wild west coast from Belo sur Mer to Salary, and the RN7's parks.", "fr": "Une odyssée terrestre de 22 jours sans vol intérieur : la descente de la Tsiribihina, les Tsingy de Bemaraha, l'Allée des Baobabs, la côte ouest sauvage de Belo sur Mer à Salary, et les parcs de la RN7."}, "category": "nature", "featured": false, "groupMax": 12, "included": {"en": ["Air-conditioned 4WD transport", "Experienced driver-guide", "Accommodation in double/twin with breakfast", "Entry fees to all mentioned parks", "Compulsory local park guides", "Driver & guide's board and lodging"], "fr": ["Transport en 4×4 climatisé", "Chauffeur-guide expérimenté", "Hébergement en chambre double/twin avec petit-déjeuner", "Droits d'entrée de tous les parcs cités", "Guides locaux obligatoires dans les parcs", "Hébergement et repas du chauffeur et du guide"]}, "itinerary": [{"day": {"en": "Day 1", "fr": "Jour 1"}, "title": {"en": "International arrival in Antananarivo", "fr": "Arrivée internationale à Antananarivo"}, "description": {"en": "Greeted at Ivato with help through formalities (SIM, currency), then the drive to your hotel across the twelve hills of Antananarivo — markets, colonial buildings and rice paddies. Overnight at Sakamanga Hotel.", "fr": "Accueil à Ivato avec assistance aux formalités (SIM, change), puis route vers votre hôtel à travers les douze collines d'Antananarivo — marchés, bâtiments coloniaux et rizières. Nuit à l'hôtel Sakamanga."}}, {"day": {"en": "Day 2", "fr": "Jour 2"}, "title": {"en": "Antananarivo → Antsirabe (170 km, 5h)", "fr": "Antananarivo → Antsirabe (170 km, 5h)"}, "description": {"en": "South on the RN7 through Behenjy's produce markets and Ambatolampy's aluminium workshops, amid red laterite and terraced paddies, to Antsirabe, the 'City of Waters', and its crater lakes Andraikiba and Tritriva. Overnight at Chambre du Voyageur.", "fr": "Vers le sud sur la RN7, marchés de Behenjy et ateliers d'aluminium d'Ambatolampy, au milieu de la latérite rouge et des rizières en terrasses, jusqu'à Antsirabe, la « ville des eaux », et ses lacs de cratère Andraikiba et Tritriva. Nuit à la Chambre du Voyageur."}}, {"day": {"en": "Day 3", "fr": "Jour 3"}, "title": {"en": "Antsirabe → Miandrivazo (220 km, 6h)", "fr": "Antsirabe → Miandrivazo (220 km, 6h)"}, "description": {"en": "A rural walk around Betafo (blacksmiths, brick-making), a picnic at Ambatomalaza hill, then on to Miandrivazo on the Tsiribihina, meeting your river guide for a briefing. Overnight at Princesse Tsiribihina.", "fr": "Balade rurale autour de Betafo (forgerons, briqueterie), pique-nique sur la colline d'Ambatomalaza, puis route vers Miandrivazo sur la Tsiribihina, où vous rencontrez votre guide fluvial pour le briefing. Nuit à la Princesse Tsiribihina."}}, {"day": {"en": "Day 4", "fr": "Jour 4"}, "title": {"en": "Miandrivazo → Tsiribihina River", "fr": "Miandrivazo → fleuve Tsiribihina"}, "description": {"en": "Board the adapted barge at Masiakampy and cruise past herons and kingfishers and Sakalava reed-hut villages, swim at Nosy Ampela waterfall (lemurs), and camp on a sandbank under the stars. Camping, full board.", "fr": "Embarquement sur la barge aménagée à Masiakampy et descente parmi hérons et martins-pêcheurs et villages sakalava aux cases de roseaux, baignade à la cascade de Nosy Ampela (lémuriens), et bivouac sur un banc de sable sous les étoiles. Nuit sous tente, pension complète."}}, {"day": {"en": "Day 5", "fr": "Jour 5"}, "title": {"en": "Tsiribihina River", "fr": "Fleuve Tsiribihina"}, "description": {"en": "Continue past cliffs, rice fields and villages (Begidro, Berevo), meet the first great baobabs at Ambatomisay, and camp on a beach with a traditional Malagasy dance by the fire. Camping, full board.", "fr": "Suite de la descente au fil des falaises, rizières et villages (Begidro, Berevo), premiers grands baobabs à Ambatomisay, et bivouac sur une plage avec une danse traditionnelle malgache autour du feu. Nuit sous tente, pension complète."}}, {"day": {"en": "Day 6", "fr": "Jour 6"}, "title": {"en": "Belo sur Tsiribihina → Bekopaka (120 km, 4h)", "fr": "Belo sur Tsiribihina → Bekopaka (120 km, 4h)"}, "description": {"en": "Morning birdwatching, a last lunch aboard, then disembark at Belo and transfer by 4WD across dry forest to Bekopaka, gateway to the Tsingy de Bemaraha. Overnight at Orchidée du Bemaraha.", "fr": "Observation des oiseaux le matin, dernier déjeuner à bord, puis débarquement à Belo et transfert en 4×4 à travers la forêt sèche jusqu'à Bekopaka, porte des Tsingy de Bemaraha. Nuit à l'Orchidée du Bemaraha."}}, {"day": {"en": "Day 7", "fr": "Jour 7"}, "title": {"en": "Tsingy de Bemaraha", "fr": "Tsingy de Bemaraha"}, "description": {"en": "A full day in the UNESCO Grands Tsingy — corridors, suspension bridges, limestone pinnacles, caves and panoramic views on a 4-hour observational walk, safely harnessed. Overnight at Orchidée du Bemaraha.", "fr": "Une journée entière dans les Grands Tsingy (UNESCO) — corridors, ponts suspendus, aiguilles calcaires, grottes et panoramas sur une marche d'observation de 4h, harnaché en sécurité. Nuit à l'Orchidée du Bemaraha."}}, {"day": {"en": "Day 8", "fr": "Jour 8"}, "title": {"en": "Bekopaka → Kirindy (200 km, 6h + ferry)", "fr": "Bekopaka → Kirindy (200 km, 6h + bac)"}, "description": {"en": "South by 4WD and ferry past decorated Sakalava tombs to Kirindy; a guided night walk for mouse lemurs, chameleons and the fossa. Overnight at Relais du Kirindy.", "fr": "Vers le sud en 4×4 et bac, devant les tombeaux sakalava décorés, jusqu'à Kirindy ; marche nocturne guidée (microcèbes, caméléons, fossa). Nuit au Relais du Kirindy."}}, {"day": {"en": "Day 9", "fr": "Jour 9"}, "title": {"en": "Kirindy → Morondava (70 km, 2h)", "fr": "Kirindy → Morondava (70 km, 2h)"}, "description": {"en": "A morning walk in Kirindy (Verreaux's sifaka), then the Avenue of the Baobabs bathed in golden sunset before Morondava. Overnight at Chez Maggie.", "fr": "Une marche matinale à Kirindy (propithèque de Verreaux), puis l'Allée des Baobabs baignée par le coucher de soleil doré avant Morondava. Nuit Chez Maggie."}}, {"day": {"en": "Day 10", "fr": "Jour 10"}, "title": {"en": "Morondava → Belo sur Mer (120 km, 4h)", "fr": "Morondava → Belo sur Mer (120 km, 4h)"}, "description": {"en": "Drive south through semi-arid country and shallow river crossings to Belo sur Mer, a fishing village of traditional shipbuilding and salt production; explore the village or relax on the beach. Overnight at Ecolodge du Menabe.", "fr": "Route vers le sud à travers une contrée semi-aride et des gués jusqu'à Belo sur Mer, village de pêcheurs réputé pour la construction navale traditionnelle et la production de sel ; découverte du village ou détente sur la plage. Nuit à l'Ecolodge du Menabe."}}, {"day": {"en": "Day 11", "fr": "Jour 11"}, "title": {"en": "Belo sur Mer", "fr": "Belo sur Mer"}, "description": {"en": "A day at leisure — traditional shipyards, snorkelling on the coral reefs, whale watching in July–August, and meeting the Vezo fishing communities. Overnight at Ecolodge du Menabe.", "fr": "Journée libre — chantiers navals traditionnels, snorkeling sur les récifs coralliens, baleines en juillet–août, et rencontre des communautés de pêcheurs vezo. Nuit à l'Ecolodge du Menabe."}}, {"day": {"en": "Day 12", "fr": "Jour 12"}, "title": {"en": "Belo sur Mer → Morombe (260 km, 7h)", "fr": "Belo sur Mer → Morombe (260 km, 7h)"}, "description": {"en": "A long, photogenic drive south, stopping at Andranopasy for ancient baobabs (Adansonia grandidieri, rubrostipa, za), reaching Morombe by evening. Overnight at Chez Katia.", "fr": "Une longue route photogénique vers le sud, arrêt à Andranopasy pour d'anciens baobabs (Adansonia grandidieri, rubrostipa, za), arrivée à Morombe en soirée. Nuit Chez Katia."}}, {"day": {"en": "Day 13", "fr": "Jour 13"}, "title": {"en": "Morombe → Salary (130 km, 5h)", "fr": "Morombe → Salary (130 km, 5h)"}, "description": {"en": "Along the coast over sandy tracks past the coves of Andavadoaka, casuarinas and baobabs, to the quiet, pristine Salary Bay; afternoon at leisure. Overnight at Salary Bay.", "fr": "Le long de la côte sur des pistes sableuses, au-delà des criques d'Andavadoaka, filaos et baobabs, jusqu'à la baie paisible et préservée de Salary ; après-midi libre. Nuit à Salary Bay."}}, {"day": {"en": "Day 14", "fr": "Jour 14"}, "title": {"en": "Salary Bay", "fr": "Baie de Salary"}, "description": {"en": "A full day of scuba diving, whale watching (July–August), pirogue excursions with Vezo fishermen, or a visit to the Mikea forest. Overnight at Salary Bay.", "fr": "Une journée entière de plongée, d'observation des baleines (juillet–août), de sorties en pirogue avec les pêcheurs vezo, ou de découverte de la forêt de Mikea. Nuit à Salary Bay."}}, {"day": {"en": "Day 15", "fr": "Jour 15"}, "title": {"en": "Salary → Ifaty (80 km, 3h)", "fr": "Salary → Ifaty (80 km, 3h)"}, "description": {"en": "South along the Mozambique Channel past fishing villages and dunes, a stop at Ankasy and the Reniala spiny forest near Toliara (baobabs, endemic birds), on to Ifaty. Overnight at La Bella Donna.", "fr": "Vers le sud le long du canal du Mozambique, villages de pêcheurs et dunes, arrêt à Ankasy et à la forêt épineuse de Reniala près de Toliara (baobabs, oiseaux endémiques), puis Ifaty. Nuit à La Bella Donna."}}, {"day": {"en": "Day 16", "fr": "Jour 16"}, "title": {"en": "Ifaty → Toliara → Ranohira (280 km, 6h)", "fr": "Ifaty → Toliara → Ranohira (280 km, 6h)"}, "description": {"en": "East across the Mahafaly plateau with its Aloalo-carved tombs, through the sapphire town of Ilakaka, to Ranohira, gateway to Isalo. Overnight at Hotel H1 Isalo.", "fr": "Vers l'est à travers le plateau Mahafaly et ses tombeaux sculptés d'aloalo, en passant par Ilakaka la ville du saphir, jusqu'à Ranohira, porte de l'Isalo. Nuit à l'Hotel H1 Isalo."}}, {"day": {"en": "Day 17", "fr": "Jour 17"}, "title": {"en": "Isalo National Park", "fr": "Parc national de l'Isalo"}, "description": {"en": "Explore Isalo's canyons, natural pools, waterfalls and sandstone formations (lemurs, endemic birds), ending at the Window of Isalo as the setting sun turns the rock to gold. Overnight at Hotel H1 Isalo.", "fr": "Exploration des canyons, piscines naturelles, cascades et formations de grès de l'Isalo (lémuriens, oiseaux endémiques), avec la Fenêtre de l'Isalo au coucher du soleil, quand la roche vire à l'or. Nuit à l'Hotel H1 Isalo."}}, {"day": {"en": "Day 18", "fr": "Jour 18"}, "title": {"en": "Ranohira → Anja → Fianarantsoa (360 km, 8h)", "fr": "Ranohira → Anja → Fianarantsoa (360 km, 8h)"}, "description": {"en": "North with a stop at Anja Community Reserve (ring-tailed lemurs, granite boulders), then Fianarantsoa and its historic hillside town. Overnight at Setam Lodge.", "fr": "Vers le nord avec un arrêt à la réserve communautaire d'Anja (makis catta, blocs de granite), puis Fianarantsoa et sa vieille ville perchée. Nuit au Setam Lodge."}}, {"day": {"en": "Day 19", "fr": "Jour 19"}, "title": {"en": "Ranomafana National Park", "fr": "Parc national de Ranomafana"}, "description": {"en": "A day hiking Ranomafana's rainforest for golden bamboo lemurs, Milne-Edwards' sifakas and the velvet asity, with waterfalls and hot springs. Overnight at Setam Lodge.", "fr": "Une journée de randonnée dans la forêt de Ranomafana pour les lémuriens à bambou doré, les propithèques de Milne-Edwards et la philépitte veloutée, avec cascades et sources chaudes. Nuit au Setam Lodge."}}, {"day": {"en": "Day 20", "fr": "Jour 20"}, "title": {"en": "Ranomafana → Antsirabe (260 km, 6h)", "fr": "Ranomafana → Antsirabe (260 km, 6h)"}, "description": {"en": "North through Ambositra, capital of Zafimaniry woodcraft — artisan workshops and markets — then Antsirabe, a colonial town of thermal springs and lively crafts. Overnight at Chambre du Voyageur.", "fr": "Vers le nord par Ambositra, capitale de la sculpture zafimaniry — ateliers d'artisans et marchés — puis Antsirabe, ville coloniale aux sources thermales et à l'artisanat vivant. Nuit à la Chambre du Voyageur."}}, {"day": {"en": "Day 21", "fr": "Jour 21"}, "title": {"en": "Antsirabe → Antananarivo (170 km, 5h)", "fr": "Antsirabe → Antananarivo (170 km, 5h)"}, "description": {"en": "Return to the capital through Merina villages and terraced rice fields, arriving for lunch and a city tour — the Manjakamiadana Palace, markets and panoramic viewpoints. Overnight at Sakamanga Hotel.", "fr": "Retour vers la capitale à travers villages merina et rizières en terrasses, arrivée pour le déjeuner et visite de la ville — le Palais de Manjakamiadana, les marchés et les points de vue. Nuit à l'hôtel Sakamanga."}}, {"day": {"en": "Day 22", "fr": "Jour 22"}, "title": {"en": "International departure", "fr": "Départ international"}, "description": {"en": "Transfer to Ivato Airport for your international flight, departing with lasting memories of Madagascar's landscapes, wildlife and culture.", "fr": "Transfert vers l'aéroport d'Ivato pour votre vol international, avec des souvenirs impérissables des paysages, de la faune et de la culture de Madagascar."}}], "priceFrom": 3690, "bestSeason": {"en": "May to November", "fr": "De mai à novembre"}, "difficulty": 2, "highlights": {"en": ["The Tsiribihina river descent", "UNESCO Tsingy de Bemaraha", "Walk among the baobabs", "Belo sur Mer & Salary Bay"], "fr": ["La descente de la Tsiribihina", "Les Tsingy de Bemaraha (UNESCO)", "Marcher parmi les baobabs", "Belo sur Mer & la baie de Salary"]}, "description": {"en": "A 22-day journey of discovery through Madagascar — entirely independent of domestic flights. From the lush Menabe to the wild west coast and the dramatic southern highlands: begin with a mesmerising descent of the Tsiribihina River, explore the otherworldly Tsingy de Bemaraha and the iconic Avenue of the Baobabs, then travel the pristine coastline from Morondava to Toliara through fishing villages, salt flats and remote bays, before following the legendary RN7 through parks brimming with wildlife and timeless cultural traditions.", "fr": "Un voyage de découverte de 22 jours à travers Madagascar — entièrement sans vol intérieur. Du Menabe luxuriant à la côte ouest sauvage et aux hautes terres du sud : débutez par une descente envoûtante du fleuve Tsiribihina, explorez les Tsingy de Bemaraha et l'emblématique Allée des Baobabs, puis longez le littoral préservé de Morondava à Toliara à travers villages de pêcheurs, marais salants et baies isolées, avant de suivre la légendaire RN7 à travers des parcs foisonnants de faune et de traditions."}, "notIncluded": {"en": ["Drinks", "Tips and personal purchases", "All meals (lunches and dinners)", "Travel insurance and visa", "International flights"], "fr": ["Boissons", "Pourboires et achats personnels", "Tous les repas (déjeuners et dîners)", "Assurance voyage et visa", "Vols internationaux"]}, "durationDays": 22, "macroRegions": ["west", "south", "highlands"], "priceEstimated": true}$MW$::jsonb) on conflict (slug) do update set featured=excluded.featured, sort=excluded.sort, content=excluded.content;

-- Destinations (8)
insert into public.destinations (slug, region, sort, content) values ('andasibe-mantadia-eastern-wonders', 'east', 0, $MW${"slug": "andasibe-mantadia-eastern-wonders", "image": "/images/destinations/andasibemantadia-madagascars-eastern-wonders.webp", "title": {"en": "Andasibe–Mantadia & Eastern Wonders", "fr": "Andasibe–Mantadia & merveilles de l'Est"}, "region": "east", "excerpt": {"en": "From the haunting calls of the Indri in Andasibe to whale watching off Sainte-Marie and the beaches of Île aux Nattes, the east blends rainforests, lemurs, orchids and island escapes.", "fr": "De l'appel envoûtant de l'Indri à Andasibe à l'observation des baleines à Sainte-Marie et aux plages de l'Île aux Nattes, l'Est mêle forêts tropicales, lémuriens, orchidées et escapades insulaires."}, "sections": [{"body": {"en": "Also known as Andasibe or Périnet, this reserve is one of Madagascar's most celebrated lemur sites, protecting over 60 families of the Indri — the largest lemur, whose dawn calls are unforgettable. A UNESCO World Heritage Site, its rainforest trails (1–5 hours) reveal woolly lemurs, bamboo lemurs, chameleons, orchids and rich birdlife.", "fr": "Aussi appelée Andasibe ou Périnet, cette réserve est l'un des sites de lémuriens les plus célèbres de Madagascar, abritant plus de 60 familles d'Indris — le plus grand lémurien, dont le chant à l'aube est inoubliable. Classée UNESCO, ses sentiers de forêt tropicale (1 à 5h) dévoilent lémuriens laineux et à bambou, caméléons, orchidées et une avifaune riche."}, "heading": {"en": "Analamazaotra — Sanctuary of the Indri", "fr": "Analamazaotra — Sanctuaire de l'Indri"}}, {"body": {"en": "North of Andasibe, Mantadia offers a wilder, less-visited primary rainforest with 14 lemur species — diademed sifakas, black-and-white ruffed lemurs — over 100 birds, and Madagascar's largest chameleon, Parson's. Day hikes lead to the Sacred Waterfall; night walks reveal remarkable amphibian diversity.", "fr": "Au nord d'Andasibe, Mantadia offre une forêt primaire plus sauvage et moins fréquentée, avec 14 espèces de lémuriens — propithèques à diadème, varis noir et blanc — plus de 100 oiseaux et le plus grand caméléon de l'île, le Parson. Les randonnées mènent à la Cascade Sacrée ; les marches nocturnes révèlent une diversité d'amphibiens remarquable."}, "heading": {"en": "Mantadia — Wild Rainforest Adventure", "fr": "Mantadia — Aventure en forêt sauvage"}}, {"body": {"en": "Meaning 'hot water' for its thermal springs, this 435 km² mountainous rainforest became a UNESCO site after the 1986 discovery of the golden bamboo lemur. It shelters 12 lemur species, 118 birds and countless reptiles among tree ferns, orchids and bamboo, and hosts the Centre ValBio research station.", "fr": "« Eau chaude » en malgache, pour ses sources thermales, cette forêt de montagne de 435 km² est classée UNESCO depuis la découverte du lémurien à bambou doré en 1986. Elle abrite 12 espèces de lémuriens, 118 oiseaux et d'innombrables reptiles parmi fougères arborescentes, orchidées et bambous, ainsi que la station de recherche Centre ValBio."}, "heading": {"en": "Ranomafana — Realm of the Golden Bamboo Lemur", "fr": "Ranomafana — Royaume du lémurien à bambou doré"}}, {"body": {"en": "East of Lake Alaotra, this rugged, little-explored park is among the island's most biodiverse: 13 lemurs including indri and aye-aye, the fossa, and 112 bird species (67 endemic). Accommodation is basic, making camping the best way to immerse in its waterfalls and untouched rainforest.", "fr": "À l'est du lac Alaotra, ce parc accidenté et peu exploré compte parmi les plus riches de l'île : 13 lémuriens dont l'indri et l'aye-aye, le fossa, et 112 espèces d'oiseaux (67 endémiques). L'hébergement est sommaire ; le bivouac est le meilleur moyen de s'immerger dans ses cascades et sa forêt intacte."}, "heading": {"en": "Zahamena — Madagascar's Hidden Rainforest", "fr": "Zahamena — La forêt cachée de Madagascar"}}, {"body": {"en": "Also called Nosy Boraha, this 'Garden Island' is famed for tropical beaches, waterfalls, coral reefs and pirate history. From July to September thousands of humpback whales migrate along its coast. Cycling, pirogue rides, snorkelling and a relaxed island rhythm complete the experience.", "fr": "Aussi appelée Nosy Boraha, cette « île jardin » est réputée pour ses plages tropicales, cascades, récifs coralliens et son histoire de pirates. De juillet à septembre, des milliers de baleines à bosse migrent le long de ses côtes. Vélo, balades en pirogue, snorkeling et rythme insulaire paisible complètent l'expérience."}, "heading": {"en": "Sainte-Marie — The Island of Whales", "fr": "Sainte-Marie — L'île aux baleines"}}, {"body": {"en": "On a peninsula of Lake Ampitabe along the Pangalanes Canal, this 35-hectare reserve shelters tame lemurs — indris, crowned and ruffed lemurs, and the elusive aye-aye, best seen on night walks — amid nearly 100,000 palms, orchids and lakeside eco-lodges.", "fr": "Sur une presqu'île du lac Ampitabe, le long du canal des Pangalanes, cette réserve de 35 hectares abrite des lémuriens familiers — indris, lémuriens couronnés et varis, et l'insaisissable aye-aye, à observer de nuit — parmi près de 100 000 palmiers, des orchidées et des éco-lodges au bord de l'eau."}, "heading": {"en": "Palmarium (Ankanin'ny Nofy) — The Nest of Dreams", "fr": "Palmarium (Ankanin'ny Nofy) — Le nid de rêve"}}, {"body": {"en": "South of Sainte-Marie, this car-free island (Nosy Nato) offers white sand, turquoise lagoons and coral-rich waters reached only by pirogue. Snorkel, dive and swim, climb to the lighthouse for reef views, and — in August — watch humpback whales offshore.", "fr": "Au sud de Sainte-Marie, cette île sans voiture (Nosy Nato) offre sable blanc, lagons turquoise et eaux coralliennes, accessible uniquement en pirogue. Snorkeling, plongée et baignade, montée au phare pour la vue sur le récif, et — en août — observation des baleines à bosse au large."}, "heading": {"en": "Île aux Nattes — A Pristine Tropical Escape", "fr": "Île aux Nattes — Une échappée tropicale préservée"}}], "regionLabel": {"en": "Eastern Wonders", "fr": "Merveilles de l'Est"}}$MW$::jsonb) on conflict (slug) do update set region=excluded.region, sort=excluded.sort, content=excluded.content;
insert into public.destinations (slug, region, sort, content) values ('antananarivo-central-highlands', 'highlands', 1, $MW${"slug": "antananarivo-central-highlands", "image": "/images/destinations/antananarivo-madagascars-central-highlands.webp", "title": {"en": "Antananarivo & the Central Highlands", "fr": "Antananarivo & les Hautes Terres"}, "region": "highlands", "excerpt": {"en": "Royal palaces and lively markets of Antananarivo, the crater lakes of Antsirabe, Ambositra's woodcarving, scenic railways and the peaks of Andringitra — the highlands blend history, culture and nature.", "fr": "Palais royaux et marchés animés d'Antananarivo, lacs de cratère d'Antsirabe, sculpture sur bois d'Ambositra, trains panoramiques et sommets de l'Andringitra — les Hautes Terres mêlent histoire, culture et nature."}, "sections": [{"body": {"en": "The capital balances royal palaces, bustling markets and green spaces across its twelve hills. South lies Antsirabe, the 'City of Water,' with colonial architecture, thermal springs and the volcanic crater lakes of Tritriva and Andraikiba — and the cascading rice terraces of nearby Betafo.", "fr": "La capitale conjugue palais royaux, marchés animés et espaces verts sur ses douze collines. Au sud, Antsirabe, la « ville des eaux », séduit par son architecture coloniale, ses sources thermales et les lacs de cratère de Tritriva et Andraikiba — ainsi que les rizières en terrasses de Betafo."}, "heading": {"en": "Antananarivo & Antsirabe", "fr": "Antananarivo & Antsirabe"}}, {"body": {"en": "In the rolling hills near Ambositra, the Zafimaniry villages preserve a UNESCO-listed woodcarving tradition — watch artisans create intricate houses and objects. Ambositra itself, capital of Malagasy craftsmanship, brims with carved furniture, markets and charming streets.", "fr": "Dans les collines autour d'Ambositra, les villages Zafimaniry perpétuent une tradition de sculpture sur bois classée UNESCO — on y observe les artisans façonner maisons et objets ciselés. Ambositra, capitale de l'artisanat malgache, regorge de meubles sculptés, de marchés et de rues pittoresques."}, "heading": {"en": "Ambositra & the Zafimaniry Villages", "fr": "Ambositra & les villages Zafimaniry"}}, {"body": {"en": "Fianarantsoa, the cultural heart of the highlands, charms with cobblestone streets and a historic old town. From here the legendary Fianarantsoa–Côte Est railway winds through rainforests and villages to Manakara, while nearby Sahambavy is Madagascar's only tea estate.", "fr": "Fianarantsoa, cœur culturel des Hautes Terres, séduit par ses ruelles pavées et sa vieille ville historique. De là, le légendaire chemin de fer Fianarantsoa–Côte Est serpente à travers forêts et villages jusqu'à Manakara, tandis que Sahambavy, tout près, est l'unique plantation de thé de Madagascar."}, "heading": {"en": "Fianarantsoa, the FCE Train & Sahambavy Tea", "fr": "Fianarantsoa, le train FCE & le thé de Sahambavy"}}, {"body": {"en": "A lively highland town, Ambalavao is famous for handmade Antemoro paper pressed with flowers, its vineyards and its bustling weekly zebu market. The nearby Anja Community Reserve is a highlight, where iconic ring-tailed lemurs can be observed among dramatic granite boulders.", "fr": "Ville animée des Hautes Terres, Ambalavao est réputée pour son papier Antemoro orné de fleurs, ses vignobles et son grand marché aux zébus hebdomadaire. Tout près, la réserve communautaire d'Anja est un temps fort : on y observe les emblématiques makis catta parmi de spectaculaires blocs de granite."}, "heading": {"en": "Ambalavao & Anja Park", "fr": "Ambalavao & le parc d'Anja"}}, {"body": {"en": "A UNESCO World Heritage Site, Andringitra dazzles with granite peaks, valleys and waterfalls. Its ultimate challenge is Pic Boby (2,658 m), the country's second-highest summit, with over 100 km of trails. The nearby Tsaranoro Valley impresses with soaring cliffs, climbing routes and traditional villages.", "fr": "Classé au patrimoine mondial de l'UNESCO, l'Andringitra éblouit par ses pics de granite, ses vallées et ses cascades. Son défi ultime est le Pic Boby (2 658 m), deuxième plus haut sommet du pays, avec plus de 100 km de sentiers. La vallée du Tsaranoro voisine impressionne par ses falaises, ses voies d'escalade et ses villages traditionnels."}, "heading": {"en": "Andringitra & the Tsaranoro Valley", "fr": "Andringitra & la vallée du Tsaranoro"}}], "regionLabel": {"en": "Central Highlands", "fr": "Hautes Terres centrales"}}$MW$::jsonb) on conflict (slug) do update set region=excluded.region, sort=excluded.sort, content=excluded.content;
insert into public.destinations (slug, region, sort, content) values ('isalo-southwest', 'south', 2, $MW${"slug": "isalo-southwest", "image": "/images/destinations/isalo-national-park-southwest-madagascar.webp", "title": {"en": "Isalo & the Southwest", "fr": "L'Isalo & le Sud-Ouest"}, "region": "south", "excerpt": {"en": "The dramatic canyons of Isalo, the birdlife of Zombitse, Toliara's cultural gateway and coastal gems like Anakao and Ifaty — with spiny forests, salt lakes and the untouched Makay Massif.", "fr": "Les canyons spectaculaires de l'Isalo, l'avifaune de Zombitse, Toliara la porte culturelle et les joyaux côtiers d'Anakao et Ifaty — entre forêts épineuses, lacs salés et le massif préservé du Makay."}, "sections": [{"body": {"en": "Covering 820 km² of Jurassic sandstone sculpted into ridges and canyons, Isalo is often compared to the American West. Trails lead to natural pools, waterfalls and the famous Piscine Naturelle, amid 14 lemur species and 80 birds. Bara burial caves add cultural depth to its dramatic scenery.", "fr": "S'étendant sur 820 km² de grès jurassique sculpté en crêtes et canyons, l'Isalo est souvent comparé au Far West. Ses sentiers mènent à des piscines naturelles, des cascades et la célèbre Piscine Naturelle, parmi 14 espèces de lémuriens et 80 oiseaux. Les grottes funéraires Bara ajoutent une profondeur culturelle à ses paysages spectaculaires."}, "heading": {"en": "Isalo — A Jurassic Sandstone Wonderland", "fr": "Isalo — Un Colorado jurassique de grès"}}, {"body": {"en": "This often-overlooked dry deciduous forest is a vital transition zone with 85 bird species — nearly half of Madagascar's endemics, including the rare Appert's Greenbul — and eight lemur species among baobabs and orchids. The surrounding Tandroy and Mahafaly communities are known for ornate tombs.", "fr": "Cette forêt sèche décidue souvent négligée est une zone de transition majeure : 85 espèces d'oiseaux — près de la moitié des endémiques de l'île, dont le rare bulbul d'Appert — et huit espèces de lémuriens parmi baobabs et orchidées. Les communautés antandroy et mahafaly voisines sont réputées pour leurs tombeaux décorés."}, "heading": {"en": "Zombitse–Vohibasia — Bird & Lemur Haven", "fr": "Zombitse–Vohibasia — Refuge d'oiseaux & lémuriens"}}, {"body": {"en": "Capital of the south, Toliara enjoys year-round sunshine, broad avenues, colourful pousse-pousse and lively tsapiky music. Day trips reach the Antsokay Arboretum, Table Mountain, Saint Augustin's Bay, the Sarodrano Caves and the Honko mangrove reserve.", "fr": "Capitale du sud, Toliara jouit d'un ensoleillement permanent, de larges avenues, de pousse-pousse colorés et de la musique tsapiky. Les excursions rejoignent l'Arboretum d'Antsokay, la Table, la baie de Saint-Augustin, les grottes de Sarodrano et la réserve de mangrove de Honko."}, "heading": {"en": "Toliara — Gateway to the Southwest", "fr": "Toliara — Porte du Sud-Ouest"}}, {"body": {"en": "Reached only by boat, Anakao is an authentic Vezo fishing village of turquoise waters and golden beaches. Surf, kitesurf, snorkel, dive and watch whales (July–September), visit Nosy Ve by pirogue or explore Tsimanampetsotsa, all wrapped in strong coastal traditions.", "fr": "Accessible uniquement par bateau, Anakao est un authentique village de pêcheurs vezo aux eaux turquoise et plages dorées. Surf, kitesurf, snorkeling, plongée et baleines (juillet–septembre), visite de Nosy Ve en pirogue ou du Tsimanampetsotsa, le tout porté par de fortes traditions côtières."}, "heading": {"en": "Anakao — Vezo Village & Coastal Adventure", "fr": "Anakao — Village vezo & aventure côtière"}}, {"body": {"en": "North of Toliara, Ifaty and Mangily share long sandy beaches and access to the spiny forest, with over 300 sunny days a year for diving, snorkelling and whale watching. The Reniala Private Reserve protects ancient baobabs; private dinners beneath the giants add a touch of romance.", "fr": "Au nord de Toliara, Ifaty et Mangily partagent de longues plages de sable et l'accès à la forêt épineuse, avec plus de 300 jours de soleil par an pour la plongée, le snorkeling et l'observation des baleines. La réserve privée de Reniala protège des baobabs centenaires ; les dîners privés sous les géants ajoutent une touche romantique."}, "heading": {"en": "Ifaty–Mangily — Beaches & Spiny Forest", "fr": "Ifaty–Mangily — Plages & forêt épineuse"}}, {"body": {"en": "This unique park protects a vast saline lake shimmering from turquoise to emerald, home to flamingos and 110 bird species, five lemurs, radiated tortoises and Grandidier's mongoose, amid spiny forests, baobabs, dunes and limestone caves with underground rivers.", "fr": "Ce parc unique protège un vaste lac salé aux reflets turquoise et émeraude, refuge de flamants et de 110 espèces d'oiseaux, cinq lémuriens, tortues radiées et mangouste de Grandidier, entre forêts épineuses, baobabs, dunes et grottes calcaires aux rivières souterraines."}, "heading": {"en": "Tsimanampetsotsa — Salt Lake & Endemic Wildlife", "fr": "Tsimanampetsotsa — Lac salé & faune endémique"}}, {"body": {"en": "A remote, largely unexplored range of deep canyons, turquoise basins and dense forests, accessible only in the dry season (May–November). Its isolation preserves over 300 plant species, newly discovered flora and rock-painting sites — a paradise for trekkers seeking true wilderness.", "fr": "Chaîne isolée et largement inexplorée de canyons profonds, de vasques turquoise et de forêts denses, accessible seulement en saison sèche (mai–novembre). Son isolement préserve plus de 300 espèces végétales, des plantes nouvellement découvertes et des sites de peintures rupestres — un paradis pour les trekkeurs en quête de nature intacte."}, "heading": {"en": "Makay Massif — The Last Eden", "fr": "Massif du Makay — Le dernier Éden"}}], "regionLabel": {"en": "Southwest", "fr": "Sud-Ouest"}}$MW$::jsonb) on conflict (slug) do update set region=excluded.region, sort=excluded.sort, content=excluded.content;
insert into public.destinations (slug, region, sort, content) values ('mahajanga-northwest', 'west', 3, $MW${"slug": "mahajanga-northwest", "image": "/images/destinations/mahajanga-northwest-madagascar.webp", "title": {"en": "Mahajanga & the Northwest", "fr": "Mahajanga & le Nord-Ouest"}, "region": "west", "excerpt": {"en": "The birdwatching haven of Ankarafantsika, Mahajanga's vibrant coastal culture, and rare wildlife in Sahamalaza, Baie de Baly and Bemanevika — from coral reefs to crater lakes.", "fr": "Le paradis ornithologique d'Ankarafantsika, la culture côtière vibrante de Mahajanga, et une faune rare à Sahamalaza, la Baie de Baly et Bemanevika — des récifs coralliens aux lacs de cratère."}, "sections": [{"body": {"en": "The 'Kingdom of Birds' spans over 130,000 hectares of lakes, canyon and dry forest, sheltering 129 bird species and eight lemurs such as Coquerel's sifaka. Its Ampijoroa station is the world's most important breeding site for the endangered ploughshare and flat-tailed tortoises.", "fr": "Le « royaume des oiseaux » couvre plus de 130 000 hectares de lacs, canyon et forêt sèche, abritant 129 espèces d'oiseaux et huit lémuriens comme le propithèque de Coquerel. Sa station d'Ampijoroa est le site de reproduction le plus important au monde pour les tortues à soc et à queue plate, menacées."}, "heading": {"en": "Ankarafantsika — Bird & Lemur Sanctuary", "fr": "Ankarafantsika — Sanctuaire d'oiseaux & lémuriens"}}, {"body": {"en": "A vibrant port city founded by Arab traders, Mahajanga blends Arab, Swahili, Comorian and Indian influences and is famed as Madagascar's culinary capital. Palm-lined boulevards, colonial façades, a 1,000-year-old baobab and the lively seaside 'Bord' define its tropical charm.", "fr": "Ville portuaire vibrante fondée par des marchands arabes, Mahajanga mêle influences arabes, swahilies, comoriennes et indiennes, et passe pour la capitale gastronomique de Madagascar. Boulevards bordés de palmiers, façades coloniales, un baobab millénaire et le « Bord » de mer animé font tout son charme tropical."}, "heading": {"en": "Mahajanga — The City of Flowers", "fr": "Mahajanga — La cité des fleurs"}}, {"body": {"en": "A UNESCO Biosphere Reserve spanning 260 km² (half marine), Sahamalaza combines coral reefs, mangroves and dry forests where 40% of species are endemic. It shelters the blue-eyed black lemur and, offshore, 170 fish species, sea turtles and dolphins.", "fr": "Réserve de biosphère de l'UNESCO de 260 km² (dont la moitié marine), Sahamalaza combine récifs coralliens, mangroves et forêts sèches où 40 % des espèces sont endémiques. Elle abrite le lémurien aux yeux turquoise et, au large, 170 espèces de poissons, tortues marines et dauphins."}, "heading": {"en": "Sahamalaza — Marine & Forest Treasure", "fr": "Sahamalaza — Trésor marin & forestier"}}, {"body": {"en": "This 58 km² park of forests, mangroves, beaches and reefs is the last refuge of the critically endangered ploughshare tortoise. White-sand beaches, nesting turtle sites and baobab thickets host eight lemurs, 120 birds, dolphins and dugongs in a pristine coastal setting.", "fr": "Ce parc de 58 km² de forêts, mangroves, plages et récifs est le dernier refuge de la tortue à soc, au bord de l'extinction. Plages de sable blanc, sites de ponte des tortues et fourrés de baobabs accueillent huit lémuriens, 120 oiseaux, dauphins et dugongs dans un cadre côtier préservé."}, "heading": {"en": "Baie de Baly — Coastal Gem", "fr": "Baie de Baly — Joyau côtier"}}, {"body": {"en": "An untouched sanctuary of crater lakes, marshes and highland forests, Bemanevika is world-famous as the only home of the Madagascar pochard, once thought extinct until rediscovered here. The Madagascar red owl and serpent eagle add to a paradise for ornithologists.", "fr": "Sanctuaire intact de lacs de cratère, marais et forêts d'altitude, Bemanevika est mondialement connu comme l'unique habitat du fuligule de Madagascar, cru éteint jusqu'à sa redécouverte ici. La phodile rousse et le serpentaire complètent un paradis pour ornithologues."}, "heading": {"en": "Bemanevika — Lakes & Rare Birds", "fr": "Bemanevika — Lacs & oiseaux rares"}}], "regionLabel": {"en": "Northwest", "fr": "Nord-Ouest"}}$MW$::jsonb) on conflict (slug) do update set region=excluded.region, sort=excluded.sort, content=excluded.content;
insert into public.destinations (slug, region, sort, content) values ('masoala-northeast', 'east', 4, $MW${"slug": "masoala-northeast", "image": "/images/destinations/masoala-northeast-madagascar.webp", "title": {"en": "Masoala & the Northeast", "fr": "Masoala & le Nord-Est"}, "region": "east", "excerpt": {"en": "Masoala's vast rainforest, Nosy Mangabe's island wildlife, Farankaraina's aye-ayes and Marojejy's soaring peaks — a paradise of rare species, marine reserves and remote forests.", "fr": "La vaste forêt de Masoala, la faune insulaire de Nosy Mangabe, les aye-ayes de Farankaraina et les pics de Marojejy — un paradis d'espèces rares, de réserves marines et de forêts reculées."}, "sections": [{"body": {"en": "Madagascar's largest protected area (240,520 ha) and a UNESCO World Heritage Site, Masoala runs from sea to 1,311 m, harbouring 2% of global biodiversity — aye-aye, red-ruffed lemur, 130+ butterflies. It also protects 10,000 ha of coral reefs and seagrass in Antongil Bay, with dolphins, turtles and humpback whales (Jul–Sep).", "fr": "Plus vaste aire protégée de Madagascar (240 520 ha) et site du patrimoine mondial de l'UNESCO, Masoala s'étend de la mer à 1 311 m et abrite 2 % de la biodiversité mondiale — aye-aye, vari roux, plus de 130 papillons. Elle protège aussi 10 000 ha de récifs coralliens et herbiers dans la baie d'Antongil, avec dauphins, tortues et baleines à bosse (juil.–sept.)."}, "heading": {"en": "Masoala — Largest Rainforest & Marine Paradise", "fr": "Masoala — Plus grande forêt & paradis marin"}}, {"body": {"en": "Just 5 km from Maroantsetra, this forest-clad island is renowned for aye-ayes and 16th-century Dutch sailor carvings. Antongil Bay, the 'Cradle of Whales,' welcomes humpbacks from June to September. Trails lead to waterfalls, ancient graves and viewpoints over golden beaches.", "fr": "À seulement 5 km de Maroantsetra, cette île couverte de forêt est réputée pour ses aye-ayes et ses gravures de marins hollandais du XVIᵉ siècle. La baie d'Antongil, « berceau des baleines », accueille les baleines à bosse de juin à septembre. Ses sentiers mènent à des cascades, d'anciennes tombes et des points de vue sur des plages dorées."}, "heading": {"en": "Nosy Mangabe — Island of Aye-Ayes & Whales", "fr": "Nosy Mangabe — Île des aye-ayes & des baleines"}}, {"body": {"en": "Reached by boat and a short trek from Maroantsetra, Farankaraina is one of the finest places to see the elusive aye-aye in the wild, alongside bamboo lemurs, giant leaf-tailed geckos, streaked tenrecs and couas — a prime site for trekking and photography.", "fr": "Accessible en bateau puis une courte marche depuis Maroantsetra, Farankaraina est l'un des meilleurs endroits pour observer l'insaisissable aye-aye en liberté, aux côtés de lémuriens à bambou, geckos à queue plate géants, tenrecs et couas — un site de choix pour le trek et la photo."}, "heading": {"en": "Farankaraina — Best Place to See the Aye-Aye", "fr": "Farankaraina — Le meilleur site pour l'aye-aye"}}, {"body": {"en": "A UNESCO World Heritage Site of steep cliffs, waterfalls and dense rainforest, Marojejy (55,500 ha) shelters 11 lemur species including the critically endangered silky sifaka. Treks range from day hikes to multi-day expeditions; best visited April–May and September–December.", "fr": "Site du patrimoine mondial de l'UNESCO aux falaises abruptes, cascades et forêt dense, Marojejy (55 500 ha) abrite 11 espèces de lémuriens dont le propithèque soyeux, au bord de l'extinction. Les treks vont de la journée à l'expédition de plusieurs jours ; meilleure période d'avril à mai et de septembre à décembre."}, "heading": {"en": "Marojejy — Towering Rainforest Peaks", "fr": "Marojejy — Pics de forêt tropicale"}}, {"body": {"en": "One of Madagascar's most sensitive zones, home to the golden-crowned sifaka, Sanford's brown lemur and aye-aye, plus around 130 birds and 75 reptiles. With little infrastructure, camping at the forest edge offers a true wilderness experience.", "fr": "L'une des zones les plus sensibles de Madagascar, refuge du propithèque à couronne dorée, du lémurien brun de Sanford et de l'aye-aye, plus environ 130 oiseaux et 75 reptiles. Avec peu d'infrastructures, le bivouac en lisière offre une véritable immersion sauvage."}, "heading": {"en": "Daraina–Loky Manambato — Golden-Crowned Sifaka", "fr": "Daraina–Loky Manambato — Le propithèque à couronne dorée"}}, {"body": {"en": "Pristine rainforest from 500 m to 2,064 m, famous for the black indri, the silky sifaka and the 'living fossil' tree Takhtajania perrieri, 120 million years old. Its name means 'Place of the Great God' — rugged treks and camping at Camp Indri immerse you in unique wildlife.", "fr": "Forêt tropicale intacte de 500 à 2 064 m, célèbre pour l'indri noir, le propithèque soyeux et l'arbre « fossile vivant » Takhtajania perrieri, vieux de 120 millions d'années. Son nom signifie « lieu du Grand Dieu » — treks accidentés et bivouac au Camp Indri plongent dans une faune unique."}, "heading": {"en": "Anjanaharibe-Sud — Remote Mountain Rainforest", "fr": "Anjanaharibe-Sud — Forêt de montagne isolée"}}], "regionLabel": {"en": "Northeast", "fr": "Nord-Est"}}$MW$::jsonb) on conflict (slug) do update set region=excluded.region, sort=excluded.sort, content=excluded.content;
insert into public.destinations (slug, region, sort, content) values ('nosy-be-northern', 'north', 5, $MW${"slug": "nosy-be-northern", "image": "/images/destinations/nosy-be-northern-madagascar.webp", "title": {"en": "Nosy Be & the North", "fr": "Nosy Be & le Nord"}, "region": "north", "excerpt": {"en": "Amber Mountain's lush forests, Ankarana's limestone tsingy and Diego Suarez's charm meet the pristine islands of Nosy Be — rare lemurs, chameleons, coral reefs and emerald lagoons.", "fr": "Les forêts luxuriantes de la Montagne d'Ambre, les tsingy calcaires de l'Ankarana et le charme de Diego Suarez rencontrent les îles préservées de Nosy Be — lémuriens et caméléons rares, récifs coralliens et lagons émeraude."}, "sections": [{"body": {"en": "One of Madagascar's first protected areas (182 km²), this cool volcanic massif offers six lakes, three waterfalls and 30 km of trails to Sacred Falls and the 1,475 m summit. Crowned lemurs, chameleons, leaf-tailed geckos and 75 bird species thrive in its refreshing forests.", "fr": "L'une des premières aires protégées de Madagascar (182 km²), ce massif volcanique frais offre six lacs, trois cascades et 30 km de sentiers vers les Cascades Sacrées et le sommet à 1 475 m. Lémuriens couronnés, caméléons, geckos à queue plate et 75 espèces d'oiseaux peuplent ses forêts rafraîchissantes."}, "heading": {"en": "Amber Mountain — Lush Volcanic Rainforest", "fr": "Montagne d'Ambre — Forêt volcanique luxuriante"}}, {"body": {"en": "Dramatic limestone pinnacles (tsingy), canyons and Africa's largest underground cave system (120+ km) define Ankarana. Explore sinkholes, suspension bridges, the Green Lake and Crocodile Caves, amid lemurs and 350+ plant species, while the Antankarana keep sacred sites alive.", "fr": "Spectaculaires aiguilles calcaires (tsingy), canyons et le plus grand réseau de grottes souterraines d'Afrique (120+ km) définissent l'Ankarana. Avens, ponts suspendus, Lac Vert et Grottes aux Crocodiles, parmi lémuriens et plus de 350 espèces végétales, tandis que les Antankarana perpétuent leurs sites sacrés."}, "heading": {"en": "Ankarana — Limestone Fortress Adventure", "fr": "Ankarana — L'aventure de la forteresse calcaire"}}, {"body": {"en": "Unique to the north, the Red Tsingy are vivid red and orange sandstone spires carved by erosion in a small canyon near Ankarana. Constantly reshaped by wind and rain, these colourful formations are among the region's most photographed wonders.", "fr": "Uniques au nord, les Tsingy Rouges sont des aiguilles de grès rouge et orange sculptées par l'érosion dans un petit canyon près de l'Ankarana. Sans cesse remodelées par le vent et la pluie, ces formations colorées comptent parmi les merveilles les plus photographiées de la région."}, "heading": {"en": "The Red Tsingy — Sandstone Needles", "fr": "Les Tsingy Rouges — Aiguilles de grès"}}, {"body": {"en": "Blending French colonial charm and Malagasy culture on a vast bay, Diego Suarez is the gateway to Amber Mountain and Ankarana. Nearby, the 'Three Bays' offer surfing and scenic beaches, and Cape Ambre reveals striking limestone formations like Windsor Castle.", "fr": "Mêlant charme colonial français et culture malgache sur une vaste baie, Diego Suarez est la porte de la Montagne d'Ambre et de l'Ankarana. Tout près, les « Trois Baies » offrent surf et plages panoramiques, et le Cap d'Ambre révèle des formations calcaires saisissantes comme le Windsor Castle."}, "heading": {"en": "Antsiranana (Diego Suarez) — Gateway to the North", "fr": "Antsiranana (Diego Suarez) — Porte du Nord"}}, {"body": {"en": "At the entrance of Diego Bay, this 34 km² protected lagoon glows emerald-green over shallow sandy bottoms. Surrounded by islets, it is ideal for snorkelling, kitesurfing and windsurfing (June–October), with seafood picnics and sailing day trips.", "fr": "À l'entrée de la baie de Diego, ce lagon protégé de 34 km² brille d'un vert émeraude au-dessus de fonds sableux peu profonds. Entouré d'îlots, il est idéal pour le snorkeling, le kitesurf et la planche à voile (juin–octobre), avec pique-niques de fruits de mer et sorties en voilier."}, "heading": {"en": "The Emerald Sea — Lagoon of Diego Bay", "fr": "La Mer d'Émeraude — Lagon de la baie de Diego"}}, {"body": {"en": "Just outside Diego Suarez, this 5,000-hectare reserve protects dry forest, limestone cliffs and caves, home to endemic baobabs, Sanford's brown lemurs and rich birdlife. Trails reach panoramic viewpoints and colonial ruins, with 15 km of caves and climbing routes nearby.", "fr": "Aux portes de Diego Suarez, cette réserve de 5 000 hectares protège forêt sèche, falaises calcaires et grottes, refuge de baobabs endémiques, de lémuriens bruns de Sanford et d'une avifaune riche. Ses sentiers mènent à des points de vue panoramiques et des ruines coloniales, avec 15 km de grottes et de voies d'escalade à proximité."}, "heading": {"en": "Montagne des Français — Dry Forests & Cliffs", "fr": "Montagne des Français — Forêts sèches & falaises"}}, {"body": {"en": "This 73,319-hectare reserve, 100 km south of Diego Suarez, is the last stronghold of the critically endangered Perrier's sifaka. Multi-day 4x4 visits combine guided hikes, night walks for nocturnal species and encounters with local culture.", "fr": "Cette réserve de 73 319 hectares, à 100 km au sud de Diego Suarez, est le dernier bastion du propithèque de Perrier, au bord de l'extinction. Les visites de plusieurs jours en 4×4 associent randonnées guidées, marches nocturnes pour les espèces nocturnes et rencontres avec la culture locale."}, "heading": {"en": "Andrafiamena–Andavakoera — Perrier's Sifaka", "fr": "Andrafiamena–Andavakoera — Le propithèque de Perrier"}}, {"body": {"en": "Madagascar's premier tropical destination combines resorts, ylang-ylang plantations and rich marine life — diving, whale-shark safaris and the Lokobe Reserve's black lemurs. The archipelago includes Nosy Komba (Lemur Island), Nosy Tanikely (marine reserve) and Nosy Iranja's famous twin islands and sandbar.", "fr": "Destination tropicale phare de Madagascar, Nosy Be conjugue resorts, plantations d'ylang-ylang et vie marine foisonnante — plongée, safaris requins-baleines et les lémuriens noirs de la réserve de Lokobe. L'archipel comprend Nosy Komba (l'île aux Lémuriens), Nosy Tanikely (réserve marine) et les célèbres îles jumelles et banc de sable de Nosy Iranja."}, "heading": {"en": "Nosy Be & Surrounding Islands", "fr": "Nosy Be & les îles voisines"}}], "regionLabel": {"en": "Northern", "fr": "Nord"}}$MW$::jsonb) on conflict (slug) do update set region=excluded.region, sort=excluded.sort, content=excluded.content;
insert into public.destinations (slug, region, sort, content) values ('western-tsingy-baobabs', 'west', 6, $MW${"slug": "western-tsingy-baobabs", "image": "/images/destinations/western-madagascar-tsingy-baobabs-wildlife.webp", "title": {"en": "Western Madagascar — Tsingy & Baobabs", "fr": "Grand Ouest — Tsingy & Baobabs"}, "region": "west", "excerpt": {"en": "The jagged tsingy of Bemaraha, Kirindy's nocturnal wildlife, the serene Tsiribihina River and Morondava's iconic Avenue of the Baobabs — landscapes found nowhere else on Earth.", "fr": "Les tsingy acérés du Bemaraha, la faune nocturne de Kirindy, le paisible fleuve Tsiribihina et la mythique Allée des Baobabs de Morondava — des paysages uniques au monde."}, "sections": [{"body": {"en": "A UNESCO World Heritage Site since 1990, Bemaraha's limestone plateaus form jagged pinnacles, deep canyons and the Manambolo Gorge. It harbours 13 lemur species, 100+ birds and 650 plants (85% endemic). Explore via suspension bridges and trails — remote, and accessible only in the dry season (May–November).", "fr": "Site du patrimoine mondial de l'UNESCO depuis 1990, les plateaux calcaires du Bemaraha forment aiguilles acérées, canyons profonds et la Gorge de la Manambolo. Il abrite 13 espèces de lémuriens, plus de 100 oiseaux et 650 plantes (85 % endémiques). Exploration par ponts suspendus et sentiers — isolé, accessible seulement en saison sèche (mai–novembre)."}, "heading": {"en": "Tsingy de Bemaraha — Stone Forest of Wonders", "fr": "Tsingy de Bemaraha — La forêt de pierre"}}, {"body": {"en": "This 120 km² deciduous dry forest is the best place to see Madagascar's top predator, the fossa — especially during its November mating season. It also shelters Verreaux's sifakas, Madame Berthe's mouse lemur (the world's smallest primate), giant jumping rats and three endemic baobab species.", "fr": "Cette forêt sèche décidue de 120 km² est le meilleur endroit pour observer le plus grand prédateur de Madagascar, le fossa — surtout pendant sa saison des amours en novembre. Elle abrite aussi les propithèques de Verreaux, le microcèbe de Mme Berthe (le plus petit primate du monde), des rats sauteurs géants et trois espèces de baobabs endémiques."}, "heading": {"en": "Kirindy Forest — Realm of the Fossa", "fr": "Forêt de Kirindy — Le royaume du fossa"}}, {"body": {"en": "A classic Malagasy adventure: 150 km over 2–3 days from Miandrivazo to Belo-sur-Tsiribihina, by pirogue or motorised barge, camping on sandbanks under starry skies. Savannahs, cliffs, baobab forests, lemurs and birdlife unfold, with the Anosin'Ampela waterfall and magical sunsets.", "fr": "Une aventure malgache classique : 150 km en 2 à 3 jours de Miandrivazo à Belo-sur-Tsiribihina, en pirogue ou barge à moteur, avec bivouac sur les bancs de sable sous un ciel étoilé. Savanes, falaises, forêts de baobabs, lémuriens et oiseaux se succèdent, avec la cascade d'Anosin'Ampela et des couchers de soleil magiques."}, "heading": {"en": "Tsiribihina River — A Journey by Water", "fr": "Fleuve Tsiribihina — Un voyage au fil de l'eau"}}, {"body": {"en": "Madagascar's most famous landmark: a 250 m stretch of Adansonia grandidieri near Morondava, with majestic trees over 30 m tall and more than 1,000 years old. Sunrise and sunset bathe the trunks in golden light, creating one of the island's most photogenic sights.", "fr": "Le site le plus célèbre de Madagascar : une allée de 250 m d'Adansonia grandidieri près de Morondava, aux arbres majestueux de plus de 30 m et vieux de plus de 1 000 ans. Lever et coucher de soleil baignent les troncs d'une lumière dorée, créant l'un des paysages les plus photogéniques de l'île."}, "heading": {"en": "Avenue of the Baobabs — Giants of Menabe", "fr": "Allée des Baobabs — Les géants du Menabe"}}, {"body": {"en": "South of Morondava, this 722 km² park merges dry forests, spiny thickets, mangroves, lakes, beaches, dunes and coral reefs. It shelters Verreaux's sifakas, ring-tailed lemurs, 58 birds, pink flamingos and rare Bernier's teal, with whales and reefs around offshore islets.", "fr": "Au sud de Morondava, ce parc de 722 km² réunit forêts sèches, fourrés épineux, mangroves, lacs, plages, dunes et récifs coralliens. Il abrite propithèques de Verreaux, makis catta, 58 oiseaux, flamants roses et la rare sarcelle de Bernier, avec baleines et récifs autour d'îlots au large."}, "heading": {"en": "Kirindy Mitea — Diversity by the Sea", "fr": "Kirindy Mitea — La diversité au bord de la mer"}}, {"body": {"en": "A tranquil coastal town of long beaches, Morondava is the hub for Bemaraha, Kirindy and the Baobab Avenue. Once a Sakalava kingdom capital, its heritage lives on in decorated royal tombs, raffia weaving, Sakalava wrestling and a lively seaside atmosphere.", "fr": "Ville côtière paisible aux longues plages, Morondava est le point de départ vers le Bemaraha, Kirindy et l'Allée des Baobabs. Ancienne capitale d'un royaume sakalava, son héritage vit à travers les tombeaux royaux décorés, le tissage du raphia, la lutte sakalava et une ambiance balnéaire animée."}, "heading": {"en": "Morondava — Coastal Gateway of Menabe", "fr": "Morondava — Porte côtière du Menabe"}}, {"body": {"en": "South of Morondava, this Vezo fishing village is famed for traditional boatbuilding, emerald lagoons and a white-sand beach. Surrounded by mangroves and palms, it offers snorkelling, coral-island cruises, whale watching (June–September) and visits to the Antsira salt works.", "fr": "Au sud de Morondava, ce village de pêcheurs vezo est réputé pour sa construction navale traditionnelle, ses lagons émeraude et sa plage de sable blanc. Entouré de mangroves et de palmiers, il offre snorkeling, croisières vers les îlots coralliens, observation des baleines (juin–septembre) et visite des salines d'Antsira."}, "heading": {"en": "Belo-sur-Mer — Vezo Fishing Heritage", "fr": "Belo-sur-Mer — Patrimoine des pêcheurs vezo"}}], "regionLabel": {"en": "Western Madagascar", "fr": "Grand Ouest"}}$MW$::jsonb) on conflict (slug) do update set region=excluded.region, sort=excluded.sort, content=excluded.content;
insert into public.destinations (slug, region, sort, content) values ('fort-dauphin-southern', 'south', 7, $MW${"slug": "fort-dauphin-southern", "image": "/images/destinations/fort-dauphin-southern-madagascar.webp", "title": {"en": "Fort Dauphin & the Deep South", "fr": "Fort-Dauphin & le Grand Sud"}, "region": "south", "excerpt": {"en": "Fort Dauphin's dramatic coasts, Berenty's lemurs, Ifotaka's sacred spiny forests, Lavanono's surf frontier and Cape Sainte Marie's tortoises — wild beauty and deep cultural roots.", "fr": "Les côtes spectaculaires de Fort-Dauphin, les lémuriens de Berenty, les forêts épineuses sacrées d'Ifotaka, la frontière du surf de Lavanono et les tortues du Cap Sainte-Marie — beauté sauvage et racines culturelles profondes."}, "sections": [{"body": {"en": "On a peninsula framed by the Indian Ocean and the Anosy mountains, Fort Dauphin blends beaches, mountains and culture. Libanona Beach draws surfers, while excursions reach Sainte Luce Reserve, Andohahela National Park (UNESCO) and Nahampoana Reserve, and Pic St. Louis rewards hikers with sweeping panoramas.", "fr": "Sur une presqu'île encadrée par l'océan Indien et les montagnes de l'Anosy, Fort-Dauphin mêle plages, montagnes et culture. La plage de Libanona attire les surfeurs, tandis que les excursions rejoignent la réserve de Sainte Luce, le parc national d'Andohahela (UNESCO) et la réserve de Nahampoana, et le Pic Saint-Louis récompense les randonneurs de vastes panoramas."}, "heading": {"en": "Fort Dauphin (Tolagnaro) — Gateway to the Southeast", "fr": "Fort-Dauphin (Tolagnaro) — Porte du Sud-Est"}}, {"body": {"en": "One of Madagascar's most famous private reserves (1936), set in a sisal plantation by the Mandrare River. Its gallery and spiny forests shelter ring-tailed lemurs, Verreaux's sifakas and flying foxes, with diverse birdlife. Comfortable bungalows and guided day and night walks make it a perfect first stop.", "fr": "L'une des plus célèbres réserves privées de Madagascar (1936), au cœur d'une plantation de sisal au bord du fleuve Mandrare. Ses forêts-galeries et épineuses abritent makis catta, propithèques de Verreaux et roussettes, avec une avifaune variée. Bungalows confortables et sorties guidées de jour comme de nuit en font une première étape idéale."}, "heading": {"en": "Berenty Reserve — Lemur Paradise", "fr": "Réserve de Berenty — Paradis des lémuriens"}}, {"body": {"en": "Spanning 22,000 hectares, Ifotaka preserves sacred spiny thickets and gallery forest — ring-tailed lemurs, sifakas, chameleons and 50+ birds, with owls and mouse lemurs on night walks. Deeply tied to Antandroy traditions, it offers zebu-cart rides, community chalets and authentic immersion.", "fr": "S'étendant sur 22 000 hectares, Ifotaka préserve fourrés épineux sacrés et forêt-galerie — makis catta, propithèques, caméléons et plus de 50 oiseaux, avec chouettes et microcèbes en marche nocturne. Profondément liée aux traditions antandroy, elle propose balades en charrette à zébu, chalets communautaires et immersion authentique."}, "heading": {"en": "Ifotaka Community Forest — Sacred Spiny Forest", "fr": "Forêt communautaire d'Ifotaka — Forêt épineuse sacrée"}}, {"body": {"en": "Remote and raw near Cape Sainte Marie, Lavanono is famed for perfect left-hand waves and unspoiled beauty. With strong trade winds (July–November), it is a paradise for surfing and kitesurfing — eco-lodges, fresh seafood, fireside music and passing whales in winter.", "fr": "Isolée et brute près du Cap Sainte-Marie, Lavanono est réputée pour ses vagues gauches parfaites et sa beauté préservée. Avec de forts alizés (juillet–novembre), c'est un paradis du surf et du kitesurf — éco-lodges, fruits de mer frais, musique au coin du feu et baleines de passage en hiver."}, "heading": {"en": "Lavanono — Surfers' Frontier", "fr": "Lavanono — La frontière des surfeurs"}}, {"body": {"en": "At Madagascar's southernmost tip, this reserve of windswept cliffs, dunes and spiny thickets holds one of the world's highest densities of radiated and spider tortoises. Humpback whales pass from June to October; sacred caves and fragments of elephant-bird eggs add archaeological intrigue.", "fr": "À la pointe la plus méridionale de Madagascar, cette réserve de falaises battues par les vents, de dunes et de fourrés épineux abrite l'une des plus fortes densités au monde de tortues radiées et araignées. Les baleines à bosse passent de juin à octobre ; grottes sacrées et fragments d'œufs d'oiseaux-éléphants ajoutent une intrigue archéologique."}, "heading": {"en": "Cape Sainte Marie — Where Oceans Meet", "fr": "Cap Sainte-Marie — Là où les océans se rencontrent"}}], "regionLabel": {"en": "Southern", "fr": "Sud"}}$MW$::jsonb) on conflict (slug) do update set region=excluded.region, sort=excluded.sort, content=excluded.content;

-- Témoignages (3) — on vide d'abord pour éviter les doublons
delete from public.testimonials;
insert into public.testimonials (sort, content) values (0, $MW${"quote": {"en": "TEST The most seamless, soulful trip we've ever taken. Our guide felt like family by the end.", "fr": "TEST Le voyage le plus fluide et le plus authentique que nous ayons fait. Notre guide était devenu une famille."}, "author": "Sophie & Marc", "origin": {"en": "France", "fr": "France"}}$MW$::jsonb);
insert into public.testimonials (sort, content) values (1, $MW${"quote": {"en": "Standing under the baobabs at sunset is something I'll never forget. Flawless organisation.", "fr": "Se tenir sous les baobabs au coucher du soleil, je ne l'oublierai jamais. Organisation parfaite."}, "author": "James T.", "origin": {"en": "United Kingdom", "fr": "Royaume-Uni"}}$MW$::jsonb);
insert into public.testimonials (sort, content) values (2, $MW${"quote": {"en": "They tailored everything to us — the lemurs, the beaches, the food. Pure magic.", "fr": "Tout a été taillé sur-mesure pour nous — les lémuriens, les plages, la cuisine. Pure magie."}, "author": "Anna K.", "origin": {"en": "Germany", "fr": "Allemagne"}}$MW$::jsonb);

-- Réglages (2)
insert into public.settings (id, content) values ('site', $MW${"url": "https://madaweaver-tour.vercel.app", "name": "Madaweaver Tour", "social": {"youtube": "#", "facebook": "#", "instagram": "#", "tripadvisor": "#"}, "contact": {"email": "harysrandrianomenjanahary@gmail.com", "address": "Lot II M 85 Bis, Antananarivo 101, Madagascar", "whatsapp": "261345301317", "phoneDisplay": "+261 34 53 013 17"}, "reviews": {"count": {"en": "based on 180+ reviews", "fr": "sur 180+ avis"}, "rating": {"en": "4.9/5", "fr": "4,9/5"}}, "tagline": {"en": "Weaving your finest journeys across Madagascar", "fr": "Tisser vos plus beaux voyages à Madagascar"}, "description": {"en": "Local travel agency in Madagascar. Tailor-made tours: baobabs, lemurs, tsingy, paradise beaches. Book your Malagasy adventure.", "fr": "Agence de voyage locale à Madagascar. Circuits sur-mesure : baobabs, lémuriens, tsingy, plages paradisiaques. Réservez votre aventure malgache."}}$MW$::jsonb) on conflict (id) do update set content=excluded.content;
insert into public.settings (id, content) values ('carrental', $MW${"intro": {"en": "Rent a reliable vehicle for your Madagascar trip — with or without a driver. Well-maintained 4×4s and cars, fair rates, and the local know-how to travel with peace of mind.", "fr": "Louez un véhicule fiable pour votre voyage à Madagascar — avec ou sans chauffeur. Des 4×4 et voitures bien entretenus, des tarifs justes, et le savoir-faire local pour rouler l'esprit tranquille."}, "title": {"en": "Car rental", "fr": "Location de voiture"}, "ctaText": {"en": "Tell us your dates and route — we'll send you a tailored quote.", "fr": "Dites-nous vos dates et votre itinéraire — nous vous envoyons un devis sur mesure."}, "options": [{"text": {"en": "A professional Malagasy driver who knows the roads, the routes and the language. Sit back and enjoy the journey in full safety.", "fr": "Un chauffeur malgache professionnel qui connaît les routes, les itinéraires et la langue. Détendez-vous et profitez du voyage en toute sécurité."}, "title": {"en": "With a driver", "fr": "Avec chauffeur"}}, {"text": {"en": "Prefer your own pace? Drive yourself with a well-maintained vehicle and our route advice. (Subject to conditions.)", "fr": "Vous préférez votre propre rythme ? Conduisez vous-même avec un véhicule bien entretenu et nos conseils d'itinéraire. (Sous conditions.)"}, "title": {"en": "Without a driver (self-drive)", "fr": "Sans chauffeur (en autonomie)"}}], "ctaTitle": {"en": "Need a vehicle for your trip?", "fr": "Besoin d'un véhicule pour votre voyage ?"}, "vehicles": [{"name": "4×4 Toyota Land Cruiser", "image": "https://hzltrhklbqdkasvazihg.supabase.co/storage/v1/object/public/media/uploads/1787382266331-70-series-LC.webp", "images": ["https://hzltrhklbqdkasvazihg.supabase.co/storage/v1/object/public/media/uploads/1787383105420-70-series-LC.webp", "https://hzltrhklbqdkasvazihg.supabase.co/storage/v1/object/public/media/uploads/1787383111080-LC.jpg"], "priceNote": {"en": "On request", "fr": "Sur demande"}, "description": {"en": "The reference for Madagascar's tracks — robust, comfortable, ideal for the RN7, Tsingy and remote routes.", "fr": "La référence sur les pistes de Madagascar — robuste, confortable, idéal pour la RN7, les Tsingy et les routes reculées."}, "priceWithDriver": "90$", "priceWithoutDriver": "70$"}], "heroImage": "https://hzltrhklbqdkasvazihg.supabase.co/storage/v1/object/public/media/uploads/1787383140302-70-series-LC.webp"}$MW$::jsonb) on conflict (id) do update set content=excluded.content;
